#!/usr/bin/env bash
# =============================================================================
#  CS2NEXUS  -  CS2 SERVER MANAGER / LAUNCHER  -  /opt/nexus.sh
#  CS2NEXUS-LAUNCHER (marker used by the launcher self-update check)
#  Ubuntu 22.04 | Counter-Strike 2 dedicated servers | tmux | JSON registry
#
#  Base installation (never modified) : /opt/cs2
#  Managed servers                    : /opt/cs2-servers/<slug>
#  Registry                           : /opt/cs2-servers/servers.json  (ARRAY)
#  Shared plugins                     : /opt/cs2-servers/shared        (see below)
#
#  Large game files are shared through symlinks. Each server gets its own
#  real copies of: cfg, addons, logs, the cs2.sh launcher and the small
#  bin/linuxsteamrt64/cs2 launcher binary.
#
#  Shared plugins: ONE copy in /opt/cs2-servers/shared/addons, symlinked into
#  every server (game/csgo/addons/...). Only counterstrikesharp/plugins/<X>
#  and metamod/plugins/<X> can be shared - never any core files.
#
#  Usage:
#    nexus                              interactive menu (nexus.sh)
#    nexus help                         non-interactive commands (cron/systemd)
# =============================================================================

set -u
set -o pipefail
# resolve our own path BEFORE changing directory (relative invocations like ./nexus.sh)
SELF=$(readlink -f -- "$0" 2>/dev/null || printf '%s' "$0")
readonly SELF
cd / || exit 1

# ------------------------------- Configuration -------------------------------
BASE="/opt/cs2"                       # may be changed by the setup wizard / config file
readonly SERVERS_DIR="/opt/cs2-servers"
readonly CONF_FILE="/etc/cs2nexus.conf"
readonly DB="$SERVERS_DIR/servers.json"
readonly CS2_USER="cs2"
readonly CS2_GROUP="cs2"
readonly CS2_HOME="/home/cs2"
readonly LOCK_FILE="/run/lock/server-cs2.lock"
readonly DEFAULT_MAP="de_dust2"
readonly MIN_PORT=1024
readonly MAX_PORT=65535
readonly MAX_CLIENTS=64
readonly STOP_TIMEOUT=20

# Shared plugins / extras
readonly SHARED_DIR="$SERVERS_DIR/shared"
readonly SHARED_ADDONS="$SHARED_DIR/addons"
readonly SHARED_DB="$SHARED_DIR/plugins.json"
readonly AUTOSTART_DB="$SHARED_DIR/autostart.json"
readonly BACKUP_DIR="$SHARED_DIR/backups"
readonly STATE_DIR="$SHARED_DIR/state"
readonly OPS_LOCK="/run/lock/server-cs2-ops.lock"
readonly BACKUP_KEEP=10
STEAMCMD="/usr/games/steamcmd"
readonly SETTINGS_DB="$SERVERS_DIR/shared/server-settings.json"
readonly PLUGIN_BACKUP_DIR="$SERVERS_DIR/shared/backups/plugins"
readonly PLUGIN_TIMER_UNIT="cs2nexus-plugin-update"
readonly CSS_TIMER_UNIT="cs2nexus-css-update"
readonly CSS_BACKUP_DIR="$SHARED_DIR/backups/counterstrikesharp"
readonly CSS_STATE_FILE="$STATE_DIR/counterstrikesharp-version"
readonly CSS_BACKUP_KEEP=5
readonly PLUGIN_BACKUP_KEEP=5
# Online sources (overridable for testing through environment variables)
GH_API="${CS2NEXUS_API:-https://api.github.com}"
MM_DROP="${CS2NEXUS_MM_DROP:-https://mms.alliedmods.net/mmsdrop/2.0}"
# Config-file values (see load_conf)
NEXUS_REPO="NEPENTII/CS2Nexus"
NEXUS_BRANCH="main"
EXTRA_PLUGIN_REPOS=""
GITHUB_TOKEN=""
AUTOUPDATE=0
CSS_AUTOUPDATE=1
UPDATE_ACTION="none"        # none | reload : what to do on running servers after a plugin update
# CS2Nexus default server settings (every new server starts with these; editable in Server settings -> DEFAULT)
CS2NEXUS_BASE_CVARS='{"mp_autoteambalance":0,"mp_limitteams":0,"mp_autokick":0,"mp_solid_teammates":1,"mp_warmup_items_nocost":1,"sv_alltalk":0,"sv_full_alltalk":0,"sv_talk_enemy_dead":0,"sv_talk_enemy_living":0,"sv_vote_issue_kick_allowed":0,"sv_vote_issue_changelevel_allowed":0,"sv_vote_issue_timeout_allowed":1,"mp_spectators_max":100,"sv_spec_hear":1,"sv_auto_full_alltalk_during_warmup_half_end":1,"mp_team_timeout_max":4,"mp_team_timeout_time":40}'
SETTINGS_DEFAULT_JSON='[{"id":0,"seed_v1":1,"cvars":{"mp_autoteambalance":0,"mp_limitteams":0,"mp_autokick":0,"mp_solid_teammates":1,"mp_warmup_items_nocost":1,"sv_alltalk":0,"sv_full_alltalk":0,"sv_talk_enemy_dead":0,"sv_talk_enemy_living":0,"sv_vote_issue_kick_allowed":0,"sv_vote_issue_changelevel_allowed":0,"sv_vote_issue_timeout_allowed":1,"mp_spectators_max":100,"sv_spec_hear":1,"sv_auto_full_alltalk_during_warmup_half_end":1,"mp_team_timeout_max":4,"mp_team_timeout_time":40},"features":{"team_balance":"off","force_pick_time":"off"},"launch":{"maxplayers":13,"map":"de_dust2","game_type":0,"game_mode":1},"custom":[],"plugins":{"mode":"all","local":[]}}]'
PREFLIGHT_MODE=menu
readonly STEAM_APPID=730
readonly WATCHDOG_UNIT="cs2-watchdog"
readonly WATCHDOG_MAX_RESTARTS=3
readonly WATCHDOG_WINDOW=600
# Allowed shared-plugin locations, relative to <server>/game/csgo/addons.
# Metamod note: many Metamod plugins are loaded through a .vdf file placed in
# addons/metamod/ and keep binaries elsewhere. Test before sharing them.
readonly -a PLUGIN_PREFIXES=("counterstrikesharp/plugins" "metamod/plugins")

# ------------------------------- Colors / UI ---------------------------------
if [[ -t 1 ]]; then
    RED=$'\033[1;31m'; GREEN=$'\033[1;32m'; YELLOW=$'\033[1;33m'
    BLUE=$'\033[1;34m'; CYAN=$'\033[1;36m'; BOLD=$'\033[1m'; RESET=$'\033[0m'
else
    RED=""; GREEN=""; YELLOW=""; BLUE=""; CYAN=""; BOLD=""; RESET=""
fi

# Informational messages go to MSGFD (2 while producing --json output).
MSGFD=1
ok()       { printf '%s[OK]%s %s\n'      "$GREEN"  "$RESET" "$*" >&"$MSGFD"; }
err()      { printf '%s[ERROR]%s %s\n'   "$RED"    "$RESET" "$*" >&2; }
warn()     { printf '%s[WARN]%s %s\n'    "$YELLOW" "$RESET" "$*" >&"$MSGFD"; }
info()     { printf '%s[INFO]%s %s\n'    "$BLUE"   "$RESET" "$*" >&"$MSGFD"; }
msg_skip() { printf '%s[SKIP]%s %s\n'    "$YELLOW" "$RESET" "$*" >&"$MSGFD"; }
msg_dry()  { printf '%s[DRY-RUN]%s %s\n' "$CYAN"   "$RESET" "$*" >&"$MSGFD"; }

sep()   { printf '%s----------------------------------------%s\n' "$CYAN" "$RESET"; }
dsep()  { printf '%s========================================%s\n' "$CYAN" "$RESET"; }
pause() { echo; read -r -p "Press Enter to continue..." _ || exit 0; }

clear_screen() { clear 2>/dev/null || printf '\033c'; }

header() {
    clear_screen
    dsep
    printf '%s%s%s\n' "$BOLD" "$(printf '%*s' $(( (40 + ${#1}) / 2 )) "$1")" "$RESET"
    dsep
    echo
}

trim() {
    local s=$1
    s="${s#"${s%%[![:space:]]*}"}"
    s="${s%"${s##*[![:space:]]}"}"
    printf '%s' "$s"
}

# normalize_map <input> -> MAP_NORM: "de_dust2" (normal map) or "workshop:<id>" (Workshop map).
# Accepts a map name, a bare Workshop ID, "workshop:ID" or a steamcommunity link with ?id=...
MAP_NORM=""
normalize_map() {
    local v re='[?&]id=([0-9]{5,12})([^0-9]|$)'
    MAP_NORM=""
    v=$(trim "$1")
    if [[ $v =~ ^workshop:([0-9]{5,12})$ ]]; then MAP_NORM="workshop:${BASH_REMATCH[1]}"
    elif [[ $v =~ ^[0-9]{5,12}$ ]]; then MAP_NORM="workshop:$v"
    elif [[ $v == *steamcommunity.com/* && $v =~ $re ]]; then MAP_NORM="workshop:${BASH_REMATCH[1]}"
    elif [[ $v =~ ^[A-Za-z0-9_]{1,64}$ ]]; then MAP_NORM=$v
    else return 1; fi
}
map_label() { if [[ $1 == workshop:* ]]; then printf 'Workshop map %s' "${1#workshop:}"; else printf '%s' "$1"; fi; }

# ask "Prompt" [default]  -> sets ANSWER ; returns 1 if user typed q (cancel)
ANSWER=""
ask() {
    local prompt=$1 def=${2:-} in
    if [[ -n $def ]]; then
        read -r -p "$prompt [$def]: " in || exit 0
        in=$(trim "$in"); in=${in:-$def}
    else
        read -r -p "$prompt: " in || exit 0
        in=$(trim "$in")
    fi
    if [[ $in == "q" || $in == "Q" ]]; then return 1; fi
    ANSWER=$in
    return 0
}

# confirm_yn "Prompt [Y/n]: " y|n   -> returns 0 for yes
confirm_yn() {
    local prompt=$1 def=$2 in
    read -r -p "$prompt" in || exit 0
    in=$(trim "${in,,}")
    [[ -z $in ]] && in=$def
    [[ $in == y || $in == yes ]]
}

restore_int_trap() { trap 'printf "\n"; exit 130' INT; }
restore_int_trap

# ------------------------------- Ops lock (re-entrant) -----------------------
# Serialises every read-modify-write of the JSON files and long operations
# (sync / update) between the menu, cron jobs and systemd timers.
# fd 8 is closed for tmux (see tmux_cs2) so it can never leak into servers.
OPS_DEPTH=0
lock_ops() {
    local t=${1:-30}
    if ((OPS_DEPTH == 0)); then
        exec 8>"$OPS_LOCK" || { err "Cannot open lock file $OPS_LOCK"; return 1; }
        if ((t == 0)); then
            flock -n 8 || { exec 8>&-; return 1; }
        elif ! flock -w "$t" 8; then
            exec 8>&-
            err "Another manager operation is in progress (lock busy). Try again shortly."
            return 1
        fi
    fi
    OPS_DEPTH=$((OPS_DEPTH + 1))
    return 0
}

unlock_ops() {
    if ((OPS_DEPTH > 0)); then OPS_DEPTH=$((OPS_DEPTH - 1)); fi
    if ((OPS_DEPTH == 0)); then exec 8>&-; fi
    return 0
}

# ------------------------------- Pre-flight ----------------------------------
SHARED_OK=1
AUTOSTART_OK=1

# repair_json_array <file> <label> <empty-json>
# Offers to repair a damaged registry (menu mode only). The damaged file is always
# kept as <file>.broken-<time>; servers.json is never touched by this helper.
repair_json_array() {
    local f=$1 label=$2 empty=$3 cand="" ts tmp head
    [[ $PREFLIGHT_MODE == menu ]] || return 1
    [[ -f $f ]] || return 1
    echo
    warn "The $label is damaged (it is not a JSON array): $f"
    head=$(head -c 160 -- "$f" 2>/dev/null | tr -d '\000-\010\013-\037' | tr '\n' ' ')
    info "Start of the file: ${head:-<empty>}"
    if [[ -z $(tr -d '[:space:]' <"$f" 2>/dev/null) ]]; then
        info "The file is empty."
    elif jq -e 'type=="object"' "$f" >/dev/null 2>&1; then
        cand=$(jq -c '[.[] | select(type=="array")] | if length == 1 then .[0] else empty end' "$f" 2>/dev/null)
        [[ -n $cand ]] && info "It is an object that wraps a list (for example {\"plugins\": [...]}); the list inside can be kept."
    fi
    if [[ -z $cand ]]; then
        cand=$empty
        info "It will be replaced by a fresh, empty registry."
    fi
    confirm_yn "Repair it now? A copy of the damaged file is kept next to it (.broken-...). [Y/n]: " y || return 1
    ts=$(date +%Y%m%d-%H%M%S)
    cp -p -- "$f" "$f.broken-$ts" || { err "Could not keep a copy of the damaged file."; return 1; }
    tmp=$(mktemp "$f.XXXXXX") || return 1
    printf '%s\n' "$cand" >"$tmp"
    if ! jq -e 'type=="array"' "$tmp" >/dev/null 2>&1; then rm -f -- "$tmp"; err "Repair failed."; return 1; fi
    chmod --reference="$f" -- "$tmp" 2>/dev/null
    mv -f -- "$tmp" "$f" || { rm -f -- "$tmp"; err "Repair failed."; return 1; }
    ok "Repaired. The damaged file was kept as $f.broken-$ts"
    return 0
}

init_shared() {
    install -d -m 755 -- "$SHARED_DIR" "$BACKUP_DIR" "$STATE_DIR" \
        || { err "Cannot create $SHARED_DIR"; exit 1; }
    install -d -m 755 -o "$CS2_USER" -g "$CS2_GROUP" -- "$SHARED_ADDONS" \
        || { err "Cannot create $SHARED_ADDONS"; exit 1; }
    # drop folders: anything placed here becomes a shared plugin automatically
    local pre
    for pre in "${PLUGIN_PREFIXES[@]}"; do
        install -d -m 755 -o "$CS2_USER" -g "$CS2_GROUP" -- \
            "$SHARED_ADDONS/${pre%%/*}" "$SHARED_ADDONS/$pre" \
            || { err "Cannot create $SHARED_ADDONS/$pre"; exit 1; }
    done

    if [[ ! -e $SHARED_DB && ! -L $SHARED_DB ]]; then
        echo "[]" >"$SHARED_DB" || { err "Cannot create $SHARED_DB"; exit 1; }
        chmod 644 "$SHARED_DB"
    fi
    if ! jq -e 'type=="array"' "$SHARED_DB" >/dev/null 2>&1; then
        if ! repair_json_array "$SHARED_DB" "plugin registry" "[]"; then
            SHARED_OK=0
            warn "$SHARED_DB is not a valid JSON array. Plugin features are disabled until it is fixed."
        fi
    fi

    if [[ ! -e $AUTOSTART_DB && ! -L $AUTOSTART_DB ]]; then
        echo "[]" >"$AUTOSTART_DB" || { err "Cannot create $AUTOSTART_DB"; exit 1; }
        chmod 644 "$AUTOSTART_DB"
    fi
    if ! jq -e 'type=="array"' "$AUTOSTART_DB" >/dev/null 2>&1; then
        if ! repair_json_array "$AUTOSTART_DB" "autostart list" "[]"; then
            AUTOSTART_OK=0
            warn "$AUTOSTART_DB is not a valid JSON array. Autostart/watchdog features are disabled until it is fixed."
        fi
    fi
}

# preflight [menu|cli]
preflight() {
    local mode=${1:-menu}
    PREFLIGHT_MODE=$mode
    if [[ $EUID -ne 0 ]]; then
        err "This manager must be run as root (use: sudo $0)."
        exit 1
    fi
    load_conf
    bootstrap_deps "$mode" || exit 1

    # Several terminals may have the menu open at the same time: every change to the JSON files and every long
    # operation (sync / update / install) takes the shared ops lock (lock_ops), so two menus cannot step on each other.

    if [[ ! -d $SERVERS_DIR ]]; then
        install -d -m 755 "$SERVERS_DIR" || { err "Cannot create $SERVERS_DIR"; exit 1; }
    fi
    if [[ ! -f $DB ]]; then
        echo "[]" >"$DB" || { err "Cannot create $DB"; exit 1; }
        chmod 644 "$DB"
    fi
    if ! jq -e 'type=="array"' "$DB" >/dev/null 2>&1; then
        err "$DB is not a valid JSON array. Fix or move it, then try again."
        exit 1
    fi

    # an existing installation (servers registered, CS2 files in place) skips the wizard
    if [[ $SETUP_DONE != 1 && $(jq 'length' "$DB") -gt 0 ]] && cs2_dir_ok "$BASE"; then
        info "Existing servers detected; marking the first-time setup as done."
        conf_set BASE "$BASE" && conf_set SETUP_DONE 1
    fi
    if [[ $SETUP_DONE != 1 && $mode != menu ]]; then
        err "CS2Nexus is not set up yet. Run the launcher once without arguments to start the setup wizard."
        exit 1
    fi

    if ! id "$CS2_USER" >/dev/null 2>&1; then
        if [[ $mode == menu && $SETUP_DONE != 1 ]]; then ensure_cs2_user || exit 1
        else err "Linux user '$CS2_USER' does not exist."; exit 1; fi
    fi
    init_shared
    init_settings

    if [[ $SETUP_DONE != 1 ]]; then
        run_setup_wizard || { err "Setup was not completed. Run the launcher again to retry."; exit 1; }
    elif ! cs2_dir_ok "$BASE"; then
        if [[ $mode == menu ]]; then
            warn "CS2 server files were not found in $BASE."
            run_setup_wizard || { err "Setup was not completed."; exit 1; }
        else
            err "CS2 server files not found in $BASE."; exit 1
        fi
    fi
    # CSS auto-updater is enabled by default. The timer is local to the launcher,
    # and its service only updates official CounterStrikeSharp files.
    if [[ $mode == menu && ${CSS_AUTOUPDATE:-1} == 1 ]]; then
        css_autoupdate_enable quiet || warn "CounterStrikeSharp auto-update timer could not be installed; open Maintenance -> CounterStrikeSharp updater."
    fi
}

# ------------------------------- JSON database -------------------------------
# Every JSON write: validate source -> rotating backup -> temp file in the same
# directory -> validate result -> atomic mv. Serialised by the ops lock.
backup_json() {
    local file=$1 base ts f n
    local -a all
    base=$(basename -- "$file")
    [[ -f $file ]] || return 0
    [[ -d $BACKUP_DIR ]] || mkdir -p -- "$BACKUP_DIR" 2>/dev/null || return 0
    ts=$(date +%Y%m%d-%H%M%S-%N)
    if ! cp -p -- "$file" "$BACKUP_DIR/$base.$ts" 2>/dev/null; then
        warn "Could not back up $file"
        return 0
    fi
    mapfile -t all < <(find "$BACKUP_DIR" -maxdepth 1 -type f -name "$base.*" -print \
        | grep -E "/${base//./\\.}\.[0-9]{8}-[0-9]{6}-[0-9]+\$" | sort)
    n=${#all[@]}
    if ((n > BACKUP_KEEP)); then
        for f in "${all[@]:0:n-BACKUP_KEEP}"; do rm -f -- "$f"; done
    fi
    return 0
}

_json_update_locked() {
    local file=$1; shift
    local dir base tmp
    dir=$(dirname -- "$file"); base=$(basename -- "$file")
    if ! jq -e 'type=="array"' "$file" >/dev/null 2>&1; then
        err "$file is not a valid JSON array; refusing to modify it."
        return 1
    fi
    backup_json "$file"
    tmp=$(mktemp "$dir/.$base.XXXXXX") || { err "mktemp failed"; return 1; }
    if jq "$@" "$file" >"$tmp" && jq -e 'type=="array"' "$tmp" >/dev/null 2>&1; then
        chmod --reference="$file" -- "$tmp" 2>/dev/null || chmod 644 "$tmp"
        mv -f -- "$tmp" "$file" || { rm -f -- "$tmp"; err "Cannot write $file"; return 1; }
    else
        rm -f -- "$tmp"
        err "Failed to update $file."
        return 1
    fi
}

# json_update <file> <jq args...> '<filter>'
json_update() {
    local file=$1 rc; shift
    lock_ops || return 1
    _json_update_locked "$file" "$@"; rc=$?
    unlock_ops
    return $rc
}

# db_update <jq args...> '<filter>'   (atomic write, same interface as before)
db_update()        { json_update "$DB" "$@"; }
shared_update()    { json_update "$SHARED_DB" "$@"; }
autostart_update() { json_update "$AUTOSTART_DB" "$@"; }

db_count()   { jq 'length' "$DB"; }
db_next_id() { jq '([.[].id] | max // 0) + 1' "$DB"; }

db_port_registered() { jq -e --argjson p "$1" 'any(.[]; .port == $p)' "$DB" >/dev/null 2>&1; }
db_name_taken() {
    jq -e --arg n "${1,,}" --arg s "$2" \
        'any(.[]; ((.name | ascii_downcase) == $n) or (.slug == $s))' "$DB" >/dev/null 2>&1
}

S_ID=""; S_NAME=""; S_SLUG=""; S_PORT=""; S_MAX=""; S_MAP=""; S_PATH=""
load_server() {
    local row id=$((10#$1))
    row=$(jq -r --argjson id "$id" \
        '.[] | select(.id == $id) | [.id,.name,.slug,.port,.maxplayers,.map,.path] | @tsv' "$DB") || return 1
    [[ -n $row ]] || return 1
    IFS=$'\t' read -r S_ID S_NAME S_SLUG S_PORT S_MAX S_MAP S_PATH <<<"$row"
}

# ------------------------------- Per-server state ----------------------------
# "manual stop" marker: the watchdog never restarts a server the admin stopped.
manual_stop_file() { printf '%s/manual-stop-%s' "$STATE_DIR" "$1"; }
mark_manual_stop() {
    mkdir -p -- "$STATE_DIR" 2>/dev/null
    : >"$(manual_stop_file "$1")" 2>/dev/null
    return 0
}
clear_manual_stop() { rm -f -- "$(manual_stop_file "$1")"; }
clear_server_state() {
    local id=$1
    rm -f -- "$STATE_DIR/manual-stop-$id" "$STATE_DIR/restarts-$id"
    if ((AUTOSTART_OK)) && jq -e --argjson id "$id" 'index($id) != null' "$AUTOSTART_DB" >/dev/null 2>&1; then
        autostart_update --argjson id "$id" 'map(select(. != $id))' >/dev/null
    fi
}

# ------------------------------- tmux / status -------------------------------
run_as_cs2() {
    runuser -u "$CS2_USER" -- env -u TMUX HOME="$CS2_HOME" USER="$CS2_USER" \
        LOGNAME="$CS2_USER" TERM="${TERM:-xterm}" "$@"
}
# lock descriptors are closed so the tmux server never inherits them
tmux_cs2()     { run_as_cs2 tmux "$@" 7>&- 8>&- 9>&-; }
session_name() { printf 'cs2-%s' "$1"; }
is_running()   { tmux_cs2 has-session -t "=$(session_name "$1")" >/dev/null 2>&1; }
status_of()    { if is_running "$1"; then echo ONLINE; else echo OFFLINE; fi; }

status_colored() {
    if [[ $1 == ONLINE ]]; then printf '%s%-8s%s' "$GREEN" "$1" "$RESET"
    else printf '%s%-8s%s' "$RED" "$1" "$RESET"; fi
}

# password_set <server-path> <server-id>: returns 0 when a join password is configured.
# Sources: the managed settings first (sv_password cvar of the server / DEFAULT entry),
# then server.cfg (a password that was set by hand). The last line wins, like in the game.
password_set() {
    local path=$1 id=$2 v cfg
    v=$(jq -r --argjson id "$id" '(first(.[] | select(.id == $id)) // {}).cvars.sv_password // ""' "$SETTINGS_DB" 2>/dev/null)
    if [[ -z $v ]]; then
        [[ -n $CSGOREL ]] || detect_layout >/dev/null 2>&1
        cfg="$path${CSGOREL:+/$CSGOREL}/cfg/server.cfg"
        if [[ -f $cfg && ! -L $cfg ]]; then
            v=$(grep -E '^[[:space:]]*sv_password[[:space:]]' "$cfg" 2>/dev/null | tail -n 1 \
                | sed -E 's/^[[:space:]]*sv_password[[:space:]]+//; s/[[:space:]]+$//; s/^"//; s/"$//')
        fi
    fi
    [[ -n $v ]]
}

# password_tag <server-path> <server-id>: prints " password" (yellow) right next to the
# ONLINE/OFFLINE status whenever the server has a join password.
password_tag() { if password_set "$@"; then printf '%s password%s' "$YELLOW" "$RESET"; fi; }

# ------------------------------- Port checks ---------------------------------
port_in_use() {
    ss -H -lntu 2>/dev/null | awk '{print $5}' | grep -Eq "[:.]${1}\$"
}

suggest_port() {
    local p
    for ((p = 27016; p <= 27200; p++)); do
        if ! db_port_registered "$p" && ! port_in_use "$p"; then echo "$p"; return; fi
    done
    echo 27016
}

# ------------------------------- Path safety ---------------------------------
# safe_server_path <path> <slug>
safe_server_path() {
    local p=$1 slug=$2
    [[ $slug =~ ^[a-z0-9]+(-[a-z0-9]+)*$ ]]        || return 1
    [[ $p == "$SERVERS_DIR/$slug" ]]                || return 1
    [[ $p != "$BASE" && $p != "/" && $p != "$SERVERS_DIR" && $p != "$SHARED_DIR" ]] || return 1
    [[ ! -L $p ]]                                   || return 1
    if [[ -e $p ]]; then
        [[ $(realpath -m -- "$p") == "$p" ]]        || return 1
    fi
    return 0
}

# ------------------------------- Server tree ---------------------------------
GAMEREL=""; CSGOREL=""; BINREL=""; BINPARENT=""; HAS_BIN=0
REAL_DIRS=()

rel_join() { if [[ -z $1 ]]; then printf '%s' "$2"; else printf '%s/%s' "$1" "$2"; fi; }
rel_parent() { if [[ $1 == */* ]]; then printf '%s' "${1%/*}"; else printf ''; fi; }

detect_layout() {
    if   [[ -f $BASE/game/cs2.sh ]]; then GAMEREL="game"
    elif [[ -f $BASE/cs2.sh ]];      then GAMEREL=""
    else
        err "Could not find cs2.sh in $BASE/game or $BASE."
        return 1
    fi
    CSGOREL=$(rel_join "$GAMEREL" csgo)
    BINPARENT=$(rel_join "$GAMEREL" bin)
    BINREL=$(rel_join "$GAMEREL" bin/linuxsteamrt64)
    if [[ ! -d $BASE/$CSGOREL ]]; then
        err "Base game content directory not found: $BASE/$CSGOREL"
        return 1
    fi

    REAL_DIRS=("")
    [[ -n $GAMEREL ]] && REAL_DIRS+=("$GAMEREL")
    REAL_DIRS+=("$CSGOREL")
    if [[ -f $BASE/$BINREL/cs2 ]]; then
        HAS_BIN=1
        REAL_DIRS+=("$BINPARENT" "$BINREL")
    else
        HAS_BIN=0
        warn "Launcher binary $BASE/$BINREL/cs2 not found; it will be symlinked."
    fi
    return 0
}

need_layout() { [[ -n $CSGOREL ]] || detect_layout; }

# Names that must NOT be symlinked inside real directory $1 (relative to BASE)
excludes_for() {
    local d=$1 r
    for r in "${REAL_DIRS[@]}"; do
        [[ -z $r || $r == "$d" ]] && continue
        [[ "$(rel_parent "$r")" == "$d" ]] && printf '%s\n' "${r##*/}"
    done
    [[ $d == "$GAMEREL" ]] && echo "cs2.sh"
    if [[ $d == "$CSGOREL" ]]; then printf '%s\n' cfg addons logs; fi
    if ((HAS_BIN)) && [[ $d == "$BINREL" ]]; then echo "cs2"; fi
    return 0
}

# link_missing <src> <dst> [excluded names...]
link_missing() {
    local src=$1 dst=$2; shift 2
    local e name x skip
    # drop dangling symlinks left over from removed base files
    find "$dst" -mindepth 1 -maxdepth 1 -xtype l -delete 2>/dev/null
    while IFS= read -r -d '' e; do
        name=${e##*/}
        skip=0
        for x in "$@"; do
            if [[ $x == "$name" ]]; then skip=1; break; fi
        done
        ((skip)) && continue
        if [[ -e $dst/$name || -L $dst/$name ]]; then continue; fi
        ln -s -- "$e" "$dst/$name" || { err "Failed to link $e"; return 1; }
    done < <(find "$src" -mindepth 1 -maxdepth 1 -print0)
}

# Copy launcher files (kept as real files so the engine resolves the SERVER's
# directory, not the base one). Refreshed automatically after base updates.
refresh_launchers() {
    local srv=$1 rel
    local files=("$(rel_join "$GAMEREL" cs2.sh)")
    ((HAS_BIN)) && files+=("$BINREL/cs2")
    for rel in "${files[@]}"; do
        if [[ ! -f $BASE/$rel ]]; then err "Missing base file: $BASE/$rel"; return 1; fi
        if [[ -L $srv/$rel ]] || [[ ! -f $srv/$rel ]] || ! cmp -s "$BASE/$rel" "$srv/$rel"; then
            rm -f -- "${srv:?}/$rel"
            cp -p -- "$BASE/$rel" "$srv/$rel" || { err "Failed to copy $rel"; return 1; }
        fi
        chmod +x "$srv/$rel"
    done
}

# Idempotent: builds/refreshes the symlink tree of a server directory
sync_server_tree() {
    local srv=$1 d src dst
    local -a ex
    detect_layout || return 1
    for d in "${REAL_DIRS[@]}"; do
        src="$BASE${d:+/$d}"
        dst="$srv${d:+/$d}"
        mkdir -p -- "$dst" || { err "Cannot create $dst"; return 1; }
        mapfile -t ex < <(excludes_for "$d")
        link_missing "$src" "$dst" "${ex[@]}" || return 1
    done
    refresh_launchers "$srv" || return 1
    chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$srv" || { err "chown failed on $srv"; return 1; }
    return 0
}

# Independent per-server content (only on creation)
seed_independent() {
    local srv=$1
    local csgo_base="$BASE/$CSGOREL" csgo_srv="$srv/$CSGOREL"

    if [[ -d $csgo_base/cfg ]]; then
        cp -a -- "$csgo_base/cfg" "$csgo_srv/cfg" || { err "Failed to copy cfg"; return 1; }
    else
        warn "Base cfg directory not found; creating an empty one."
        mkdir -p -- "$csgo_srv/cfg" || return 1
    fi

    if [[ -d $csgo_base/addons ]]; then
        cp -a -- "$csgo_base/addons" "$csgo_srv/addons" || { err "Failed to copy addons"; return 1; }
    else
        warn "Base addons directory not found; plugins will not be available."
        mkdir -p -- "$csgo_srv/addons" || return 1
    fi

    mkdir -p -- "$csgo_srv/logs" "$srv/logs" || return 1
}

# The CS2 game-mode configs (gamemode_competitive.cfg, gamemode_casual.cfg, ...) set
# mp_roundtime, mp_warmuptime, mp_freezetime, ... AFTER server.cfg has run, so those values
# would silently win. The same settings are therefore also written to the per-server
# gamemode_<mode>_server.cfg override files (our own files; no stock file is replaced) and to
# cs2nexus_settings.cfg, which "Apply now" executes on a running server.
GM_FILES=(casual competitive competitive2v2 deathmatch armsrace demolition workshop custom)
write_gamemode_overrides() {   # <server dir> <id>
    local srv=$1 id=$2 dir lines common g f glines
    dir="$srv/$CSGOREL/cfg"
    [[ -d $dir && ! -L $dir ]] || return 0
    lines=$(settings_cfg_lines "$id" 2>/dev/null)
    common=$(settings_user_lines "$id" 2>/dev/null)
    f="$dir/cs2nexus_settings.cfg"
    [[ -L $f ]] && rm -f -- "$f"
    { echo '// Written by CS2Nexus. Do not edit: use Server Settings.'; [[ -n $lines ]] && printf '%s\n' "$lines"; } >"$f"
    chown "$CS2_USER:$CS2_GROUP" -- "$f" 2>/dev/null
    for g in "${GM_FILES[@]}"; do
        f="$dir/gamemode_${g}_server.cfg"
        [[ -L $f ]] && continue
        if [[ -f $f ]]; then sed -i '/^\/\/ BEGIN CS2NEXUS-GAMEMODE$/,/^\/\/ END CS2NEXUS-GAMEMODE$/d' "$f"; fi
        glines=$({ settings_prefix_lines "$id" "$g" 2>/dev/null; [[ -n $common ]] && printf '%s\n' "$common"; })
        if [[ -n $glines ]]; then
            { echo '// BEGIN CS2NEXUS-GAMEMODE'; printf '%s\n' "$glines"; echo '// END CS2NEXUS-GAMEMODE'; } >>"$f"
            chown "$CS2_USER:$CS2_GROUP" -- "$f" 2>/dev/null
        elif [[ -f $f && ! -s $f ]]; then
            rm -f -- "$f"
        fi
    done
    return 0
}

write_server_cfg() {
    local srv=$1 name=$2 maxp=$3 port=$4 id=${5:-} gslt="" cfg
    need_layout || return 1
    cfg="$srv/$CSGOREL/cfg/server.cfg"
    [[ -L $cfg ]] && rm -f -- "$cfg"
    touch -- "$cfg" || { err "Cannot write $cfg"; return 1; }

    sed -i '/^\/\/ BEGIN CS2-MANAGER$/,/^\/\/ END CS2-MANAGER$/d' "$cfg" || return 1
    sed -i -E '/^[[:space:]]*hostname[[:space:]]/d' "$cfg" || return 1
    [[ -n $id ]] && gslt=$(launch_value "$id" gslt "")

    {
        echo '// BEGIN CS2-MANAGER'
        echo "hostname \"$name\""
        echo "sv_visiblemaxplayers $maxp"
        echo "tv_port $((port + 5))"
        echo "log on"
        echo "sv_logfile 1"
        [[ -n $gslt ]] && echo "sv_setsteamaccount \"$gslt\""
        [[ -n $id ]] && settings_cfg_lines "$id"
        echo '// END CS2-MANAGER'
    } >>"$cfg" || { err "Cannot append to $cfg"; return 1; }
    chown "$CS2_USER:$CS2_GROUP" -- "$cfg" || return 1
    [[ -n $gslt ]] && chmod 640 -- "$cfg"
    [[ -n $id ]] && write_gamemode_overrides "$srv" "$id"

    if sed '/^\/\/ BEGIN CS2-MANAGER$/,/^\/\/ END CS2-MANAGER$/d' "$cfg" | grep -Eq '^[[:space:]]*sv_setsteamaccount'; then
        warn "server.cfg contains a Steam GSLT token (sv_setsteamaccount) outside the managed block."
        warn "Each server needs its own token - edit: $cfg"
    fi
}

# =============================================================================
#  SHARED PLUGINS
# =============================================================================
DRY_RUN=0
SYNC_SKIPS=0
UNLINKED=0
CUR_PLUG=""
PLG_LOCALS=()
PLUGIN_REL=""
OPT_LOCAL_CSV="-"
OPT_EXCL_CSV="-"
OPT_INCL_CSV="-"

shared_db_ok() {
    ((SHARED_OK)) && return 0
    if repair_json_array "$SHARED_DB" "plugin registry" "[]"; then SHARED_OK=1; return 0; fi
    err "Shared plugin registry ($SHARED_DB) is not a valid JSON array."
    err "Fix or restore it (backups: $BACKUP_DIR), then try again."
    return 1
}

valid_simple_name() { [[ $1 =~ ^[A-Za-z0-9._+@-]+$ && $1 != . && $1 != .. ]]; }

# validate_plugin_rel <path> [quiet]  -> sets PLUGIN_REL
# Accepts ONLY <allowed-prefix>/<PLUGIN> (exactly one extra component).
validate_plugin_rel() {
    local p=$1 quiet=${2:-0} pre rest comp
    local -a comps
    PLUGIN_REL=""
    p=${p%/}
    if [[ -z $p ]]; then ((quiet)) || err "Path cannot be empty."; return 1; fi
    if [[ $p == /* ]]; then ((quiet)) || err "Absolute paths are not allowed."; return 1; fi
    if [[ ! $p =~ ^[A-Za-z0-9._+@-]+(/[A-Za-z0-9._+@-]+)*$ ]]; then
        ((quiet)) || err "Invalid characters in path (allowed: letters, digits, . _ + @ - and /)."
        return 1
    fi
    IFS=/ read -ra comps <<<"$p"
    for comp in "${comps[@]}"; do
        if [[ $comp == . || $comp == .. ]]; then
            ((quiet)) || err "'.' and '..' are not allowed in the path."
            return 1
        fi
    done
    for pre in "${PLUGIN_PREFIXES[@]}"; do
        if [[ $p == "$pre"/* ]]; then
            rest=${p#"$pre"/}
            if [[ -n $rest && $rest != */* ]]; then PLUGIN_REL=$p; return 0; fi
        fi
    done
    if ! ((quiet)); then
        err "Only single plugins can be shared: <prefix>/<PLUGIN> with prefix one of:"
        for pre in "${PLUGIN_PREFIXES[@]}"; do echo "    $pre"; done
    fi
    return 1
}

plugin_src_path() { printf '%s/%s' "$SHARED_ADDONS" "$1"; }

# shared_path_ok <path>: strictly inside shared/addons, no symlink components
shared_path_ok() {
    local p=$1 rp
    [[ $p == "$SHARED_ADDONS"/* ]] || return 1
    rp=$(realpath -m -- "$p") || return 1
    [[ $rp == "$p" ]] || return 1
    return 0
}

# ensure_chain <base> <target>: create missing directories below <base> down
# to <target>. Refuses to pass through symlinks. New dirs are owned by cs2.
ensure_chain() {
    local base=$1 target=$2 cur part
    local -a parts
    [[ $target == "$base" ]] && return 0
    [[ $target == "$base"/* ]] || return 1
    [[ -d $base && ! -L $base ]] || return 1
    cur=$base
    IFS=/ read -ra parts <<<"${target#"$base"/}"
    for part in "${parts[@]}"; do
        cur="$cur/$part"
        if [[ -L $cur ]]; then return 1; fi
        if [[ ! -d $cur ]]; then
            if [[ -e $cur ]]; then return 1; fi
            mkdir -- "$cur" || return 1
            chown "$CS2_USER:$CS2_GROUP" -- "$cur" || return 1
        fi
    done
    return 0
}

# paths_identical <shared-source> <local-copy>
paths_identical() {
    local a=$1 b=$2
    [[ -L $b ]] && return 1
    if [[ -f $a && -f $b ]]; then cmp -s -- "$a" "$b"; return; fi
    if [[ -d $a && -d $b ]]; then
        # a local copy that contains symlinks is never treated as identical
        [[ -z $(find "$b" -type l -print -quit 2>/dev/null) ]] || return 1
        diff -rq -- "$a" "$b" >/dev/null 2>&1
        return
    fi
    return 1
}

# Replace an identical real dir/file by a symlink (rename first, delete after).
replace_with_link() {
    local dst=$1 src=$2 old
    old="$dst.mgr-old.$$"
    [[ $old == "$SERVERS_DIR"/*/* ]] || return 1
    mv -T -- "$dst" "$old" || return 1
    if ! ln -s -- "$src" "$dst"; then
        mv -T -- "$old" "$dst"
        return 1
    fi
    chown -h "$CS2_USER:$CS2_GROUP" -- "$dst"
    rm -rf --one-file-system -- "$old"
    return 0
}

# drop_link <link> <target> <keep-copy 0|1>
# Removes a symlink after verifying it really is a symlink into shared/addons.
# keep=1 turns it into a real copy first, so the server keeps the plugin.
drop_link() {
    local link=$1 target=$2 keep=$3 tmp
    [[ -L $link ]] || return 1
    [[ $target == "$SHARED_ADDONS"/* ]] || return 1
    ((DRY_RUN)) && return 0
    if ((keep)) && [[ -e $link ]]; then
        tmp="$link.mgr-copy.$$"
        [[ $tmp == "$SERVERS_DIR"/*/* ]] || return 1
        if ! cp -a -- "$target" "$tmp"; then
            rm -rf --one-file-system -- "$tmp"
            return 1
        fi
        rm -f -- "$link" || { rm -rf --one-file-system -- "$tmp"; return 1; }
        mv -T -- "$tmp" "$link" || return 1
        chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$link"
    else
        rm -f -- "$link" || return 1
    fi
    return 0
}

# unlink_managed <dst> <shared-src> <keep>
# Removes ONLY symlinks that belong to <shared-src>. Real local files/dirs and
# foreign symlinks are never touched. Sets UNLINKED. Returns 1 on a failed check.
unlink_managed() {
    local dst=$1 src=$2 keep=${3:-0} t child
    UNLINKED=0
    if [[ -L $dst ]]; then
        t=$(readlink -- "$dst")
        if [[ $t == "$src" || $t == "$src"/* ]]; then
            if drop_link "$dst" "$t" "$keep"; then UNLINKED=1; else return 1; fi
        fi
        return 0
    fi
    [[ -d $dst ]] || return 0
    while IFS= read -r -d '' child; do
        t=$(readlink -- "$child")
        if [[ $t == "$src"/* ]]; then
            if drop_link "$child" "$t" "$keep"; then UNLINKED=$((UNLINKED + 1)); else return 1; fi
        fi
    done < <(find "$dst" -mindepth 1 -type l -print0)
    # tidy up only directories we just emptied by removing our own links;
    # directories that still hold real (per-server) files are never removed
    if ((!DRY_RUN && UNLINKED > 0)); then find "$dst" -depth -type d -empty -delete 2>/dev/null; fi
    return 0
}

# preport <ok|info|dry|warn|skip> [detail]  ->  "[LEVEL] SERVER -> PLUGIN (detail)"
preport() {
    local level=$1; shift
    local m="$S_NAME -> $CUR_PLUG${*:+ ($*)}"
    case $level in
        ok)   ok "$m" ;;
        info) info "$m" ;;
        dry)  msg_dry "$m" ;;
        warn) warn "$m" ;;
        skip) msg_skip "$m"; SYNC_SKIPS=$((SYNC_SKIPS + 1)) ;;
    esac
}

# --- whole-folder mode: one symlink for the plugin directory/file ---
sync_whole() {
    local src=$1 dst=$2 base=$3 t
    if [[ -L $dst ]]; then
        t=$(readlink -- "$dst")
        if [[ $t == "$src" ]]; then preport ok "already linked"; return 0; fi
        if [[ ! -e $dst || $t == "$SHARED_ADDONS"/* ]]; then
            if ((DRY_RUN)); then preport dry "would repair symlink"; return 0; fi
            if ln -sfT -- "$src" "$dst" && chown -h "$CS2_USER:$CS2_GROUP" -- "$dst"; then
                preport ok "repaired symlink"
            else
                preport skip "could not repair symlink"
            fi
            return 0
        fi
        warn "Symlink on $S_NAME points elsewhere: $t"
        preport skip "foreign symlink left untouched"
        return 0
    fi
    if [[ -e $dst ]]; then
        if paths_identical "$src" "$dst"; then
            if ((DRY_RUN)); then preport dry "would replace identical local copy with a symlink"; return 0; fi
            if replace_with_link "$dst" "$src"; then
                preport ok "identical local copy replaced by symlink"
            else
                preport skip "could not convert local copy"
            fi
            return 0
        fi
        warn "Existing local plugin differs on $S_NAME"
        preport skip "Not replacing local plugin"
        return 0
    fi
    if ((DRY_RUN)); then preport dry "would create symlink"; return 0; fi
    if ensure_chain "$base" "$(dirname -- "$dst")" \
        && ln -s -- "$src" "$dst" \
        && chown -h "$CS2_USER:$CS2_GROUP" -- "$dst"; then
        preport ok "linked"
    else
        preport skip "could not create symlink (parent path problem?)"
    fi
}

# --- split mode: REAL plugin directory whose children are symlinked into the
#     shared copy, except the per-server items in PLG_LOCALS (paths relative to
#     the plugin folder, e.g. "data/astra_skins.sqlite"). A directory that
#     contains such an item stays real and its other children are linked below it.
SPLIT_NEW=0; SPLIT_OK=0; SPLIT_FIX=0; SPLIT_BAD=0
local_exact()  { local l; for l in "${PLG_LOCALS[@]}"; do [[ $l == "$1" ]] && return 0; done; return 1; }
local_below()  { local l; for l in "${PLG_LOCALS[@]}"; do [[ $l == "$1"/* ]] && return 0; done; return 1; }

split_dir() {   # <src dir> <dst dir> <rel prefix> <dst exists 0|1> <base>
    local src=$1 dst=$2 pre=$3 have=$4 base=$5 child name rp cdst t
    while IFS= read -r -d '' child; do
        name=${child##*/}
        rp=${pre:+$pre/}$name
        local_exact "$rp" && continue
        cdst="$dst/$name"
        if [[ -d $child ]] && local_below "$rp"; then
            if ((!have)); then split_dir "$child" "$cdst" "$rp" 0 "$base"; continue; fi
            if [[ -L $cdst ]]; then
                t=$(readlink -- "$cdst")
                if [[ ! -e $cdst || $t == "$SHARED_ADDONS"/* ]]; then
                    if ((DRY_RUN)); then SPLIT_FIX=$((SPLIT_FIX + 1)); split_dir "$child" "$cdst" "$rp" 0 "$base"; continue; fi
                    rm -f -- "$cdst" || { SPLIT_BAD=$((SPLIT_BAD + 1)); continue; }
                else
                    warn "Foreign symlink on $S_NAME: $rp"; SPLIT_BAD=$((SPLIT_BAD + 1)); continue
                fi
            fi
            if [[ -e $cdst && ! -d $cdst ]]; then warn "A file blocks $rp on $S_NAME"; SPLIT_BAD=$((SPLIT_BAD + 1)); continue; fi
            if [[ ! -d $cdst ]]; then
                if ((DRY_RUN)); then split_dir "$child" "$cdst" "$rp" 0 "$base"; continue; fi
                ensure_chain "$base" "$cdst" || { SPLIT_BAD=$((SPLIT_BAD + 1)); continue; }
            fi
            split_dir "$child" "$cdst" "$rp" 1 "$base"
            continue
        fi
        if ((!have)); then SPLIT_NEW=$((SPLIT_NEW + 1)); continue; fi
        if [[ -L $cdst ]]; then
            t=$(readlink -- "$cdst")
            if [[ $t == "$child" ]]; then
                SPLIT_OK=$((SPLIT_OK + 1))
            elif [[ ! -e $cdst || $t == "$SHARED_ADDONS"/* ]]; then
                if ((DRY_RUN)); then SPLIT_FIX=$((SPLIT_FIX + 1))
                elif ln -sfT -- "$child" "$cdst" && chown -h "$CS2_USER:$CS2_GROUP" -- "$cdst"; then SPLIT_FIX=$((SPLIT_FIX + 1))
                else SPLIT_BAD=$((SPLIT_BAD + 1)); fi
            else
                warn "Foreign symlink on $S_NAME: $rp"; SPLIT_BAD=$((SPLIT_BAD + 1))
            fi
        elif [[ -e $cdst ]]; then
            if paths_identical "$child" "$cdst"; then
                if ((DRY_RUN)); then SPLIT_FIX=$((SPLIT_FIX + 1))
                elif replace_with_link "$cdst" "$child"; then SPLIT_FIX=$((SPLIT_FIX + 1))
                else SPLIT_BAD=$((SPLIT_BAD + 1)); fi
            else
                warn "Existing local item differs on $S_NAME: $rp"; SPLIT_BAD=$((SPLIT_BAD + 1))
            fi
        else
            if ((DRY_RUN)); then SPLIT_NEW=$((SPLIT_NEW + 1))
            elif ln -s -- "$child" "$cdst" && chown -h "$CS2_USER:$CS2_GROUP" -- "$cdst"; then SPLIT_NEW=$((SPLIT_NEW + 1))
            else SPLIT_BAD=$((SPLIT_BAD + 1)); fi
        fi
    done < <(find "$src" -mindepth 1 -maxdepth 1 -print0)
}

sync_split() {
    local src=$1 dst=$2 base=$3 t child lc have_dir=1
    SPLIT_NEW=0; SPLIT_OK=0; SPLIT_FIX=0; SPLIT_BAD=0

    if [[ -L $dst ]]; then
        t=$(readlink -- "$dst")
        if [[ ! -e $dst || $t == "$SHARED_ADDONS"/* ]]; then
            have_dir=0
            warn "Converting whole-folder link to per-item links on $S_NAME (data written through the old link stays in shared storage)."
            if ! ((DRY_RUN)); then
                rm -f -- "$dst" || { preport skip "cannot replace symlink with a directory"; return 0; }
            fi
        else
            warn "Symlink on $S_NAME points elsewhere: $t"
            preport skip "foreign symlink left untouched"
            return 0
        fi
    elif [[ -e $dst && ! -d $dst ]]; then
        warn "A file blocks the plugin directory on $S_NAME"
        preport skip "not a directory"
        return 0
    elif [[ ! -d $dst ]]; then
        have_dir=0
    fi
    if ((!have_dir && !DRY_RUN)); then
        ensure_chain "$base" "$dst" || { preport skip "cannot create plugin directory"; return 0; }
        have_dir=1
    fi

    split_dir "$src" "$dst" "" "$have_dir" "$base"

    # remove dangling links that used to point into this shared plugin
    if ((have_dir)) && [[ -d $dst ]]; then
        while IFS= read -r -d '' child; do
            t=$(readlink -- "$child")
            if [[ $t == "$src"/* && ! -e $child ]]; then
                if ((DRY_RUN)); then SPLIT_FIX=$((SPLIT_FIX + 1))
                elif rm -f -- "$child"; then SPLIT_FIX=$((SPLIT_FIX + 1)); fi
            fi
        done < <(find "$dst" -mindepth 1 -type l -print0)
    fi

    lc=$(IFS=,; printf '%s' "${PLG_LOCALS[*]}")
    if ((SPLIT_BAD > 0)); then preport skip "$SPLIT_BAD item(s) not replaced (differ locally / foreign)"; fi
    if ((DRY_RUN)); then
        preport dry "would link $SPLIT_NEW new, fix $SPLIT_FIX; per-server kept: $lc"
    else
        preport ok "linked $SPLIT_NEW, fixed $SPLIT_FIX, unchanged $SPLIT_OK; per-server kept: $lc"
    fi
}

_sync_plugin_inner() {
    local pname=$1 rel=$2 lcsv=$3 xcsv=$4 icsv=${5:--}
    local src dst base l excluded=0
    CUR_PLUG=$pname
    PLG_LOCALS=()
    if [[ $lcsv != "-" ]]; then IFS=, read -ra PLG_LOCALS <<<"$lcsv"; fi
    for l in "${PLG_LOCALS[@]}"; do
        if ! valid_local_path "$l"; then preport skip "invalid per-server path in registry: $l"; return 0; fi
    done
    [[ ,$xcsv, == *",$S_ID,"* ]] && excluded=1
    if [[ $icsv != "-" && ,$icsv, != *",$S_ID,"* ]]; then excluded=1; fi

    src=$(plugin_src_path "$rel")
    base="$S_PATH/$CSGOREL"
    dst="$base/addons/$rel"

    if ! safe_server_path "$S_PATH" "$S_SLUG"; then
        preport skip "unsafe or inconsistent server path in database"; return 0
    fi
    if [[ ! -d $base || -L $base ]]; then
        preport skip "server directory $CSGOREL is missing"; return 0
    fi
    if ! shared_path_ok "$src"; then
        preport skip "unsafe shared path"; return 0
    fi

    if ((excluded)); then
        if ! unlink_managed "$dst" "$src" 0; then
            preport skip "not assigned, but removing the managed link failed"; return 0
        fi
        if ((UNLINKED)); then
            if ((DRY_RUN)); then preport dry "not assigned: would remove managed link"
            else preport ok "not assigned to this server: managed link removed"; fi
        else
            preport info "not assigned to this server"
        fi
        return 0
    fi

    if [[ ! -e $src && ! -L $src ]]; then
        preport skip "shared source is missing ($src)"; return 0
    fi

    if ((${#PLG_LOCALS[@]})) && [[ -d $src ]]; then
        sync_split "$src" "$dst" "$base"
    else
        sync_whole "$src" "$dst" "$base"
    fi
}

# sync_plugin_on_server <name> <rel> <local-csv|-> <exclude-csv|->
# Uses the loaded S_* server. Returns 1 if anything was skipped.
sync_plugin_on_server() {
    local before=$SYNC_SKIPS
    _sync_plugin_inner "$@"
    [[ $SYNC_SKIPS -eq $before ]]
}

# name<TAB>path<TAB>local-csv|-<TAB>exclude-csv|-
plugins_rows() {
    jq -r '.[] | select(type=="object") | [
        ((.name // "-") | tostring),
        ((.path // "-") | tostring),
        ((.local // []) | if type=="array" and length>0 then map(tostring)|join(",") else "-" end),
        ((.exclude // []) | if type=="array" and length>0 then map(tostring)|join(",") else "-" end),
        ((.include // []) | if type=="array" and length>0 then map(tostring)|join(",") else "-" end)
    ] | @tsv' "$SHARED_DB"
}

# =============================================================================
#  WEAPONPAINTS (replaces AstraSkins): ONE plugin, ONE config, ONE MySQL/MariaDB database for EVERY server
#  - the plugin folder is the shared one (no per-server data folder)
#  - configs/plugins/WeaponPaints on every server is a link to shared/configs/WeaponPaints
#  - it needs the libraries PlayerSettings, AnyBaseLib and MenuManager: installed together with it
#  - database login lives in shared/weaponpaints-db.json and is written into the plugin config
#  - players choose their skins on the WeaponPaints website (PHP) or with !knife / !skins in game
#  Runs automatically with every plugin sync. Package source: GitHub releases (no API, so no rate limit).
# =============================================================================
readonly WP_NAME="WeaponPaints"
readonly WP_CFG_SHARED="$SHARED_DIR/configs/$WP_NAME"
readonly WP_DB_FILE="$SHARED_DIR/weaponpaints-db.json"
readonly WP_CACHE="$SHARED_DIR/wp-cache"
readonly WP_WEB_DIR="/opt/cs2-weaponpaints-web"
readonly WP_GAMEDATA_URL="https://raw.githubusercontent.com/Nereziel/cs2-WeaponPaints/main/gamedata/weaponpaints.json"
readonly -a WP_PKGS=(
    "Nereziel/cs2-WeaponPaints|WeaponPaints.zip"
    "NickFox007/PlayerSettingsCS2|PlayerSettings.zip"
    "NickFox007/AnyBaseLibCS2|AnyBaseLib.zip"
    "NickFox007/MenuManagerCS2|MenuManager.zip"
)
WP_NEEDS_RESTART=0

wp_rel() { jq -r --arg n "$WP_NAME" '[.[] | select(type=="object" and .name == $n)][0].path // empty' "$SHARED_DB" 2>/dev/null; }

# registry: no per-server split, no include/exclude -> every server uses the one shared copy
wp_prepare_registry() {
    ((SHARED_OK)) || return 0
    jq -e --arg n "$WP_NAME" 'any(.[]; type=="object" and .name == $n and (((.local // []) | length) > 0 or ((.include // []) | length) > 0))' "$SHARED_DB" >/dev/null 2>&1 || return 0
    ((DRY_RUN)) && return 0
    if shared_update --arg n "$WP_NAME" 'map(if type=="object" and .name == $n then del(.local, .include) else . end)' >/dev/null; then
        info "$WP_NAME is now shared by ALL servers (per-server data / exclusions removed)."
    fi
    return 0
}

# ---------------------------------- database ---------------------------------
wp_db_file_ok() {
    [[ -s $WP_DB_FILE ]] || return 1
    jq -e 'type=="object" and ((.host // "")|tostring|length>0) and ((.user // "")|tostring|length>0) and ((.name // "")|tostring|length>0) and ((.password // null)|type=="string")' "$WP_DB_FILE" >/dev/null 2>&1
}
wp_db_get() { jq -r --arg k "$1" '(.[$k] // empty) | tostring' "$WP_DB_FILE" 2>/dev/null; }
wp_sql_bin() { command -v mariadb 2>/dev/null || command -v mysql 2>/dev/null; }

wp_db_write_file() {   # <host> <port> <user> <password> <name> [website]
    local tmp web=${6:-}
    [[ -z $web && -s $WP_DB_FILE ]] && web=$(wp_db_get website)
    install -d -m 755 -o "$CS2_USER" -g "$CS2_GROUP" -- "$SHARED_DIR" 2>/dev/null
    tmp=$(mktemp "$SHARED_DIR/.wpdb.XXXXXX") || return 1
    jq -n --arg h "$1" --argjson p "$2" --arg u "$3" --arg pw "$4" --arg n "$5" --arg w "$web" \
        '{host:$h, port:$p, user:$u, password:$pw, name:$n, website:$w}' >"$tmp" \
        && chown "$CS2_USER:$CS2_GROUP" -- "$tmp" && chmod 640 -- "$tmp" && mv -f -- "$tmp" "$WP_DB_FILE" \
        || { rm -f -- "$tmp"; return 1; }
}

wp_db_test() {   # <host> <port> <user> <password> <name>
    local bin; bin=$(wp_sql_bin) || return 2
    MYSQL_PWD="$4" "$bin" --connect-timeout=8 -h "$1" -P "$2" -u "$3" -N -e 'SELECT 1' "$5" >/dev/null 2>&1
}

# patch the one shared plugin config with the database login (keys matched case-insensitively)
wp_patch_config() {
    local f="$WP_CFG_SHARED/$WP_NAME.json" new tmp
    [[ -f $f ]] || return 1
    wp_db_file_ok || return 1
    new=$(jq --slurpfile d "$WP_DB_FILE" 'def ci($n): ((keys_unsorted | map(select(ascii_downcase == ($n | ascii_downcase))) | .[0]) // $n);
        if type != "object" then error("not an object") else . end
        | ($d[0]) as $c
        | .[ci("DatabaseHost")] = $c.host
        | .[ci("DatabasePort")] = ($c.port | tonumber)
        | .[ci("DatabaseUser")] = $c.user
        | .[ci("DatabasePassword")] = $c.password
        | .[ci("DatabaseName")] = $c.name
        | if (($c.website // "") | length) > 0 then .[ci("Website")] = $c.website else . end' "$f" 2>/dev/null) \
        || { warn "$WP_NAME.json is not valid JSON; not touched: $f"; return 1; }
    if [[ $(jq -S . "$f" 2>/dev/null) == "$(jq -S . <<<"$new")" ]]; then return 0; fi
    ((DRY_RUN)) && return 0
    tmp="$f.tmp.$$"
    printf '%s\n' "$new" >"$tmp" && chown "$CS2_USER:$CS2_GROUP" -- "$tmp" && chmod 640 -- "$tmp" && mv -f -- "$tmp" "$f" || { rm -f -- "$tmp"; return 1; }
    ok "$WP_NAME config: database login written (shared by all servers)."
    WP_NEEDS_RESTART=1
    return 0
}

wp_db_local_setup() {
    local bin pw i name="cs2nexus_wp" user="cs2nexus_wp" port=3306
    if ! command -v mariadbd >/dev/null 2>&1 && ! command -v mysqld >/dev/null 2>&1; then
        info "Installing the MariaDB server (apt) ..."
        DEBIAN_FRONTEND=noninteractive apt-get install -y mariadb-server mariadb-client >/dev/null 2>&1 \
            || { err "Could not install MariaDB (apt-get failed). Install it by hand, then use the external-database option."; return 1; }
    fi
    systemctl enable --now mariadb >/dev/null 2>&1 || systemctl enable --now mysql >/dev/null 2>&1 || true
    wp_mariadb_light
    bin=$(wp_sql_bin) || { err "No mysql/mariadb client was found."; return 1; }
    for ((i = 0; i < 10; i++)); do "$bin" -e 'SELECT 1' >/dev/null 2>&1 && break; sleep 2; done
    "$bin" -e 'SELECT 1' >/dev/null 2>&1 || { err "The database server does not answer (as root over the local socket)."; return 1; }
    if wp_db_file_ok && [[ $(wp_db_get user) == "$user" && $(wp_db_get host) == "127.0.0.1" ]]; then pw=$(wp_db_get password); port=$(wp_db_get port); fi
    [[ ${pw:-} =~ ^[A-Za-z0-9]{24}$ ]] || pw=$(LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom | head -c 24)
    [[ $port =~ ^[0-9]+$ ]] || port=3306
    "$bin" <<SQL || { err "Creating the database / user failed."; return 1; }
CREATE DATABASE IF NOT EXISTS \`$name\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER IF NOT EXISTS '$user'@'localhost' IDENTIFIED BY '$pw';
CREATE USER IF NOT EXISTS '$user'@'127.0.0.1' IDENTIFIED BY '$pw';
ALTER USER '$user'@'localhost' IDENTIFIED BY '$pw';
ALTER USER '$user'@'127.0.0.1' IDENTIFIED BY '$pw';
GRANT ALL PRIVILEGES ON \`$name\`.* TO '$user'@'localhost';
GRANT ALL PRIVILEGES ON \`$name\`.* TO '$user'@'127.0.0.1';
FLUSH PRIVILEGES;
SQL
    if ! wp_db_test 127.0.0.1 "$port" "$user" "$pw" "$name"; then
        err "The new database user cannot log in over TCP 127.0.0.1:$port (is 'skip-networking' enabled in the MariaDB config?)."; return 1
    fi
    wp_db_write_file 127.0.0.1 "$port" "$user" "$pw" "$name" || { err "Could not write $WP_DB_FILE"; return 1; }
    ok "Local database ready: $name (user $user, 127.0.0.1:$port). Login stored in $WP_DB_FILE"
    wp_patch_config || true
    WP_NEEDS_RESTART=1
    return 0
}

wp_db_external_setup() {
    local host port user pw name
    info "Use a MySQL / MariaDB server that already exists (the user needs full rights on the database)."
    ask "Host" "$( wp_db_file_ok && wp_db_get host || echo 127.0.0.1)" || return 1; host=$ANSWER
    ask "Port" "$( wp_db_file_ok && wp_db_get port || echo 3306)" || return 1; port=$ANSWER
    ask "Database name" "$( wp_db_file_ok && wp_db_get name || echo cs2nexus_wp)" || return 1; name=$ANSWER
    ask "User" "$( wp_db_file_ok && wp_db_get user || true)" || return 1; user=$ANSWER
    read -r -s -p "Password: " pw || return 1; echo
    if [[ ! $host =~ ^[A-Za-z0-9._:-]+$ || ! $port =~ ^[0-9]{1,5}$ || ! $name =~ ^[A-Za-z0-9_]+$ || ! $user =~ ^[A-Za-z0-9_.@-]+$ || -z $pw ]]; then
        err "Invalid value (host/port/name/user use plain characters only; the password cannot be empty)."; return 1
    fi
    wp_sql_bin >/dev/null 2>&1 || { info "Installing the MariaDB client ..."; DEBIAN_FRONTEND=noninteractive apt-get install -y mariadb-client >/dev/null 2>&1 || true; }
    if ! wp_db_test "$host" "$port" "$user" "$pw" "$name"; then
        err "Login failed (wrong data, database missing, or the server blocks this machine)."
        confirm_yn "Save it anyway? [y/N]: " n || return 1
    fi
    wp_db_write_file "$host" "$port" "$user" "$pw" "$name" || { err "Could not write $WP_DB_FILE"; return 1; }
    ok "Database login saved."
    wp_patch_config || true
    WP_NEEDS_RESTART=1
    return 0
}

wp_db_status() {
    local good=0
    if ! wp_db_file_ok; then warn "No database is configured yet (menu: WeaponPaints -> database)."; return 1; fi
    info "Database: $(wp_db_get user)@$(wp_db_get host):$(wp_db_get port) / $(wp_db_get name)"
    if wp_db_test "$(wp_db_get host)" "$(wp_db_get port)" "$(wp_db_get user)" "$(wp_db_get password)" "$(wp_db_get name)"; then ok "Login works."; good=1
    else err "Login does not work (or the mysql/mariadb client is missing)."; fi
    [[ -f $WP_CFG_SHARED/$WP_NAME.json ]] && { wp_patch_config >/dev/null 2>&1; info "Plugin config is in sync with this login."; } \
        || info "The plugin config does not exist yet: start a server once with the plugin installed."
    ((good))
}

# ------------------------------ website (PHP) --------------------------------
wp_web_install() {
    local tag url tmp grp cfg
    wp_db_file_ok || { err "Set up the database first."; return 1; }
    command -v unzip >/dev/null 2>&1 || { err "unzip is not installed."; return 1; }
    tag=$(wp_latest_tag "Nereziel/cs2-WeaponPaints")
    [[ $tag =~ ^[A-Za-z0-9._+-]{1,64}$ ]] || { err "Could not read the latest WeaponPaints release."; return 1; }
    tmp=$(mktemp -d /tmp/cs2nexus-wpweb.XXXXXX) || return 1
    url="https://github.com/Nereziel/cs2-WeaponPaints/releases/download/$tag/WeaponPaints-Website.zip"
    if ! curl -fsSL --retry 3 --connect-timeout 15 --max-time 300 -o "$tmp/web.zip" "$url" || ! unzip -qo "$tmp/web.zip" -d "$tmp/x"; then
        err "Download of the website package failed."; rm -rf --one-file-system -- "$tmp"; return 1
    fi
    [[ -f $tmp/x/website/class/config.php ]] || { err "Unexpected website package layout."; rm -rf --one-file-system -- "$tmp"; return 1; }
    install -d -m 755 -- "$WP_WEB_DIR"
    rm -rf --one-file-system -- "$WP_WEB_DIR/website"
    cp -a -- "$tmp/x/website" "$WP_WEB_DIR/website" || { err "Copy failed."; rm -rf --one-file-system -- "$tmp"; return 1; }
    rm -rf --one-file-system -- "$tmp"
    cfg="$WP_WEB_DIR/website/class/config.php"
    # write the database login; the Steam API key and domain are filled in by the owner
    sed -i -E \
        -e "s|define\('DB_HOST', '[^']*'\);|define('DB_HOST', '$(wp_db_get host)');|" \
        -e "s|define\('DB_PORT', '[^']*'\);|define('DB_PORT', '$(wp_db_get port)');|" \
        -e "s|define\('DB_NAME', '[^']*'\);|define('DB_NAME', '$(wp_db_get name)');|" \
        -e "s|define\('DB_USER', '[^']*'\);|define('DB_USER', '$(wp_db_get user)');|" \
        -e "s|define\('DB_PASS', '[^']*'\);|define('DB_PASS', '$(wp_db_get password)');|" "$cfg"
    grp=root; getent group www-data >/dev/null 2>&1 && grp=www-data
    chown -R "root:$grp" -- "$WP_WEB_DIR"; chmod 640 -- "$cfg"
    ok "Website files: $WP_WEB_DIR/website  (release $tag)"
    echo "  Next steps:"
    echo "   1) apt install php-fpm php-mysql php-curl   (PHP 7.4 or newer)"
    echo "   2) Edit $cfg and fill STEAM_API_KEY (https://steamcommunity.com/dev/apikey), STEAM_DOMAIN_NAME,"
    echo "      STEAM_LOGIN_PAGE and STEAM_LOGOUT_PAGE (your site address)."
    echo "   3) Point nginx/Apache at $WP_WEB_DIR/website with PHP enabled."
    echo "   4) Players open it with !ws in game. The tables are created by the plugin, so start a server first."
    return 0
}

# ------------------------------ package install ------------------------------
wp_latest_tag() {   # <owner/repo> -> tag of the latest release (read from the redirect, no API calls)
    curl -fsSI -m 25 --retry 2 "https://github.com/$1/releases/latest" 2>/dev/null | tr -d '\r' \
        | awk 'tolower($1)=="location:"{n=split($2,a,"/"); print a[n]; exit}'
}

# wp_install [quiet 0|1] [force 0|1]: WeaponPaints + PlayerSettings + AnyBaseLib + MenuManager
# plugins -> shared plugin folder (linked into every server); libraries/gamedata -> cache, copied per server at sync
wp_install() {
    local quiet=${1:-0} force=${2:-0} entry repo asset base tag cur url tmp x csd d name pdst rc=0 changed=0 pk_ok id running=0
    local vf="$WP_CACHE/versions.json"
    ((SHARED_OK)) || { err "Shared plugins are not set up yet (finish the launcher setup first)."; return 1; }
    [[ -d $SHARED_ADDONS ]] || { err "The shared plugin folder does not exist yet."; return 1; }
    command -v unzip >/dev/null 2>&1 || { err "unzip is not installed."; return 1; }
    need_layout || return 1
    lock_ops 30 || { err "Another operation is running; try again in a minute."; return 1; }
    install -d -m 755 -o "$CS2_USER" -g "$CS2_GROUP" -- "$WP_CACHE" "$WP_CACHE/shared" "$WP_CACHE/gamedata" "$SHARED_ADDONS/counterstrikesharp/plugins"
    if ! { [[ -s $vf ]] && jq -e 'type=="object"' "$vf" >/dev/null 2>&1; }; then printf '{}\n' >"$vf"; fi
    tmp=$(mktemp -d /tmp/cs2nexus-wp.XXXXXX) || { unlock_ops; return 1; }
    for entry in "${WP_PKGS[@]}"; do
        repo=${entry%%|*}; asset=${entry##*|}; base=${asset%.zip}
        tag=$(wp_latest_tag "$repo")
        if ! [[ $tag =~ ^[A-Za-z0-9._+-]{1,64}$ ]]; then
            err "$base: could not read the latest release of github.com/$repo (offline or blocked?)."; rc=1; continue
        fi
        cur=$(jq -r --arg k "$base" '.[$k] // ""' "$vf")
        if ((!force)) && [[ $cur == "$tag" && -e $WP_CACHE/.ok-$base ]]; then
            ((quiet)) || ok "$base $tag: already installed."
            continue
        fi
        ((quiet)) || info "Downloading $base $tag ..."
        x="$tmp/$base"; mkdir -p -- "$x"
        url="https://github.com/$repo/releases/download/$tag/$asset"
        if ! curl -fsSL --retry 3 --connect-timeout 15 --max-time 300 -o "$x/pkg.zip" "$url"; then err "$base: download failed ($url)."; rc=1; continue; fi
        if ! unzip -qo "$x/pkg.zip" -d "$x/x"; then err "$base: the archive could not be extracted."; rc=1; continue; fi
        if [[ -n $(find "$x/x" -type l -print -quit 2>/dev/null) ]]; then err "$base: the package contains symlinks; refusing it."; rc=1; continue; fi
        if (( $(du -sm "$x/x" 2>/dev/null | awk '{print $1+0}') > PLUGIN_ARCHIVE_MAX_MB )); then err "$base: the package is too large; refusing it."; rc=1; continue; fi
        csd="$x/x/addons/counterstrikesharp"
        if [[ ! -d $csd ]]; then err "$base: unexpected package layout."; rc=1; continue; fi
        pk_ok=1
        if [[ -d $csd/plugins ]]; then
            while IFS= read -r -d '' d; do
                name=${d##*/}
                valid_simple_name "$name" || continue
                pdst="$SHARED_ADDONS/counterstrikesharp/plugins/$name"
                vault_rescue "$name" "$pdst" "$d"
                rm -rf --one-file-system -- "$pdst"
                if ! cp -a -- "$d" "$pdst"; then err "$base: could not copy plugin $name."; pk_ok=0; continue; fi
                chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$pdst"
                vault_restore "$name" "$pdst"
                vault_manifest_write "$name" "$d"
                shared_update --arg n "$name" --arg p "counterstrikesharp/plugins/$name" \
                    'if any(.[]; type=="object" and .path == $p) then . else . += [{name:$n, path:$p}] end' >/dev/null
            done < <(find "$csd/plugins" -mindepth 1 -maxdepth 1 -type d -print0)
        fi
        if [[ -d $csd/shared ]]; then
            while IFS= read -r -d '' d; do
                name=${d##*/}
                valid_simple_name "$name" || continue
                rm -rf --one-file-system -- "$WP_CACHE/shared/$name"
                cp -a -- "$d" "$WP_CACHE/shared/$name" || { err "$base: could not stage library $name."; pk_ok=0; }
            done < <(find "$csd/shared" -mindepth 1 -maxdepth 1 -type d -print0)
        fi
        if [[ -d $csd/gamedata ]]; then cp -a -- "$csd/gamedata/." "$WP_CACHE/gamedata/" || pk_ok=0; fi
        chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$WP_CACHE" 2>/dev/null
        if ((pk_ok)); then
            jq --arg k "$base" --arg v "$tag" '.[$k] = $v' "$vf" >"$vf.tmp" && mv -f -- "$vf.tmp" "$vf"
            : >"$WP_CACHE/.ok-$base"
            changed=1
            ((quiet)) || ok "$base $tag installed."
        else
            rc=1
        fi
    done
    rm -rf --one-file-system -- "$tmp"
    if ((changed)); then
        date +%s >"$WP_CACHE/.stamp"
        chown "$CS2_USER:$CS2_GROUP" -- "$WP_CACHE/.stamp" "$vf" 2>/dev/null
        DRY_RUN=0
        sync_shared_all || rc=1
        while IFS= read -r id; do is_running "$id" && running=$((running + 1)); done < <(jq -r '.[].id' "$DB" 2>/dev/null)
        if ((running > 0)); then
            warn "$running server(s) are running: RESTART them so they load the new plugin files (do not hot-reload them)."
        fi
    fi
    if [[ -n $(jq -r '[.[] | select(type=="object" and .name == "AstraSkins")][0].path // empty' "$SHARED_DB" 2>/dev/null) ]]; then
        if ((quiet)); then wp_retire_astra quiet || true
        else warn "AstraSkins is still registered. Use WeaponPaints menu -> 'Retire AstraSkins' (servers must be stopped)."; fi
    fi
    wp_db_file_ok || warn "$WP_NAME has no database yet: WeaponPaints menu -> database (or: $SELF wp-db local)."
    unlock_ops
    return $rc
}

# AstraSkins is replaced: deregister it, move its folder (with its sqlite database) to the backup folder, drop the server links.
# Only with every server stopped: removing plugin files under a running server is what we avoid.
wp_retire_astra() {   # [quiet]
    local quiet=${1:-} rel id ts bk link repos
    rel=$(jq -r '[.[] | select(type=="object" and .name == "AstraSkins")][0].path // empty' "$SHARED_DB" 2>/dev/null)
    [[ -n $rel ]] || { [[ $quiet == quiet ]] || info "AstraSkins is not registered; nothing to retire."; return 0; }
    validate_plugin_rel "$rel" 1 || { warn "AstraSkins has an unexpected path in the registry; left alone."; return 1; }
    while IFS= read -r id; do
        if is_running "$id"; then
            warn "A server is running (ID $id): stop all servers first, then retire AstraSkins."; return 1
        fi
    done < <(jq -r '.[].id' "$DB" 2>/dev/null)
    ts=$(date +%Y%m%d-%H%M%S)
    bk="$BACKUP_DIR/retired-AstraSkins-$ts"
    install -d -m 750 -o "$CS2_USER" -g "$CS2_GROUP" -- "$BACKUP_DIR" 2>/dev/null
    if ! shared_update --arg n "AstraSkins" 'map(select((type=="object" and .name == $n) | not))' >/dev/null; then
        warn "Could not update the plugin registry; AstraSkins left as it is."; return 1
    fi
    if [[ -d $(plugin_src_path "$rel") ]] && shared_path_ok "$(plugin_src_path "$rel")"; then
        mkdir -p -- "$bk" && mv -T -- "$(plugin_src_path "$rel")" "$bk/plugin" \
            && info "The AstraSkins folder (with its sqlite database) was moved to $bk/plugin"
    fi
    while IFS= read -r id; do
        load_server "$id" || continue
        safe_server_path "$S_PATH" "$S_SLUG" || continue
        link="$S_PATH/$CSGOREL/addons/$rel"
        [[ -L $link ]] && rm -f -- "$link"
    done < <(jq -r '.[].id' "$DB" 2>/dev/null)
    repos=",${EXTRA_PLUGIN_REPOS:-},"; repos=${repos//,Ayrton09\/AstraSkins,/,}; repos=${repos#,}; repos=${repos%,}
    [[ ${EXTRA_PLUGIN_REPOS:-} == *Ayrton09/AstraSkins* ]] && conf_set EXTRA_PLUGIN_REPOS "$repos" >/dev/null 2>&1
    ok "AstraSkins retired. The shared config folder configs/AstraSkins was left untouched."
    return 0
}

# ---- gamedata + core.json for one loaded server (S_*) ----
# core.json: CounterStrikeSharp blocks writing item attributes unless FollowCS2ServerGuidelines is false
wp_runtime_server() {   # [refresh 0|1]
    local refresh=${1:-0} base gdir gf cf tmp fetched=0
    ((SHARED_OK)) || return 0
    ((DRY_RUN)) && return 0
    [[ -n $(wp_rel) ]] || return 0
    safe_server_path "$S_PATH" "$S_SLUG" || return 0
    base="$S_PATH/$CSGOREL"
    [[ -d $base && ! -L $base ]] || return 0
    gdir="$base/addons/counterstrikesharp/gamedata"; gf="$gdir/weaponpaints.json"
    cf="$base/addons/counterstrikesharp/configs/core.json"
    if [[ ! -s $gf ]] || ((refresh)); then
        ensure_chain "$base" "$gdir" || { warn "$S_NAME: cannot create $gdir"; return 0; }
        tmp=$(mktemp) || return 0
        if ((refresh)) && curl -fsSL -m 30 -o "$tmp" "$WP_GAMEDATA_URL" 2>/dev/null && jq -e 'has("CAttributeList_SetOrAddAttributeValueByName")' "$tmp" >/dev/null 2>&1; then
            fetched=1
            [[ -d $WP_CACHE/gamedata ]] && cp -- "$tmp" "$WP_CACHE/gamedata/weaponpaints.json" 2>/dev/null
        elif [[ -s $WP_CACHE/gamedata/weaponpaints.json ]] && jq -e . "$WP_CACHE/gamedata/weaponpaints.json" >/dev/null 2>&1; then
            cp -- "$WP_CACHE/gamedata/weaponpaints.json" "$tmp"
        else
            rm -f -- "$tmp"; warn "$S_NAME: no WeaponPaints gamedata available (run: $SELF wp-install)."; return 0
        fi
        if install -m 644 -o "$CS2_USER" -g "$CS2_GROUP" -- "$tmp" "$gf"; then
            ok "$S_NAME: WeaponPaints gamedata $( ((fetched)) && echo updated from GitHub || echo installed )."
            if ((fetched)) && ensure_chain "$base" "$base/addons/counterstrikesharp/shared"; then
                : >"$base/addons/counterstrikesharp/shared/.nexus-wp-refreshed" && chown "$CS2_USER:$CS2_GROUP" -- "$base/addons/counterstrikesharp/shared/.nexus-wp-refreshed"
            fi
            WP_NEEDS_RESTART=1
        else warn "$S_NAME: could not write $gf"; fi
        rm -f -- "$tmp"
    fi
    if [[ -f $cf ]]; then
        if jq -e '.FollowCS2ServerGuidelines == true' "$cf" >/dev/null 2>&1; then
            tmp=$(mktemp) || return 0
            if jq '.FollowCS2ServerGuidelines = false' "$cf" >"$tmp" 2>/dev/null && jq -e . "$tmp" >/dev/null 2>&1 \
               && cat -- "$tmp" >"$cf"; then
                ok "$S_NAME: core.json FollowCS2ServerGuidelines set to false (required by WeaponPaints)."
                warn "Note: this CounterStrikeSharp setting lets plugins change item attributes (skins); Valve's server guidelines forbid that on public servers (GSLT risk)."
                WP_NEEDS_RESTART=1
            else warn "$S_NAME: could not update $cf"; fi
            rm -f -- "$tmp"
        fi
    else
        info "$S_NAME: core.json does not exist yet (start the server once); it is fixed on the next sync."
    fi
    return 0
}

# ---- libraries (addons/counterstrikesharp/shared/*) + gamedata copied from the cache into one loaded server (S_*) ----
wp_seed_server() {
    local base c stamp cur d name f
    ((SHARED_OK)) || return 0
    ((DRY_RUN)) && return 0
    [[ -s $WP_CACHE/.stamp ]] || return 0
    safe_server_path "$S_PATH" "$S_SLUG" || return 0
    base="$S_PATH/$CSGOREL"
    [[ -d $base && ! -L $base ]] || return 0
    c="$base/addons/counterstrikesharp"
    [[ -d $c && ! -L $c ]] || return 0
    stamp=$(head -n1 "$WP_CACHE/.stamp" 2>/dev/null)
    cur=$(head -n1 "$c/shared/.nexus-wp-stamp" 2>/dev/null)
    [[ -n $stamp && $cur != "$stamp" ]] || return 0
    ensure_chain "$base" "$c/shared" || { warn "$S_NAME: cannot create the shared library folder."; return 0; }
    for d in "$WP_CACHE"/shared/*/; do
        [[ -d $d ]] || continue
        name=${d%/}; name=${name##*/}
        valid_simple_name "$name" || continue
        vault_rescue "servers/$S_SLUG/lib-$name" "$c/shared/$name" "${d%/}"
        rm -rf --one-file-system -- "${c:?}/shared/$name"
        cp -a -- "${d%/}" "$c/shared/$name" && chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$c/shared/$name"
        vault_restore "servers/$S_SLUG/lib-$name" "$c/shared/$name"
    done
    if compgen -G "$WP_CACHE/gamedata/*.json" >/dev/null; then
        ensure_chain "$base" "$c/gamedata" || return 0
        for f in "$WP_CACHE"/gamedata/*.json; do
            install -m 644 -o "$CS2_USER" -g "$CS2_GROUP" -- "$f" "$c/gamedata/${f##*/}"
        done
    fi
    printf '%s\n' "$stamp" >"$c/shared/.nexus-wp-stamp" && chown "$CS2_USER:$CS2_GROUP" -- "$c/shared/.nexus-wp-stamp"
    info "$S_NAME: WeaponPaints libraries + gamedata updated."
    return 0
}

# per loaded server (S_*): plugin folder + config folder
wp_share_server() {
    local rel base src plug cfgroot cfgd bk ts t
    ((SHARED_OK)) || return 0
    ((DRY_RUN)) && return 0
    rel=$(wp_rel); [[ -n $rel ]] || return 0
    validate_plugin_rel "$rel" 1 || return 0
    safe_server_path "$S_PATH" "$S_SLUG" || return 0
    base="$S_PATH/$CSGOREL"
    [[ -d $base && ! -L $base ]] || return 0
    src=$(plugin_src_path "$rel"); plug="$base/addons/$rel"
    ts=$(date +%Y%m%d-%H%M%S)
    bk="$S_PATH/nexus-backup/$WP_NAME-$ts"

    # 1) a real (local / split) plugin folder is replaced by the link to the shared one
    if [[ -d $plug && ! -L $plug && -d $src ]] && ! paths_identical "$src" "$plug"; then
        mkdir -p -- "$bk" && chown "$CS2_USER:$CS2_GROUP" -- "$S_PATH/nexus-backup" "$bk" 2>/dev/null
        if mv -T -- "$plug" "$bk/plugin"; then
            info "$S_NAME: its own $WP_NAME folder was moved to $bk/plugin (the shared one is used now)."
            WP_NEEDS_RESTART=1
        else
            warn "$S_NAME: could not move the local $WP_NAME folder; it stays per-server."
        fi
    fi

    # 2) shared config folder
    cfgroot="$base/addons/counterstrikesharp/configs/plugins"
    cfgd="$cfgroot/$WP_NAME"
    install -d -m 755 -o "$CS2_USER" -g "$CS2_GROUP" -- "$SHARED_DIR/configs" "$WP_CFG_SHARED" || return 0
    if [[ -L $cfgd ]]; then
        t=$(readlink -- "$cfgd")
        [[ $t == "$WP_CFG_SHARED" ]] && return 0
        if [[ $t == "$SHARED_DIR"/* || ! -e $cfgd ]]; then ln -sfT -- "$WP_CFG_SHARED" "$cfgd" && chown -h "$CS2_USER:$CS2_GROUP" -- "$cfgd"; return 0; fi
        warn "$S_NAME: $WP_NAME config folder is a link to somewhere else ($t); left alone."; return 0
    fi
    if [[ -e $cfgd && ! -d $cfgd ]]; then warn "$S_NAME: a file blocks the $WP_NAME config folder."; return 0; fi
    if [[ -d $cfgd ]]; then
        # the first config found becomes the shared one
        if [[ -f $cfgd/$WP_NAME.json && ! -f $WP_CFG_SHARED/$WP_NAME.json ]]; then
            cp -p -- "$cfgd/$WP_NAME.json" "$WP_CFG_SHARED/$WP_NAME.json" && chown "$CS2_USER:$CS2_GROUP" -- "$WP_CFG_SHARED/$WP_NAME.json"
        fi
        mkdir -p -- "$bk" && chown "$CS2_USER:$CS2_GROUP" -- "$S_PATH/nexus-backup" "$bk" 2>/dev/null
        mv -T -- "$cfgd" "$bk/config" || { warn "$S_NAME: could not move the local $WP_NAME config folder."; return 0; }
        WP_NEEDS_RESTART=1
    fi
    if ensure_chain "$base" "$cfgroot" && ln -s -- "$WP_CFG_SHARED" "$cfgd" && chown -h "$CS2_USER:$CS2_GROUP" -- "$cfgd"; then
        info "$S_NAME: $WP_NAME config is the shared one."
    else
        warn "$S_NAME: could not link the shared $WP_NAME config."
    fi
    return 0
}

# the config does not exist before the plugin runs once: when it appears, patch it and reload the plugin
wp_config_watch() {   # <server id>
    local id=$1 f="$WP_CFG_SHARED/$WP_NAME.json"
    [[ -n $(wp_rel) ]] || return 0
    [[ -f $f ]] && { wp_patch_config; return 0; }
    (
        local i
        for ((i = 0; i < 40; i++)); do
            sleep 3
            [[ -f $f ]] || continue
            sleep 1
            WP_NEEDS_RESTART=0
            wp_patch_config >/dev/null 2>&1 && ((WP_NEEDS_RESTART)) && is_running "$id" && console_send "$id" "css_plugins reload $WP_NAME" >/dev/null 2>&1
            exit 0
        done
    ) </dev/null >/dev/null 2>&1 7>&- 8>&- 9>&- &
    disown 2>/dev/null
    return 0
}

wp_report_restart() {
    ((WP_NEEDS_RESTART)) || return 0
    warn "$WP_NAME was switched to the shared folder/config: RESTART the running servers once (Restart Server) so they use it."
    WP_NEEDS_RESTART=0
}

# ---------------------------------- menu / CLI --------------------------------
wp_status_lines() {
    local vf="$WP_CACHE/versions.json" b v
    echo "  Status:"
    if [[ -f $SHARED_ADDONS/counterstrikesharp/plugins/$WP_NAME/$WP_NAME.dll ]]; then
        for b in WeaponPaints PlayerSettings AnyBaseLib MenuManager; do
            v=$(jq -r --arg k "$b" '.[$k] // "-"' "$vf" 2>/dev/null)
            printf '    %-14s %s\n' "$b" "${v:--}"
        done
    else
        echo "    WeaponPaints is not installed yet."
    fi
    if wp_db_file_ok; then echo "    Database       $(wp_db_get user)@$(wp_db_get host):$(wp_db_get port) / $(wp_db_get name)"
    else echo "    Database       not configured"; fi
    [[ -f $WP_WEB_DIR/website/class/config.php ]] && echo "    Website files  $WP_WEB_DIR/website"
    [[ -n $(jq -r '[.[] | select(type=="object" and .name == "AstraSkins")][0].path // empty' "$SHARED_DB" 2>/dev/null) ]] \
        && echo "    AstraSkins     still registered (use option 7 with all servers stopped)"
    echo
}

wp_menu() {
    local c
    while :; do
        clear_screen
        dsep
        printf '%s            WEAPONPAINTS (skins)%s\n' "$BOLD" "$RESET"
        dsep
        echo
        wp_status_lines
        echo " 1) Install / update WeaponPaints + libraries (PlayerSettings, AnyBaseLib, MenuManager)"
        echo " 2) Database: create a local MariaDB automatically (recommended)"
        echo " 3) Database: use an external MySQL / MariaDB"
        echo " 4) Database: test the login"
        echo " 5) Install the skins website (PHP files + database login)"
        echo " 6) Fix gamedata + core.json on every server (re-download the signature)"
        echo " 7) Retire AstraSkins (all servers must be stopped)"
        echo " 8) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) header "INSTALL WEAPONPAINTS"; DRY_RUN=0; wp_install 0 0; pause ;;
            2) header "LOCAL DATABASE"; wp_db_local_setup; pause ;;
            3) header "EXTERNAL DATABASE"; wp_db_external_setup; pause ;;
            4) header "DATABASE TEST"; wp_db_status; pause ;;
            5) header "SKINS WEBSITE"; wp_web_install; pause ;;
            6) header "FIX GAMEDATA"; cli_wp_fix --refresh; pause ;;
            7) header "RETIRE ASTRASKINS"; lock_ops 30 && { wp_retire_astra; unlock_ops; }; pause ;;
            8|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

cli_wp_install() {   # [--force]
    local force=0 a
    for a in "$@"; do case $a in --force) force=1 ;; *) err "Usage: $SELF wp-install [--force]"; return 2 ;; esac; done
    DRY_RUN=0
    wp_install 1 "$force"
}

cli_wp_fix() {   # [--refresh]
    local refresh=0 id a
    for a in "$@"; do case $a in --refresh) refresh=1 ;; *) err "Usage: $SELF wp-fix [--refresh]"; return 2 ;; esac; done
    DRY_RUN=0
    ((SHARED_OK)) || { err "Shared plugins are not set up."; return 1; }
    [[ -n $(wp_rel) ]] || { err "WeaponPaints is not installed. Run: $SELF wp-install"; return 1; }
    need_layout || return 1
    WP_NEEDS_RESTART=0
    while IFS= read -r id; do
        load_server "$id" || continue
        wp_seed_server
        wp_runtime_server "$refresh"
    done < <(jq -r '.[].id' "$DB")
    wp_patch_config >/dev/null 2>&1 || true
    if ((WP_NEEDS_RESTART)); then warn "Restart the servers so WeaponPaints picks this up (e.g. nexus restart ID)."; WP_NEEDS_RESTART=0
    else ok "WeaponPaints gamedata and core.json are already correct on every server."; fi
    return 0
}

cli_wp_db() {   # local | test
    case ${1:-} in
        local) wp_db_local_setup ;;
        test)  wp_db_status ;;
        *) err "Usage: $SELF wp-db local|test"; return 2 ;;
    esac
}

wp_db_dump() {   # <stage dir>: mysqldump of the WeaponPaints database (only a database on this machine)
    local stage=$1 h dst bin
    wp_db_file_ok || return 0
    h=$(wp_db_get host); [[ $h == 127.0.0.1 || $h == localhost ]] || return 0
    bin=$(command -v mariadb-dump 2>/dev/null || command -v mysqldump 2>/dev/null) || return 0
    dst="$stage$SHARED_DIR/weaponpaints.sql"
    mkdir -p -- "$(dirname -- "$dst")"
    MYSQL_PWD=$(wp_db_get password) "$bin" --single-transaction -h "$h" -P "$(wp_db_get port)" -u "$(wp_db_get user)" "$(wp_db_get name)" >"$dst" 2>/dev/null \
        || rm -f -- "$dst"
    return 0
}


wp_mariadb_cnf() {
    local d
    for d in /etc/mysql/mariadb.conf.d /etc/mysql/conf.d /etc/my.cnf.d; do
        [[ -d $d ]] && { printf '%s/99-cs2nexus-light.cnf' "$d"; return 0; }
    done
    printf '/etc/mysql/conf.d/99-cs2nexus-light.cnf'
}

# WeaponPaints keeps a few small tables: MariaDB does not need its default (heavy) memory settings
wp_mariadb_light() {
    local f; f=$(wp_mariadb_cnf)
    mkdir -p -- "$(dirname -- "$f")" || return 1
    cat >"$f" <<'CNF'
# written by CS2Nexus
[mysqld]
performance_schema = OFF
max_connections = 40
innodb_buffer_pool_size = 64M
innodb_log_buffer_size = 4M
key_buffer_size = 8M
tmp_table_size = 16M
max_heap_table_size = 16M
table_open_cache = 200
thread_cache_size = 8
skip-name-resolve
CNF
    chmod 644 -- "$f"
    systemctl restart mariadb >/dev/null 2>&1 || systemctl restart mysql >/dev/null 2>&1 || true
    sleep 3
    ok "MariaDB set to a low-memory profile ($f)."
}

# =============================================================================
#  SERVER DOCTOR: checks the whole machine, the launcher and every server, makes everything lighter
#  and repairs what is wrong.  nexus doctor            -> report only (changes nothing)
#                              nexus doctor --fix      -> report, then fix + lighten (a data backup is made first)
#                              nexus doctor --fix --restart -> also restarts servers that run outdated plugin files
#  Every fix is checked again afterwards: a problem is only reported as FIXED when the check now passes.
# =============================================================================
readonly DOC_LOG_DIR="/var/log/cs2nexus"
readonly DOC_SYSCTL_FILE="/etc/sysctl.d/99-cs2nexus.conf"
readonly DOC_SWAPFILE="/swapfile-cs2nexus"
readonly -a DOC_SYSCTL=("vm.swappiness=10" "net.core.rmem_max=26214400" "net.core.wmem_max=26214400" "net.core.rmem_default=1048576" "net.core.wmem_default=1048576" "net.core.netdev_max_backlog=4096")
readonly -a DOC_USELESS_UNITS=(apport.service cups.service cups-browsed.service avahi-daemon.service avahi-daemon.socket bluetooth.service ModemManager.service whoopsie.service motd-news.timer)
DOC_FIX=0; DOC_RESTART=0
DOC_N_OK=0; DOC_N_WARN=0; DOC_N_FAIL=0; DOC_N_FIXED=0; DOC_N_FIXABLE=0
DOC_MSG=""; DOC_INFO=""; DOC_LOGFILE=""; DOC_BK=""
DOC_ID=""; DOC_BASE=""; DOC_SESS=""

doc_emit() {   # <tag> <color> <message>
    printf '  %s[%s]%s %s\n' "$2" "$1" "$RESET" "$3"
    [[ -n $DOC_LOGFILE ]] && printf '[%s] %s\n' "$1" "$3" >>"$DOC_LOGFILE" 2>/dev/null
    return 0
}
doc_pass()  { DOC_N_OK=$((DOC_N_OK + 1));       doc_emit " OK  " "$GREEN"  "$1"; }
doc_warn()  { DOC_N_WARN=$((DOC_N_WARN + 1));   doc_emit "WARN " "$YELLOW" "$1"; }
doc_fail()  { DOC_N_FAIL=$((DOC_N_FAIL + 1));   doc_emit "FAIL " "$RED"    "$1"; }
doc_fixed() { DOC_N_FIXED=$((DOC_N_FIXED + 1)); doc_emit "FIXED" "$CYAN"   "$1"; }
doc_section() { printf '\n%s%s%s\n' "$BOLD" "$1" "$RESET"; [[ -n $DOC_LOGFILE ]] && printf '\n== %s\n' "$1" >>"$DOC_LOGFILE" 2>/dev/null; return 0; }

# keep a copy of a file before the doctor changes it
doc_save() {   # <file>
    local f=$1
    [[ -e $f ]] || return 0
    [[ -n $DOC_BK ]] || DOC_BK="$BACKUP_DIR/doctor-$(date +%Y%m%d-%H%M%S)"
    mkdir -p -- "$DOC_BK$(dirname -- "$f")" 2>/dev/null && cp -a -- "$f" "$DOC_BK$f" 2>/dev/null
    return 0
}

# doc_step <title> <check fn> [fix fn] [warn|fail]
# check fn: returns 0 = fine, 1 = problem; may set DOC_MSG with details.   fix fn: repairs; the check is run again afterwards.
doc_step() {
    local title=$1 chk=$2 fix=${3:-} sev=${4:-warn} detail
    DOC_MSG=""; DOC_INFO=""
    if "$chk"; then doc_pass "$title${DOC_INFO:+ - $DOC_INFO}"; return 0; fi
    detail=$DOC_MSG
    if ((DOC_FIX)) && [[ -n $fix ]]; then
        doc_emit "FIXING" "$BLUE" "$title: $detail"
        "$fix" || true
        DOC_MSG=""; DOC_INFO=""
        if "$chk"; then doc_fixed "$title"; return 0; fi
        doc_fail "$title: still a problem after the fix - $DOC_MSG"
        return 1
    fi
    [[ -n $fix ]] && DOC_N_FIXABLE=$((DOC_N_FIXABLE + 1))
    if [[ $sev == fail ]]; then doc_fail "$title: $detail"; else doc_warn "$title: $detail"; fi
    return 1
}

doc_df_avail_mb() { df -P -BM "${1:-$SERVERS_DIR}" 2>/dev/null | awk 'NR==2{gsub("M","",$4); print $4+0}'; }
doc_df_used_pct() { df -P "${1:-$SERVERS_DIR}" 2>/dev/null | awk 'NR==2{gsub("%","",$5); print $5+0}'; }
doc_has_systemd() { command -v systemctl >/dev/null 2>&1 && [[ -d /run/systemd/system ]]; }

# ------------------------------- cleaning -------------------------------------
doc_prune_dir() {   # <dir> <keep newest N> <older than days>
    local d=$1 keep=$2 days=$3 f i=0
    [[ -d $d ]] || return 0
    while IFS= read -r f; do
        i=$((i + 1)); ((i > keep)) || continue
        [[ -n $(find "$f" -maxdepth 0 -mtime "+$days" -print -quit 2>/dev/null) ]] && rm -rf --one-file-system -- "$f"
    done < <(ls -1dt -- "$d"/* 2>/dev/null)
    return 0
}

doc_fix_clean() {
    local before after id d
    before=$(doc_df_avail_mb)
    command -v journalctl >/dev/null 2>&1 && journalctl --vacuum-size=200M --vacuum-time=14d >/dev/null 2>&1
    command -v apt-get >/dev/null 2>&1 && apt-get clean >/dev/null 2>&1
    find /tmp -maxdepth 1 \( -name 'cs2nexus.*' -o -name 'cs2nexus-*' \) -mtime +1 -exec rm -rf --one-file-system -- {} + 2>/dev/null
    find "$CS2_HOME" /root -maxdepth 6 -ipath '*/steam/logs/*' -type f -mtime +14 -delete 2>/dev/null
    find /var/lib/systemd/coredump -type f -mtime +2 -delete 2>/dev/null
    find "$SERVERS_DIR" "$BASE" -xdev -maxdepth 6 -type f \( -name 'core' -o -name 'core.[0-9]*' \) -mtime +1 -delete 2>/dev/null
    for d in "$BACKUP_DIR"/retired-* "$BACKUP_DIR"/doctor-*; do
        [[ -d $d && -n $(find "$d" -maxdepth 0 -mtime +60 -print -quit 2>/dev/null) ]] && rm -rf --one-file-system -- "$d"
    done
    doc_prune_dir "$PLUGIN_BACKUP_DIR" "$PLUGIN_BACKUP_KEEP" 14
    doc_prune_dir "$CSS_BACKUP_DIR" "$CSS_BACKUP_KEEP" 14
    # demo files and old game logs of every server
    while IFS= read -r id; do
        load_server "$id" 2>/dev/null || continue
        safe_server_path "$S_PATH" "$S_SLUG" 2>/dev/null || continue
        find "$S_PATH/$CSGOREL" -maxdepth 2 -type f -name '*.dem' -mtime +14 -delete 2>/dev/null
    done < <(jq -r '.[].id' "$DB" 2>/dev/null)
    after=$(doc_df_avail_mb)
    info "Cleaned: $(mon_fmt_mb "$(( ${after:-0} - ${before:-0} > 0 ? ${after:-0} - ${before:-0} : 0 ))") freed."
    return 0
}

# ------------------------------- system checks --------------------------------
doc_chk_disk() {
    local pct avail
    pct=$(doc_df_used_pct); avail=$(doc_df_avail_mb)
    DOC_MSG="${pct:-?}% used, $(mon_fmt_mb "${avail:-0}") free (keep at least 10% and 5 GB free)"; DOC_INFO="${pct:-?}% used, $(mon_fmt_mb "${avail:-0}") free"
    ((${pct:-0} < 90 && ${avail:-0} >= 5120))
}

doc_chk_ram() {
    local tot avail pct
    tot=$(awk '/^MemTotal:/{print $2}' /proc/meminfo); avail=$(awk '/^MemAvailable:/{print $2}' /proc/meminfo)
    pct=$(( ${avail:-0} * 100 / (${tot:-1} > 0 ? ${tot:-1} : 1) ))
    DOC_INFO="$pct% free"
    DOC_MSG="$pct% of RAM free ($(mon_fmt_mb "$(( ${avail:-0} / 1024 ))") of $(mon_fmt_mb "$(( ${tot:-0} / 1024 ))")); too many servers/services for this machine - see the Resource Monitor"
    ((pct >= 12))
}

doc_chk_swap() {
    local ram swap
    ram=$(awk '/^MemTotal:/{print int($2/1024)}' /proc/meminfo); swap=$(awk '/^SwapTotal:/{print int($2/1024)}' /proc/meminfo)
    DOC_MSG="$ram MB RAM and no swap: one memory spike while a map loads gets a server killed"
    ((${swap:-0} > 0 || ${ram:-0} >= 16384))
}
doc_fix_swap() {
    local f=$DOC_SWAPFILE size=2048 avail
    avail=$(doc_df_avail_mb /)
    ((${avail:-0} > size + 3072)) || { err "Not enough free disk space for a ${size} MB swap file."; return 1; }
    [[ -e $f ]] && { swapoff "$f" 2>/dev/null; rm -f -- "$f"; }
    fallocate -l "${size}M" "$f" 2>/dev/null && chmod 600 "$f" && mkswap "$f" >/dev/null 2>&1 && swapon "$f" 2>/dev/null \
        || { swapoff "$f" 2>/dev/null; rm -f -- "$f"
             dd if=/dev/zero of="$f" bs=1M count="$size" status=none 2>/dev/null && chmod 600 "$f" && mkswap "$f" >/dev/null 2>&1 && swapon "$f" 2>/dev/null; } \
        || { rm -f -- "$f"; err "Could not enable swap (a container without swap support?)."; return 1; }
    doc_save /etc/fstab
    grep -q "^$f " /etc/fstab 2>/dev/null || printf '%s none swap sw 0 0\n' "$f" >>/etc/fstab
    ok "Swap file created: $f (${size} MB)."
}

doc_chk_oom() {
    local n=0
    if command -v journalctl >/dev/null 2>&1; then
        n=$(journalctl -k --since "7 days ago" --no-pager 2>/dev/null | grep -ciE 'out of memory|oom-kill|killed process')
    else
        n=$(dmesg 2>/dev/null | grep -ciE 'out of memory|oom-kill|killed process')
    fi
    DOC_MSG="the kernel killed processes $n time(s) in 7 days because RAM ran out: fewer servers, less MaxPlayers or more RAM is the real fix"
    ((${n:-0} == 0))
}

doc_chk_load() {
    local cores load
    cores=$(nproc 2>/dev/null || echo 1); load=$(cut -d' ' -f2 /proc/loadavg)
    DOC_MSG="load average (5 min) is $load on $cores core(s)"; DOC_INFO="$load on $cores core(s)"
    awk -v l="$load" -v c="$cores" 'BEGIN{exit !(l <= c * 1.5)}'
}

doc_chk_time() {
    command -v timedatectl >/dev/null 2>&1 || return 0
    DOC_MSG="the clock is not synchronised (bans, logs and tokens drift)"
    [[ $(timedatectl show -p NTPSynchronized --value 2>/dev/null) != no ]]
}
doc_fix_time() { timedatectl set-ntp true >/dev/null 2>&1; sleep 3; }

doc_chk_sysctl() {
    local kv k v cur bad=""
    command -v sysctl >/dev/null 2>&1 || return 0
    for kv in "${DOC_SYSCTL[@]}"; do
        k=${kv%%=*}; v=${kv#*=}
        cur=$(sysctl -n "$k" 2>/dev/null) || continue
        if [[ $k == vm.swappiness ]]; then ((cur <= v)) || bad+=" $k=$cur"; else ((cur >= v)) || bad+=" $k=$cur"; fi
    done
    DOC_MSG="kernel settings not tuned for a game server:$bad"
    [[ -z $bad ]]
}
doc_fix_sysctl() {
    local kv
    doc_save "$DOC_SYSCTL_FILE"
    { echo "# written by CS2Nexus doctor"; for kv in "${DOC_SYSCTL[@]}"; do echo "$kv"; done; } >"$DOC_SYSCTL_FILE"
    sysctl -p "$DOC_SYSCTL_FILE" >/dev/null 2>&1 || warn "Some kernel settings could not be applied (container / read-only /proc/sys)."
}

doc_chk_services() {
    local u act=""
    doc_has_systemd || return 0
    for u in "${DOC_USELESS_UNITS[@]}"; do systemctl is-active --quiet "$u" 2>/dev/null && act+=" $u"; done
    DOC_MSG="services a game server does not need are running:$act"
    [[ -z $act ]]
}
doc_fix_services() {
    local u
    for u in "${DOC_USELESS_UNITS[@]}"; do
        systemctl is-active --quiet "$u" 2>/dev/null && { systemctl disable --now "$u" >/dev/null 2>&1 && info "Disabled $u"; }
    done
    return 0
}

doc_light_units() {
    local u
    for u in "$WATCHDOG_UNIT" "$BK_UNIT" "$PLUGIN_TIMER_UNIT" "$CSS_TIMER_UNIT" "$AL_UNIT" "$PANEL_UNIT"; do
        [[ -f /etc/systemd/system/$u.service ]] && printf '%s\n' "$u"
    done
}
doc_chk_units() {
    local u miss=""
    doc_has_systemd || return 0
    while IFS= read -r u; do [[ -f /etc/systemd/system/$u.service.d/10-cs2nexus-light.conf ]] || miss+=" $u"; done < <(doc_light_units)
    DOC_MSG="background services run at full priority (they can cause lag spikes):$miss"
    [[ -z $miss ]]
}
doc_fix_units() {
    local u d
    while IFS= read -r u; do
        d="/etc/systemd/system/$u.service.d"
        mkdir -p -- "$d" || continue
        if [[ $u == "$PANEL_UNIT" ]]; then
            printf '[Service]\nNice=10\nCPUWeight=50\nIOSchedulingClass=best-effort\nIOSchedulingPriority=6\nOOMScoreAdjust=300\n' >"$d/10-cs2nexus-light.conf"
        else
            printf '[Service]\nNice=19\nCPUWeight=20\nIOSchedulingClass=idle\n' >"$d/10-cs2nexus-light.conf"
        fi
    done < <(doc_light_units)
    systemctl daemon-reload >/dev/null 2>&1
    info "Low-priority limits written (they apply the next time each service starts; the game servers keep full priority)."
}

doc_chk_cmds() {
    local c miss=""
    for c in "${REQUIRED_CMDS[@]}"; do command -v "$c" >/dev/null 2>&1 || miss+=" $c"; done
    DOC_MSG="missing tools:$miss"
    [[ -z $miss ]]
}
doc_fix_cmds() {
    local c
    local -a pk=()
    for c in "${REQUIRED_CMDS[@]}"; do
        command -v "$c" >/dev/null 2>&1 && continue
        case $c in
            ss) pk+=(iproute2) ;; runuser|flock) pk+=(util-linux) ;; find) pk+=(findutils) ;; cmp|diff) pk+=(diffutils) ;;
            mktemp) pk+=(coreutils) ;; awk) pk+=(mawk) ;; *) pk+=("$c") ;;
        esac
    done
    ((${#pk[@]})) && DEBIAN_FRONTEND=noninteractive apt-get install -y "${pk[@]}" >/dev/null 2>&1
    return 0
}

doc_chk_perms() {
    local bad=""
    [[ -f $CONF_FILE && -n $(find "$CONF_FILE" -maxdepth 0 -perm /007 -print -quit 2>/dev/null) ]] && bad+=" $CONF_FILE"
    [[ -f $WP_DB_FILE && -n $(find "$WP_DB_FILE" -maxdepth 0 -perm /007 -print -quit 2>/dev/null) ]] && bad+=" $WP_DB_FILE"
    [[ -n $(find "$SELF" -maxdepth 0 -perm /022 -print -quit 2>/dev/null) ]] && bad+=" $SELF"
    DOC_MSG="files with too open permissions (they hold tokens / passwords or are executed as root):$bad"
    [[ -z $bad ]]
}
doc_fix_perms() {
    [[ -f $CONF_FILE ]] && chmod 600 -- "$CONF_FILE"
    [[ -f $WP_DB_FILE ]] && chmod o-rwx -- "$WP_DB_FILE"
    chmod go-w -- "$SELF"
}

doc_chk_json() {
    local f bad=""
    for f in "$DB" "$SHARED_DB" "$AUTOSTART_DB" "$SETTINGS_DB"; do
        [[ -e $f ]] && { jq -e . "$f" >/dev/null 2>&1 || bad+=" $f"; }
    done
    DOC_MSG="invalid JSON (restore it from Maintenance -> backups):$bad"
    [[ -z $bad ]]
}

doc_chk_base() {
    need_layout >/dev/null 2>&1
    DOC_MSG="CS2 game files were not found in $BASE (Maintenance -> update CS2)"
    [[ -s $BASE/${CSGOREL:-game/csgo}/pak01_dir.vpk ]]
}

doc_chk_ports() {
    local d
    d=$(jq -r '[.[].port] | group_by(.) | map(select(length > 1) | .[0] | tostring) | join(",")' "$DB" 2>/dev/null)
    DOC_MSG="two servers use the same port: $d"
    [[ -z $d ]]
}

doc_chk_orphans() {
    local s id ids bad=""
    ids=$(jq -r '.[].id' "$DB" 2>/dev/null)
    while IFS= read -r s; do
        [[ $s == cs2-* ]] || continue
        id=${s#cs2-}
        grep -qx -- "$id" <<<"$ids" || bad+=" $s"
    done < <(tmux_cs2 list-sessions -F '#{session_name}' 2>/dev/null)
    DOC_MSG="tmux session(s) of servers that no longer exist (they keep using RAM):$bad"
    [[ -z $bad ]]
}
doc_fix_orphans() {
    local s id ids
    ids=$(jq -r '.[].id' "$DB" 2>/dev/null)
    while IFS= read -r s; do
        [[ $s == cs2-* ]] || continue
        id=${s#cs2-}
        grep -qx -- "$id" <<<"$ids" || tmux_cs2 kill-session -t "=$s" 2>/dev/null
    done < <(tmux_cs2 list-sessions -F '#{session_name}' 2>/dev/null)
    return 0
}

doc_chk_registry() {
    local n rel bad=""
    ((SHARED_OK)) || return 0
    while IFS=$'\t' read -r n rel; do
        [[ -n $rel ]] || continue
        [[ -d $(plugin_src_path "$rel") ]] || bad+=" $n"
    done < <(jq -r '.[] | select(type=="object") | [.name, .path] | @tsv' "$SHARED_DB" 2>/dev/null)
    DOC_MSG="registered plugins whose files are gone:$bad"
    [[ -z $bad ]]
}
doc_fix_registry() {
    local n rel
    doc_save "$SHARED_DB"
    while IFS=$'\t' read -r n rel; do
        [[ -n $rel && ! -d $(plugin_src_path "$rel") ]] || continue
        shared_update --arg n "$n" 'map(select((type=="object" and .name == $n) | not))' >/dev/null && info "Removed '$n' from the registry (its folder does not exist)."
    done < <(jq -r '.[] | select(type=="object") | [.name, .path] | @tsv' "$SHARED_DB" 2>/dev/null)
}

doc_chk_watchdog() {
    local n
    doc_has_systemd || return 0
    n=$(jq 'length' "$AUTOSTART_DB" 2>/dev/null || echo 0)
    ((${n:-0} > 0)) || return 0
    DOC_MSG="servers are marked for autostart but the watchdog timer is not running"
    systemctl is-active --quiet "$WATCHDOG_UNIT.timer" 2>/dev/null
}
doc_fix_watchdog() {
    if [[ -f /etc/systemd/system/$WATCHDOG_UNIT.timer ]]; then systemctl enable --now "$WATCHDOG_UNIT.timer" >/dev/null 2>&1; else watchdog_install; fi
}

doc_chk_backup() {
    local newest
    doc_has_systemd || return 0
    newest=$(find "$BK_ROOT" -maxdepth 1 -name 'cs2nexus-*.tar.gz' -mtime -4 -print -quit 2>/dev/null)
    DOC_MSG="no data backup in the last 4 days (or the backup timer is off)"
    [[ -n $newest ]] && systemctl is-active --quiet "$BK_UNIT.timer" 2>/dev/null
}
doc_fix_backup() {
    [[ -f /etc/systemd/system/$BK_UNIT.timer ]] && systemctl enable --now "$BK_UNIT.timer" >/dev/null 2>&1 || backup_timer_install
    [[ -n $(find "$BK_ROOT" -maxdepth 1 -name 'cs2nexus-auto-*.tar.gz' -mtime -4 -print -quit 2>/dev/null) ]] || backup_run auto
}

doc_chk_panel() {
    panel_installed || return 0
    doc_has_systemd || return 0
    DOC_MSG="the web panel service is not running"
    systemctl is-active --quiet "$PANEL_UNIT" 2>/dev/null
}
doc_fix_panel() { systemctl restart "$PANEL_UNIT" >/dev/null 2>&1; sleep 3; }

# ------------------------------- WeaponPaints ---------------------------------
doc_wp_active() { [[ -n $(wp_rel 2>/dev/null) ]]; }

doc_chk_wpdb() {
    doc_wp_active || return 0
    if ! wp_db_file_ok; then DOC_MSG="WeaponPaints has no database configured"; return 1; fi
    DOC_MSG="the database login $(wp_db_get user)@$(wp_db_get host) does not work"
    wp_db_test "$(wp_db_get host)" "$(wp_db_get port)" "$(wp_db_get user)" "$(wp_db_get password)" "$(wp_db_get name)"
}
doc_fix_wpdb() {
    wp_sql_bin >/dev/null 2>&1 || DEBIAN_FRONTEND=noninteractive apt-get install -y mariadb-client >/dev/null 2>&1
    if ! wp_db_file_ok; then wp_db_local_setup; return; fi
    case $(wp_db_get host) in
        127.0.0.1|localhost)
            systemctl start mariadb >/dev/null 2>&1 || systemctl start mysql >/dev/null 2>&1
            sleep 3
            wp_db_test "$(wp_db_get host)" "$(wp_db_get port)" "$(wp_db_get user)" "$(wp_db_get password)" "$(wp_db_get name)" \
                || { [[ $(wp_db_get user) == cs2nexus_wp ]] && wp_db_local_setup; } ;;
    esac
    wp_patch_config >/dev/null 2>&1
    return 0
}

doc_chk_mariadb_light() {
    local h
    command -v mariadbd >/dev/null 2>&1 || command -v mysqld >/dev/null 2>&1 || return 0
    wp_db_file_ok || return 0
    h=$(wp_db_get host); [[ $h == 127.0.0.1 || $h == localhost ]] || return 0
    [[ $(wp_db_get user) == cs2nexus_wp ]] || return 0
    DOC_MSG="MariaDB runs with its default (heavy) memory settings; WeaponPaints needs very little"
    [[ -f $(wp_mariadb_cnf) ]]
}
doc_fix_mariadb_light() { wp_mariadb_light; }

# ---------------------------- per-server checks (S_* loaded) -------------------
doc_chk_s_online() {
    jq -e --argjson i "$DOC_ID" 'any(.[]; . == $i)' "$AUTOSTART_DB" >/dev/null 2>&1 || return 0
    is_running "$DOC_ID" && return 0
    [[ -e $(manual_stop_file "$DOC_ID") ]] && return 0
    DOC_MSG="marked for autostart but offline"
    return 1
}
doc_fix_s_online() { start_server "$DOC_ID"; }

doc_chk_s_loop() {
    local f="$STATE_DIR/restarts-$DOC_ID" cnt=0
    [[ -f $f ]] || return 0
    cnt=$(awk -v now="$(date +%s)" -v w="$WATCHDOG_WINDOW" '$1 ~ /^[0-9]+$/ && now-$1 < w' "$f" 2>/dev/null | wc -l)
    DOC_MSG="the watchdog had to restart this server $cnt time(s) in the last $((WATCHDOG_WINDOW / 60)) minutes: it is crashing (read its console log)"
    ((cnt < 2))
}

doc_chk_s_crash() {
    local f="$S_PATH/logs/console.log" hit
    [[ -f $f ]] || return 0
    hit=$(tail -n 1500 "$f" 2>/dev/null | grep -aoiE '.{0,40}(segmentation fault|SIGSEGV|fatal error|unhandled exception|dumped core|assertion failed|out of memory).{0,40}' | tail -n 2 | tr '\n' '|')
    DOC_MSG="crash marker in the console log: ${hit%|}   (details: $SELF logs / $f)"
    [[ -z $hit ]]
}

doc_chk_s_logs() {
    local f="$S_PATH/logs/console.log" mb=0 old
    [[ -f $f ]] && mb=$(( $(stat -c %s -- "$f" 2>/dev/null || echo 0) / 1048576 ))
    old=$(find "$DOC_BASE/addons/counterstrikesharp/logs" "$DOC_BASE/logs" -type f -mtime +14 2>/dev/null | wc -l)
    DOC_MSG="console.log is $mb MB, $old old log file(s)"
    ((mb < 50 && old == 0))
}
doc_fix_s_logs() {
    local f="$S_PATH/logs/console.log" ts x
    ts=$(date +%Y%m%d-%H%M%S)
    if [[ -f $f && $(stat -c %s -- "$f" 2>/dev/null || echo 0) -ge 52428800 ]]; then
        # the console is written in append mode, so emptying the file is safe while the server runs
        cp -p -- "$f" "$f.$ts" && : >"$f" && gzip -f -- "$f.$ts" 2>/dev/null
        ls -1t -- "$S_PATH"/logs/console.log.*.gz 2>/dev/null | tail -n +4 | while IFS= read -r x; do rm -f -- "$x"; done
    fi
    find "$DOC_BASE/addons/counterstrikesharp/logs" "$DOC_BASE/logs" -type f -mtime +14 -delete 2>/dev/null
    return 0
}

doc_chk_s_owner() {
    local n
    n=$(find "$S_PATH" -xdev ! -type l \( ! -user "$CS2_USER" -o ! -group "$CS2_GROUP" \) -print 2>/dev/null | head -n 500 | wc -l)
    DOC_MSG="$n file(s) not owned by $CS2_USER (the server cannot write them)"
    ((n == 0))
}
doc_fix_s_owner() { chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$S_PATH" 2>/dev/null; }

# broken links in addons: "ours" point into the shared folder / CS2 base (the doctor can rebuild them), the rest belong to the admin
doc_broken_links() {   # ours|other
    local l t own
    while IFS= read -r l; do
        t=$(readlink -- "$l"); own=0
        [[ $t == "$SHARED_DIR"/* || $t == "$BASE"/* ]] && own=1
        if [[ $1 == ours ]]; then ((own)) && printf '%s\n' "$l"; else ((own)) || printf '%s\n' "$l"; fi
    done < <(find "$DOC_BASE/addons" -xtype l 2>/dev/null)
}
doc_chk_s_links() {
    local n
    n=$(doc_broken_links ours | wc -l)
    DOC_MSG="$n broken plugin link(s) in addons (a plugin that cannot load)"
    ((n == 0))
}
doc_fix_s_links() {
    local l
    while IFS= read -r l; do rm -f -- "$l"; done < <(doc_broken_links ours)
    if ((SHARED_OK)); then DRY_RUN=0; sync_shared_current || true; fi
}
doc_chk_s_links2() {
    local n
    n=$(doc_broken_links other | wc -l)
    DOC_MSG="$n broken link(s) in addons that point outside the shared folder (remove them by hand)"
    ((n == 0))
}

doc_chk_s_plugdll() {
    local d name bad=""
    for d in "$DOC_BASE"/addons/counterstrikesharp/plugins/*/; do
        [[ -d $d ]] || continue
        name=${d%/}; name=${name##*/}
        [[ -f ${d}$name.dll ]] || bad+=" $name"
    done
    DOC_MSG="plugin folder(s) without a matching .dll (CounterStrikeSharp cannot load them):$bad"
    [[ -z $bad ]]
}

doc_chk_s_gameinfo() {
    local gi="$DOC_BASE/gameinfo.gi"
    [[ -d $DOC_BASE/addons/metamod ]] || return 0
    DOC_MSG="gameinfo.gi lost the Metamod line (a CS2 update overwrites it: no plugin would load)"
    [[ -f $gi ]] && grep -q 'csgo/addons/metamod' "$gi" 2>/dev/null
}
doc_fix_s_gameinfo() { patch_gameinfo; }

doc_core_json() { printf '%s' "$DOC_BASE/addons/counterstrikesharp/configs/core.json"; }
doc_chk_s_hotreload() {
    local cf; cf=$(doc_core_json)
    [[ -f $cf ]] || return 0
    DOC_MSG="CounterStrikeSharp watches plugin files and hot-reloads them: a file replaced on a running server is reloaded at a random moment (e.g. a map change)"
    ! jq -e 'any(to_entries[]; (.key | ascii_downcase) == "pluginhotreloadenabled" and .value == true)' "$cf" >/dev/null 2>&1
}
doc_fix_s_hotreload() {
    local cf tmp; cf=$(doc_core_json)
    doc_save "$cf"
    tmp=$(mktemp) || return 1
    if jq 'with_entries(if (.key | ascii_downcase) == "pluginhotreloadenabled" then .value = false else . end)' "$cf" >"$tmp" 2>/dev/null && jq -e . "$tmp" >/dev/null 2>&1; then
        cat -- "$tmp" >"$cf"
        info "Hot-reload turned off (applies on the next server start; use 'css_plugins reload NAME' to reload on purpose)."
    fi
    rm -f -- "$tmp"
}

doc_chk_s_wp() {
    local c="$DOC_BASE/addons/counterstrikesharp" miss="" d inf="$BASE/${CSGOREL:-game/csgo}/steam.inf"
    doc_wp_active || return 0
    [[ -s $c/gamedata/weaponpaints.json ]] || miss+=" gamedata"
    for d in PlayerSettingsApi AnyBaseLib MenuManagerApi; do [[ -d $c/shared/$d ]] || miss+=" $d"; done
    if [[ -f $inf ]] && { [[ ! -e $c/shared/.nexus-wp-refreshed ]] || [[ $inf -nt $c/shared/.nexus-wp-refreshed ]]; }; then
        miss+=" signature-not-refreshed-since-the-last-CS2-update"
    fi
    [[ -f $c/configs/core.json ]] && jq -e '.FollowCS2ServerGuidelines == true' "$c/configs/core.json" >/dev/null 2>&1 && miss+=" core.json"
    DOC_MSG="WeaponPaints is not ready on this server:$miss"
    [[ -z $miss ]]
}
doc_fix_s_wp() {
    wp_seed_server
    wp_runtime_server 1
    wp_patch_config >/dev/null 2>&1 || true
}

doc_chk_s_stale() {
    local start newer
    is_running "$DOC_ID" || return 0
    start=$(tmux_cs2 list-sessions -F '#{session_name} #{session_created}' 2>/dev/null | awk -v s="$DOC_SESS" '$1 == s {print $2; exit}')
    [[ $start =~ ^[0-9]+$ ]] || return 0
    newer=$({ find -L "$DOC_BASE/addons/counterstrikesharp/plugins" "$DOC_BASE/addons/counterstrikesharp/shared" -type f -name '*.dll' -newermt "@$start" -print -quit 2>/dev/null
              find -L "$DOC_BASE/addons/counterstrikesharp/gamedata" -type f -name '*.json' -newermt "@$start" -print -quit 2>/dev/null; } | head -n 1)
    DOC_MSG="plugin files changed after this server started: the running process still uses the old ones (crash risk) - restart it"
    [[ -z $newer ]]
}
doc_fix_s_stale() { info "Restarting '$S_NAME' ..."; stop_session "$DOC_ID" && start_server "$DOC_ID"; }

doc_cfg_files() {
    local f
    for f in "$DOC_BASE"/cfg/server.cfg "$DOC_BASE"/cfg/cs2nexus_settings.cfg "$DOC_BASE"/cfg/gamemode_*_server.cfg; do [[ -f $f ]] && printf '%s\n' "$f"; done
}
doc_chk_s_cfg() {
    local f bad=0
    while IFS= read -r f; do grep -qiE '^[[:space:]]*sv_hibernate_when_empty[[:space:]]+"?0"?([[:space:]]|$)' "$f" && bad=1; done < <(doc_cfg_files)
    DOC_MSG="sv_hibernate_when_empty is 0: an empty server keeps burning CPU"
    ((bad == 0))
}
doc_fix_s_cfg() {
    local f
    while IFS= read -r f; do
        grep -qiE '^[[:space:]]*sv_hibernate_when_empty[[:space:]]+"?0"?([[:space:]]|$)' "$f" || continue
        doc_save "$f"
        sed -i -E 's/^([[:space:]]*sv_hibernate_when_empty[[:space:]]+)"?0"?/\11/I' "$f"
        chown "$CS2_USER:$CS2_GROUP" -- "$f" 2>/dev/null
    done < <(doc_cfg_files)
}
doc_chk_s_heavy() {
    local f bad=""
    while IFS= read -r f; do
        grep -qiE '^[[:space:]]*tv_enable[[:space:]]+"?1"?([[:space:]]|$)' "$f" && bad+=" GOTV-on(tv_enable 1: costs CPU/RAM)"
        grep -qiE '^[[:space:]]*sv_cheats[[:space:]]+"?1"?([[:space:]]|$)' "$f" && bad+=" sv_cheats-1"
    done < <(doc_cfg_files)
    DOC_MSG="heavy / risky settings in the config:$bad (turn them off unless you need them)"
    [[ -z $bad ]]
}

# ------------------------------- the run --------------------------------------
doctor_servers() {
    local id sev
    local -a ids
    mapfile -t ids < <(jq -r '.[].id' "$DB" 2>/dev/null)
    if ((${#ids[@]} == 0)); then doc_section "SERVERS"; doc_pass "no servers registered yet"; return 0; fi
    for id in "${ids[@]}"; do
        if ! load_server "$id"; then doc_section "SERVER ID $id"; doc_fail "could not be loaded from $DB"; continue; fi
        if ! safe_server_path "$S_PATH" "$S_SLUG"; then doc_section "SERVER $S_NAME"; doc_fail "unsafe server path: $S_PATH"; continue; fi
        DOC_ID=$id; DOC_BASE="$S_PATH/$CSGOREL"; DOC_SESS=$(session_name "$id")
        doc_section "SERVER: $S_NAME (ID $id, port $S_PORT, $(is_running "$id" && echo online || echo offline))"
        doc_step "autostart / online state" doc_chk_s_online doc_fix_s_online
        doc_step "crash loop"               doc_chk_s_loop
        doc_step "crash markers in the log" doc_chk_s_crash
        doc_step "log size / old logs"      doc_chk_s_logs doc_fix_s_logs
        doc_step "file ownership"           doc_chk_s_owner doc_fix_s_owner
        doc_step "broken plugin links"      doc_chk_s_links doc_fix_s_links
        doc_step "other broken links"        doc_chk_s_links2
        doc_step "plugin folders have a .dll" doc_chk_s_plugdll
        doc_step "Metamod line in gameinfo.gi" doc_chk_s_gameinfo doc_fix_s_gameinfo fail
        doc_step "plugin hot-reload watcher" doc_chk_s_hotreload doc_fix_s_hotreload
        doc_step "WeaponPaints ready"        doc_chk_s_wp doc_fix_s_wp
        if ((DOC_RESTART)); then sev=doc_fix_s_stale; else sev=""; fi
        doc_step "running with the newest plugin files" doc_chk_s_stale "$sev"
        doc_step "server config (hibernate)" doc_chk_s_cfg doc_fix_s_cfg
        doc_step "server config (heavy options)" doc_chk_s_heavy
    done
    return 0
}

doctor_core() {   # <fix 0|1> [restart 0|1]
    DOC_FIX=${1:-0}; DOC_RESTART=${2:-0}
    DOC_N_OK=0; DOC_N_WARN=0; DOC_N_FAIL=0; DOC_N_FIXED=0; DOC_N_FIXABLE=0; DOC_BK=""
    install -d -m 750 -- "$DOC_LOG_DIR" 2>/dev/null
    DOC_LOGFILE="$DOC_LOG_DIR/doctor-$(date +%Y%m%d-%H%M%S).log"
    DRY_RUN=0
    need_layout || { err "The CS2 layout could not be detected (is CS2 installed?)."; return 1; }
    if ((DOC_FIX)); then
        lock_ops 60 || return 1
        info "Making a safety backup first ..."
        backup_run doctor >/dev/null 2>&1 || warn "The safety backup failed; changed files are still saved to the doctor folder."
    fi
    doc_section "MACHINE"
    doc_step "disk space"                 doc_chk_disk doc_fix_clean fail
    doc_step "free RAM"                   doc_chk_ram
    doc_step "swap (memory safety net)"   doc_chk_swap doc_fix_swap
    doc_step "out-of-memory kills"        doc_chk_oom
    doc_step "CPU load"                   doc_chk_load
    doc_step "clock synchronisation"      doc_chk_time doc_fix_time
    doc_step "kernel network/memory tuning" doc_chk_sysctl doc_fix_sysctl
    doc_step "unneeded system services"   doc_chk_services doc_fix_services
    doc_step "background jobs run at low priority" doc_chk_units doc_fix_units
    doc_section "LAUNCHER"
    doc_step "required tools installed"   doc_chk_cmds doc_fix_cmds fail
    doc_step "server list / registries are valid JSON" doc_chk_json "" fail
    doc_step "CS2 game files present"     doc_chk_base "" fail
    doc_step "unique ports"               doc_chk_ports "" fail
    doc_step "plugin registry matches the files" doc_chk_registry doc_fix_registry
    doc_step "plugin data vault is fresh" doc_chk_vault doc_fix_vault
    doc_step "orphan tmux sessions"       doc_chk_orphans doc_fix_orphans
    doc_step "secret files are private"   doc_chk_perms doc_fix_perms
    doc_step "watchdog (auto-restart)"    doc_chk_watchdog doc_fix_watchdog
    doc_step "data backups"               doc_chk_backup doc_fix_backup
    doc_step "web panel service"          doc_chk_panel doc_fix_panel
    if doc_wp_active; then
        doc_section "WEAPONPAINTS (skins)"
        doc_step "database login"         doc_chk_wpdb doc_fix_wpdb fail
        doc_step "MariaDB uses little RAM" doc_chk_mariadb_light doc_fix_mariadb_light
    fi
    doctor_servers
    ((DOC_FIX)) && unlock_ops
    printf '\n%s============================================================%s\n' "$CYAN" "$RESET"
    printf '  %sOK%s %d    %sWARNINGS%s %d    %sPROBLEMS%s %d    %sFIXED%s %d\n' "$GREEN" "$RESET" "$DOC_N_OK" "$YELLOW" "$RESET" "$DOC_N_WARN" "$RED" "$RESET" "$DOC_N_FAIL" "$CYAN" "$RESET" "$DOC_N_FIXED"
    if ((!DOC_FIX && DOC_N_FIXABLE > 0)); then
        printf '  %d issue(s) can be fixed and lightened automatically:  %s doctor --fix\n' "$DOC_N_FIXABLE" "$SELF"
    fi
    if ((DOC_FIX && DOC_N_WARN + DOC_N_FAIL > 0)); then
        printf '  What is left needs a decision from you (see the WARN / FAIL lines above).\n'
    fi
    ((DOC_FIX && DOC_N_FIXED > 0)) && printf '  Changed files were saved in %s (data backup: %s)\n' "${DOC_BK:-none}" "$BK_ROOT"
    printf '  Report: %s\n' "$DOC_LOGFILE"
    printf '%s============================================================%s\n' "$CYAN" "$RESET"
    ((DOC_N_FAIL == 0))
}

doctor_ui() {
    header "SERVER DOCTOR"
    info "Step 1: checking the whole machine, the launcher and every server (nothing is changed yet) ..."
    doctor_core 0 0
    if ((DOC_N_FIXABLE == 0)); then
        info "Nothing can be fixed automatically."
        return 0
    fi
    echo
    confirm_yn "Fix everything and make it lighter now? A data backup is made first. [Y/n]: " y || { info "Nothing was changed."; return 0; }
    local rs=0
    confirm_yn "Also restart servers that run OUTDATED plugin files (players are disconnected)? [y/N]: " n && rs=1
    echo
    info "Step 2: fixing and lightening ..."
    doctor_core 1 "$rs"
}

cli_doctor() {   # [--fix] [--restart]
    local fix=0 rs=0 a
    for a in "$@"; do
        case $a in
            --fix) fix=1 ;;
            --restart) rs=1 ;;
            *) err "Usage: $SELF doctor [--fix] [--restart]"; return 2 ;;
        esac
    done
    ((rs && !fix)) && { err "--restart only makes sense together with --fix."; return 2; }
    doctor_core "$fix" "$rs"
}


# =============================================================================
#  DATA VAULT: ONE place ($SHARED_DIR/vault) that keeps the data of every plugin
#  Plugins write their data (sqlite files, json databases, bans, saved choices ...) inside their own folder.
#  Removing or updating a plugin used to delete that folder, and the data with it.  Now:
#   - before a plugin folder is replaced or removed, everything the package did NOT ship (the runtime data) is copied to the vault
#   - when the plugin is installed again the data is put back (files that already exist are never overwritten)
#   - the data that stays per server (the registry's "per-server" items, e.g. bans) is copied to the vault too and
#     restored when a server loses it; a deleted server's data is removed from the vault with it
#   - the vault is part of every data backup, and 'nexus vault snapshot' / the Doctor refresh it
#  Program files (.dll .pdb .so .exe .deps.json) are never saved or restored, so an old build cannot come back.
#  Plugins that keep their data in MySQL (WeaponPaints) already use one central database; it is never touched here.
# =============================================================================
readonly VAULT_DIR="$SHARED_DIR/vault"
readonly VAULT_MANIFESTS="$VAULT_DIR/.manifests"
VAULT_LAST=0

vault_key_ok() { [[ -n $1 && $1 =~ ^[A-Za-z0-9._+@/-]+$ && $1 != *..* && $1 != /* && $1 != */ ]]; }
vault_is_program() { case ${1,,} in *.dll|*.pdb|*.so|*.exe|*.deps.json|*.runtimeconfig.json) return 0 ;; esac; return 1; }
vault_manifest_path() { printf '%s/%s.list' "$VAULT_MANIFESTS" "${1//\//__}"; }
vault_list_dir() { [[ -d $1 ]] && (cd -- "$1" && find . -type f -printf '%P\n' 2>/dev/null | LC_ALL=C sort); }

vault_init() {
    install -d -m 755 -o "$CS2_USER" -g "$CS2_GROUP" -- "$VAULT_DIR" "$VAULT_MANIFESTS" 2>/dev/null
}

# the list of files a package ships (so later we know what is data)
vault_manifest_write() {   # <key> <package dir>
    local key=$1 dir=$2 mf
    vault_key_ok "$key" || return 1
    vault_init || return 1
    mf=$(vault_manifest_path "$key")
    vault_list_dir "$dir" >"$mf.tmp" && mv -f -- "$mf.tmp" "$mf"
    chown "$CS2_USER:$CS2_GROUP" -- "$mf" 2>/dev/null
    return 0
}

vault_copy_file() {   # <src> <dst>: sqlite databases are copied consistently, the rest as it is
    local s=$1 d=$2
    mkdir -p -- "$(dirname -- "$d")" || return 1
    case ${s,,} in
        *.sqlite|*.sqlite3|*.db) bk_sqlite_copy "$s" "$d" 2>/dev/null || cp -p -- "$s" "$d" ;;
        *) cp -p -- "$s" "$d" ;;
    esac
}

# copy the runtime data of <dir> to the vault. <new package dir> (optional) lists more shipped files.
vault_rescue() {   # <key> <dir> [new package dir]
    local key=$1 dir=$2 newdir=${3:-} mf rel dst n=0
    local -A ship=()
    VAULT_LAST=0
    vault_key_ok "$key" || return 1
    [[ -d $dir && ! -L $dir ]] || return 0
    vault_init || return 1
    mf=$(vault_manifest_path "$key")
    if [[ -f $mf ]]; then while IFS= read -r rel; do ship[$rel]=1; done <"$mf"; fi
    if [[ -n $newdir && -d $newdir ]]; then while IFS= read -r rel; do ship[$rel]=1; done < <(vault_list_dir "$newdir"); fi
    dst="$VAULT_DIR/$key"
    while IFS= read -r rel; do
        [[ -n ${ship[$rel]:-} ]] && continue
        vault_is_program "$rel" && continue
        case $rel in *..*|*-wal|*-shm|*-journal) continue ;; esac
        [[ -f $dst/$rel && ! $dir/$rel -nt $dst/$rel ]] && continue
        vault_copy_file "$dir/$rel" "$dst/$rel" && n=$((n + 1))
    done < <(vault_list_dir "$dir")
    ((n > 0)) && chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$dst" 2>/dev/null
    VAULT_LAST=$n
    return 0
}

# put saved data back (never overwrites a file that exists)
vault_restore() {   # <key> <dir>
    local key=$1 dir=$2 src rel n=0
    vault_key_ok "$key" || return 1
    src="$VAULT_DIR/$key"
    [[ -d $src && -d $dir && ! -L $dir ]] || return 0
    while IFS= read -r rel; do
        [[ -e $dir/$rel || -L $dir/$rel ]] && continue
        vault_is_program "$rel" && continue
        [[ $rel == *..* ]] && continue
        mkdir -p -- "$(dirname -- "$dir/$rel")" && cp -p -- "$src/$rel" "$dir/$rel" && n=$((n + 1))
    done < <(vault_list_dir "$src")
    if ((n > 0)); then
        chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$dir" 2>/dev/null
        info "Put back $n saved data file(s) of '$key' from the vault."
    fi
    return 0
}

# the registry's per-server items of every plugin -> vault/servers/<slug>/<Plugin>/<item>
vault_snapshot_locals() {
    local P_NAME P_PATH P_LOCAL P_EXCL P_INCL id item src dst f rel
    local -a items
    ((SHARED_OK)) || return 0
    while IFS=$'\t' read -r P_NAME P_PATH P_LOCAL P_EXCL P_INCL; do
        [[ $P_LOCAL != "-" && -n $P_LOCAL ]] || continue
        valid_simple_name "$P_NAME" || continue
        IFS=, read -ra items <<<"$P_LOCAL"
        while IFS= read -r id; do
            load_server "$id" 2>/dev/null || continue
            safe_server_path "$S_PATH" "$S_SLUG" 2>/dev/null || continue
            for item in "${items[@]}"; do
                valid_local_path "$item" || continue
                src="$S_PATH/$CSGOREL/addons/$P_PATH/$item"
                [[ -e $src && ! -L $src ]] || continue
                dst="$VAULT_DIR/servers/$S_SLUG/$P_NAME/$item"
                if [[ -d $src ]]; then
                    while IFS= read -r rel; do
                        case $rel in *-wal|*-shm|*-journal) continue ;; esac
                        f="$src/$rel"
                        [[ -f $dst/$rel && ! $f -nt $dst/$rel ]] && continue
                        vault_copy_file "$f" "$dst/$rel"
                    done < <(vault_list_dir "$src")
                else
                    [[ -f $dst && ! $src -nt $dst ]] && continue
                    vault_copy_file "$src" "$dst"
                fi
            done
        done < <(jq -r '.[].id' "$DB" 2>/dev/null)
    done < <(plugins_rows)
    [[ -d $VAULT_DIR/servers ]] && chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$VAULT_DIR/servers" 2>/dev/null
    return 0
}

# the loaded server (S_*): a per-server item that is gone is copied back from the vault
vault_restore_server_locals() {
    local P_NAME P_PATH P_LOCAL P_EXCL P_INCL item src dst pd n=0
    local -a items
    ((SHARED_OK)) || return 0
    ((DRY_RUN)) && return 0
    [[ -d $VAULT_DIR/servers/$S_SLUG ]] || return 0
    safe_server_path "$S_PATH" "$S_SLUG" || return 0
    while IFS=$'\t' read -r P_NAME P_PATH P_LOCAL P_EXCL P_INCL; do
        [[ $P_LOCAL != "-" && -n $P_LOCAL ]] || continue
        valid_simple_name "$P_NAME" || continue
        pd="$S_PATH/$CSGOREL/addons/$P_PATH"
        [[ -d $pd && ! -L $pd ]] || continue
        IFS=, read -ra items <<<"$P_LOCAL"
        for item in "${items[@]}"; do
            valid_local_path "$item" || continue
            src="$VAULT_DIR/servers/$S_SLUG/$P_NAME/$item"
            dst="$pd/$item"
            [[ -e $src && ! -e $dst && ! -L $dst ]] || continue
            ensure_chain "$S_PATH/$CSGOREL" "$(dirname -- "$dst")" || continue
            if cp -a -- "$src" "$dst"; then chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$dst" 2>/dev/null; n=$((n + 1)); fi
        done
    done < <(plugins_rows)
    ((n > 0)) && info "$S_NAME: put back $n saved per-server item(s) from the vault."
    return 0
}

vault_snapshot_all() {   # every registered plugin + the per-server items
    local name rel src total=0
    ((SHARED_OK)) || return 0
    vault_init || return 1
    while IFS=$'\t' read -r name rel; do
        [[ -n $rel ]] || continue
        validate_plugin_rel "$rel" 1 || continue
        valid_simple_name "$name" || continue
        src=$(plugin_src_path "$rel")
        [[ -d $src && ! -L $src ]] || continue
        vault_rescue "$name" "$src"
        total=$((total + VAULT_LAST))
    done < <(jq -r '.[] | select(type=="object") | [.name, .path] | @tsv' "$SHARED_DB" 2>/dev/null)
    vault_snapshot_locals
    date +%s >"$VAULT_DIR/.snapshot" 2>/dev/null && chown "$CS2_USER:$CS2_GROUP" -- "$VAULT_DIR/.snapshot" 2>/dev/null
    VAULT_LAST=$total
    return 0
}

vault_forget_server() {   # <slug>: a deleted server takes its saved data with it
    [[ -n ${1:-} && $1 =~ ^[A-Za-z0-9._-]+$ && $1 != *..* ]] || return 0
    rm -rf --one-file-system -- "${VAULT_DIR:?}/servers/$1" 2>/dev/null
    return 0
}

vault_list_ui() {
    local d name n sz any=0
    if [[ ! -d $VAULT_DIR ]]; then info "The vault is empty (nothing was saved yet). Run 'Save a snapshot now'."; return 0; fi
    printf '  %-34s %8s  %s\n' "ITEM" "FILES" "SIZE"
    for d in "$VAULT_DIR"/*/ "$VAULT_DIR"/servers/*/*/; do
        [[ -d $d ]] || continue
        name=${d%/}; name=${name#"$VAULT_DIR"/}
        n=$(find "$d" -type f 2>/dev/null | wc -l); sz=$(du -sh -- "$d" 2>/dev/null | cut -f1)
        [[ $name == servers ]] && continue
        printf '  %-34s %8s  %s\n' "$name" "$n" "$sz"; any=1
    done
    ((any)) || info "The vault has no saved data yet."
    [[ -f $VAULT_DIR/.snapshot ]] && info "Last snapshot: $(date -d "@$(cat "$VAULT_DIR/.snapshot" 2>/dev/null)" '+%Y-%m-%d %H:%M' 2>/dev/null)"
    info "Folder: $VAULT_DIR   (included in every data backup)"
}

vault_restore_all() {   # put saved data back into every registered plugin and every server
    local name rel src id
    ((SHARED_OK)) || { err "Shared plugins are not set up."; return 1; }
    while IFS=$'\t' read -r name rel; do
        [[ -n $rel ]] || continue
        validate_plugin_rel "$rel" 1 || continue
        src=$(plugin_src_path "$rel"); [[ -d $src ]] || continue
        vault_restore "$name" "$src"
    done < <(jq -r '.[] | select(type=="object") | [.name, .path] | @tsv' "$SHARED_DB" 2>/dev/null)
    while IFS= read -r id; do
        load_server "$id" 2>/dev/null || continue
        vault_restore_server_locals
    done < <(jq -r '.[].id' "$DB" 2>/dev/null)
    ok "Saved data was put back wherever it was missing. Restart running servers to load it."
}

vault_menu() {
    local c name
    while :; do
        clear_screen; dsep
        printf '%s            DATA VAULT (all plugin data in one place)%s\n' "$BOLD" "$RESET"
        dsep; echo
        echo "  Removing / updating / reinstalling a plugin no longer loses its data:"
        echo "  it is saved in $VAULT_DIR and put back automatically."
        echo
        echo " 1) Show what is saved"
        echo " 2) Save a snapshot now"
        echo " 3) Put saved data back into the plugins now"
        echo " 4) Forget the saved data of one plugin"
        echo " 5) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) header "SAVED DATA"; vault_list_ui; pause ;;
            2) header "SNAPSHOT"; lock_ops 30 && { vault_snapshot_all; unlock_ops; ok "Snapshot done ($VAULT_LAST new/changed file(s) saved)."; }; pause ;;
            3) header "RESTORE FROM VAULT"; lock_ops 30 && { vault_restore_all; unlock_ops; }; pause ;;
            4) header "FORGET SAVED DATA"
               ask "Plugin name (q = cancel)" || continue; name=$ANSWER
               if vault_key_ok "$name" && [[ -d $VAULT_DIR/$name ]]; then
                   confirm_yn "Delete the saved data of '$name' for good? [y/N]: " n && { rm -rf --one-file-system -- "${VAULT_DIR:?}/$name"; rm -f -- "$(vault_manifest_path "$name")"; ok "Deleted."; }
               else err "Nothing saved under that name."; fi
               pause ;;
            5|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

cli_vault() {   # snapshot | restore | list
    DRY_RUN=0
    case ${1:-} in
        snapshot) lock_ops 30 || return 1; vault_snapshot_all; unlock_ops; ok "Snapshot done ($VAULT_LAST new/changed file(s) saved)." ;;
        restore)  lock_ops 30 || return 1; vault_restore_all; unlock_ops ;;
        list)     vault_list_ui ;;
        *) err "Usage: $SELF vault snapshot|restore|list"; return 2 ;;
    esac
}

# doctor: the vault is fresh and every registered plugin has a manifest
doc_chk_vault() {
    local snap age
    ((SHARED_OK)) || return 0
    [[ $(jq 'length' "$SHARED_DB" 2>/dev/null || echo 0) -gt 0 ]] || return 0
    snap=$(cat "$VAULT_DIR/.snapshot" 2>/dev/null); [[ $snap =~ ^[0-9]+$ ]] || snap=0
    age=$(( ($(date +%s) - snap) / 3600 ))
    DOC_MSG="the plugin data vault was never saved or is older than 48 hours (removing a plugin would lose its data)"
    DOC_INFO="saved ${age}h ago"
    ((snap > 0 && age < 48))
}
doc_fix_vault() { vault_snapshot_all; }


# Sync ALL shared plugins to the currently loaded server (S_*)
sync_shared_current() {
    local P_NAME P_PATH P_LOCAL P_EXCL P_INCL rc=0
    ((SHARED_OK)) || return 1
    need_layout || return 1
    lock_ops 30 || return 1
    wp_prepare_registry
    wp_share_server
    wp_seed_server
    wp_runtime_server
    panel_write_plugin_config_current
    while IFS=$'\t' read -r P_NAME P_PATH P_LOCAL P_EXCL P_INCL; do
        if ! validate_plugin_rel "$P_PATH" 1; then
            warn "Ignoring invalid shared plugin path in registry: $P_PATH"
            rc=1; continue
        fi
        sync_plugin_on_server "$P_NAME" "$PLUGIN_REL" "$P_LOCAL" "$P_EXCL" "$P_INCL" || rc=1
    done < <(plugins_rows)
    vault_restore_server_locals
    unlock_ops
    return $rc
}

# discover_shared_plugins: everything the admin drops into the shared folders
#   shared/addons/counterstrikesharp/plugins/<X>   and   shared/addons/metamod/plugins/<X>
# is registered automatically; the normal sync then links it into every server.
DISCOVERED=0
discover_shared_plugins() {
    local pre dir item name rel
    DISCOVERED=0
    ((SHARED_OK)) || return 0
    for pre in "${PLUGIN_PREFIXES[@]}"; do
        dir="$SHARED_ADDONS/$pre"
        [[ -d $dir && ! -L $dir ]] || continue
        while IFS= read -r -d '' item; do
            name=${item##*/}
            [[ $name == .* ]] && continue
            if [[ -L $item ]]; then warn "Ignoring symlink in the shared folder: $item"; continue; fi
            if ! valid_simple_name "$name"; then
                warn "Ignoring '$name' in the shared folder (unsupported characters)."; continue
            fi
            rel="$pre/$name"
            if jq -e --arg p "$rel" 'any(.[]; type=="object" and .path == $p)' "$SHARED_DB" >/dev/null 2>&1; then
                continue
            fi
            if [[ -n $(find "$item" -newermt '10 seconds ago' -print -quit 2>/dev/null) ]]; then
                info "'$name' was modified a moment ago (still being copied?); it is picked up on the next sync."
                continue
            fi
            if [[ -n $(find "$item" -type l -print -quit 2>/dev/null) ]]; then
                warn "'$name' contains symlinks; not registered."; continue
            fi
            if ((DRY_RUN)); then
                msg_dry "would register new shared plugin '$name' ($rel)"
                DISCOVERED=$((DISCOVERED + 1)); continue
            fi
            chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$item" 2>/dev/null
            if shared_update --arg n "$name" --arg p "$rel" '. += [{name:$n, path:$p}]'; then
                ok "New shared plugin registered: $name ($rel)"
                DISCOVERED=$((DISCOVERED + 1))
                if [[ -d $item && -n $(find "$item" -maxdepth 2 \( -iname 'data' -o -iname '*.sqlite' -o -iname '*.db' \) -print -quit 2>/dev/null) ]]; then
                    warn "'$name' seems to keep data inside its folder; that data would be SHARED by all servers."
                    warn "Use Shared Plugins -> Add Shared Plugin with '$rel' to mark per-server items (e.g. data)."
                fi
            fi
        done < <(find "$dir" -mindepth 1 -maxdepth 1 -print0)
    done
    return 0
}

sync_shared_all() {
    local id rc=0 total
    local -a ids
    shared_db_ok || return 1
    need_layout || return 1
    lock_ops 30 || return 1
    discover_shared_plugins
    total=$(jq 'length' "$SHARED_DB")
    if ((total == 0)); then
        info "No shared plugins registered. Drop plugin folders into $SHARED_ADDONS/<prefix>/ to share them."
        unlock_ops; return 0
    fi
    mapfile -t ids < <(jq -r '.[].id' "$DB")
    for id in "${ids[@]}"; do
        if ! load_server "$id"; then warn "Server ID $id could not be loaded."; rc=1; continue; fi
        if ((DRY_RUN && DISCOVERED > 0)); then
            info "(dry-run) newly found plugins are not linked yet; sync for real to link them."
            DISCOVERED=0
        fi
        sync_shared_current || rc=1
    done
    ((DRY_RUN)) || { aliases_deploy quiet; admins_deploy_defaults quiet; wp_patch_config || true; wp_report_restart; }
    unlock_ops
    return $rc
}

# --- option prompts (per-server data / excluded servers) ---
json_from_csv() {   # <csv|-> <strings|numbers>
    jq -nc --arg s "$1" --arg k "$2" \
        'if $s=="-" then [] elif $k=="numbers" then ($s|split(",")|map(tonumber)) else ($s|split(",")) end'
}

# import_plugin <server-plugin-path> <shared-src> <local-csv|->
# Copies (never moves) a plugin from a server into shared storage.
import_plugin() {
    local d=$1 src=$2 lcsv=$3 l
    local -a locs=()
    if [[ $lcsv != "-" ]]; then IFS=, read -ra locs <<<"$lcsv"; fi
    if [[ -n $(find "$d" -type l -print -quit 2>/dev/null) ]]; then
        err "The plugin contains symlinks; refusing to import it into shared storage."
        return 1
    fi
    ensure_chain "$SHARED_ADDONS" "$(dirname -- "$src")" || { err "Cannot create shared directories."; return 1; }
    cp -a -- "$d" "$src" || { err "Copy failed: $d"; rm -rf --one-file-system -- "$src"; return 1; }
    # per-server items stay on the server they came from and are not shared
    if [[ -d $src ]]; then
        for l in "${locs[@]}"; do
            if valid_local_path "$l" && shared_path_ok "$src/$l"; then rm -rf --one-file-system -- "${src:?}/$l"; fi
        done
    fi
    chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$src" || warn "chown failed on $src"
    return 0
}

# ------------------------------- Shared plugin UI ----------------------------
shared_add_ui() {
    header "ADD SHARED PLUGIN"
    shared_db_ok || return
    need_layout || return

    local pre rel pname src id cand_path n_cand=0 pick from_path created=0
    local -a cand_ids=() cand_paths=() cand_names=()
    local P_NAME P_PATH P_LOCAL P_EXCL P_INCL P_LOCAL_CUR="-" found=0

    echo "Enter the plugin path relative to a server's addons directory. Allowed:"
    for pre in "${PLUGIN_PREFIXES[@]}"; do echo "    $pre/<PLUGIN>"; done
    echo "Example: counterstrikesharp/plugins/MyPlugin"
    echo "(enter q to cancel)"; echo
    ask "Plugin path" || { info "Cancelled."; return; }
    validate_plugin_rel "$ANSWER" || return
    rel=$PLUGIN_REL; pname=${rel##*/}
    src=$(plugin_src_path "$rel")
    shared_path_ok "$src" || { err "Refusing unsafe shared path: $src"; return; }

    # already registered? -> only offer to change its options
    while IFS=$'\t' read -r P_NAME P_PATH P_LOCAL P_EXCL P_INCL; do
        if [[ $P_PATH == "$rel" ]]; then found=1; P_LOCAL_CUR=$P_LOCAL; fi
    done < <(plugins_rows)
    if ((found)); then
        info "'$pname' is already a plugin (per-server: $P_LOCAL_CUR)."
        confirm_yn "Change its options / assignment? [y/N]: " n || { info "Nothing changed."; return; }
        plugin_edit_registry "$rel"
        return
    fi

    lock_ops 30 || return
    if [[ -e $src || -L $src ]]; then
        if [[ -L $src ]]; then err "$src is a symlink; refusing."; unlock_ops; return; fi
        info "A shared copy already exists at $src; it will be registered as is."
        prompt_plugin_options "$(plugin_profile_local "$pname")" "-" "-" || { info "Cancelled."; unlock_ops; return; }
    else
        # find servers holding a REAL copy that can be imported
        while IFS= read -r id; do
            load_server "$id" || continue
            safe_server_path "$S_PATH" "$S_SLUG" || continue
            cand_path="$S_PATH/$CSGOREL/addons/$rel"
            if [[ -e $cand_path && ! -L $cand_path ]]; then
                cand_ids+=("$id"); cand_paths+=("$cand_path"); cand_names+=("$S_NAME")
            fi
        done < <(jq -r '.[].id' "$DB")
        n_cand=${#cand_ids[@]}
        if ((n_cand == 0)); then
            err "No shared copy exists and no server has a real copy of '$rel'."
            echo "Install the plugin on one server first (or place it in $src), then retry."
            unlock_ops; return
        fi
        echo
        echo "Import the plugin files from which server? (they are COPIED, nothing is moved)"
        for ((pick = 0; pick < n_cand; pick++)); do
            echo "  ${cand_ids[pick]}) ${cand_names[pick]}"
        done
        ask "Server ID" "${cand_ids[0]}" || { info "Cancelled."; unlock_ops; return; }
        from_path=""
        for ((pick = 0; pick < n_cand; pick++)); do
            [[ $ANSWER == "${cand_ids[pick]}" ]] && from_path=${cand_paths[pick]}
        done
        if [[ -z $from_path ]]; then err "Invalid server selection."; unlock_ops; return; fi
        prompt_plugin_options "$(plugin_profile_local "$pname")" "-" "-" || { info "Cancelled."; unlock_ops; return; }
        info "Copying plugin into shared storage..."
        import_plugin "$from_path" "$src" "$OPT_LOCAL_CSV" || { unlock_ops; return; }
        created=1
        ok "Copied to $src"
    fi

    if ! shared_update --arg n "$pname" --arg p "$rel" \
        --argjson l "$(json_from_csv "$OPT_LOCAL_CSV" strings)" \
        --argjson x "$(json_from_csv "$OPT_EXCL_CSV" numbers)" \
        --argjson i "$(json_from_csv "$OPT_INCL_CSV" numbers)" \
        '. += [{name:$n, path:$p}
               + (if ($l|length) > 0 then {local:$l} else {} end)
               + (if ($x|length) > 0 then {exclude:$x} else {} end)
               + (if ($i|length) > 0 then {include:$i} else {} end)]'; then
        err "Could not register the plugin."
        if ((created)) && shared_path_ok "$src"; then rm -rf --one-file-system -- "$src"; fi
        unlock_ops; return
    fi
    ok "Shared plugin '$pname' registered."
    echo
    info "Syncing all servers..."
    DRY_RUN=0
    if sync_shared_all; then ok "All servers are in sync."; else warn "Finished with skipped items (see above). Nothing was overwritten."; fi
    unlock_ops
}

shared_remove_ui() {
    header "REMOVE SHARED PLUGIN"
    shared_db_ok || return
    need_layout || return
    local total; total=$(jq 'length' "$SHARED_DB")
    if ((total == 0)); then warn "No shared plugins registered."; return; fi

    local i=0 idx rel src pname keep=0 fail=0 id dst
    local -a paths=()
    local P_NAME P_PATH P_LOCAL P_EXCL P_INCL
    while IFS=$'\t' read -r P_NAME P_PATH P_LOCAL P_EXCL P_INCL; do
        i=$((i + 1)); paths[i]=$P_PATH
        printf '%s) %s  (%s)\n' "$i" "$P_NAME" "$P_PATH"
    done < <(plugins_rows)
    echo
    ask "Plugin number to remove (q = cancel)" || { info "Cancelled."; return; }
    if ! [[ $ANSWER =~ ^[0-9]+$ ]] || ((10#$ANSWER < 1 || 10#$ANSWER > i)); then err "Invalid selection."; return; fi
    idx=$((10#$ANSWER))
    validate_plugin_rel "${paths[idx]}" || { err "Registry path is invalid; refusing to continue."; return; }
    rel=$PLUGIN_REL; pname=${rel##*/}
    src=$(plugin_src_path "$rel")
    shared_path_ok "$src" || { err "Unsafe shared path: $src"; return; }

    echo; sep
    echo "  Plugin : $pname ($rel)"
    echo "  Shared : $src"
    sep
    info "Only symlinks pointing into $SHARED_ADDONS are removed from servers."
    info "Real server-local plugin directories are never touched."
    if confirm_yn "Keep a real LOCAL copy of the plugin on each server (so they keep it)? [y/N]: " n; then keep=1; fi
    local in
    read -r -p "Type REMOVE to confirm: " in || exit 0
    if [[ $in != REMOVE ]]; then info "Cancelled."; return; fi

    lock_ops 30 || return
    DRY_RUN=0
    # save the plugin's data first: reinstalling it later brings everything back
    vault_rescue "$pname" "$src"
    vault_snapshot_locals
    ((VAULT_LAST > 0)) && info "$VAULT_LAST data file(s) of '$pname' were saved in the vault ($VAULT_DIR) and come back when you install it again."
    while IFS= read -r id; do
        load_server "$id" || continue
        if ! safe_server_path "$S_PATH" "$S_SLUG"; then
            warn "Unsafe path for $S_NAME; skipped."; fail=1; continue
        fi
        dst="$S_PATH/$CSGOREL/addons/$rel"
        if unlink_managed "$dst" "$src" "$keep"; then
            ((UNLINKED > 0)) && ok "$S_NAME: removed $UNLINKED link(s)$( ((keep)) && printf ', local copy kept')"
        else
            warn "Safety check failed on $S_NAME ($dst)."; fail=1
        fi
    done < <(jq -r '.[].id' "$DB")

    if ((fail)); then
        warn "Aborted: registry entry and shared source were NOT removed."
        unlock_ops; return
    fi
    if ! shared_update --arg p "$rel" 'map(select(.path != $p))'; then
        err "Could not update the registry; shared source kept."
        unlock_ops; return
    fi
    if [[ -e $src || -L $src ]]; then
        if shared_path_ok "$src"; then
            rm -rf --one-file-system -- "$src" && ok "Shared source removed." || err "Could not remove $src"
        else
            warn "Shared source path failed the safety check; not deleted: $src"
        fi
    fi
    ok "Shared plugin '$pname' removed."
    unlock_ops
}

# state of a plugin on the loaded server, for the list view
plugin_state() {   # <rel> <src> <has-local 0|1> <excluded 0|1>
    local rel=$1 src=$2 haslocal=$3 excl=$4 dst t
    dst="$S_PATH/$CSGOREL/addons/$rel"
    if ((excl)); then echo excluded; return; fi
    if [[ -L $dst ]]; then
        t=$(readlink -- "$dst")
        if [[ $t == "$src" ]]; then echo linked
        elif [[ ! -e $dst ]]; then echo broken-link
        else echo foreign-link; fi
    elif [[ -d $dst ]]; then
        if ((haslocal)) && [[ -n $(find "$dst" -type l -lname "$src/*" -print -quit 2>/dev/null) ]]; then
            echo linked+per-server
        else
            echo local-copy
        fi
    elif [[ -e $dst ]]; then echo local-file
    else echo missing; fi
}

shared_list_ui() {
    header "SHARED PLUGINS"
    shared_db_ok || return
    need_layout || return
    local total; total=$(jq 'length' "$SHARED_DB")
    if ((total == 0)); then warn "No shared plugins registered."; return; fi
    local -a ids
    mapfile -t ids < <(jq -r '.[].id' "$DB")
    local P_NAME P_PATH P_LOCAL P_EXCL P_INCL i=0 id line src excl haslocal
    while IFS=$'\t' read -r P_NAME P_PATH P_LOCAL P_EXCL P_INCL; do
        i=$((i + 1))
        printf '%s%s) %s%s\n' "$BOLD" "$i" "$P_NAME" "$RESET"
        if ! validate_plugin_rel "$P_PATH" 1; then
            printf '   %sInvalid path in registry: %s%s\n' "$RED" "$P_PATH" "$RESET"; continue
        fi
        src=$(plugin_src_path "$PLUGIN_REL")
        printf '   Path         : %s\n' "$PLUGIN_REL"
        if [[ -e $src ]]; then printf '   Shared source: present\n'
        else printf '   Shared source: %sMISSING%s\n' "$RED" "$RESET"; fi
        printf '   Per-server   : %s\n' "$([[ $P_LOCAL == - ]] && echo none || echo "$P_LOCAL")"
        printf '   Only on IDs  : %s\n' "$([[ $P_INCL == - ]] && echo 'all servers' || echo "$P_INCL")"
        printf '   Excluded IDs : %s\n' "$([[ $P_EXCL == - ]] && echo none || echo "$P_EXCL")"
        printf '   Source       : %s\n' "$(jq -r --arg p "$P_PATH" '[.[] | select(type=="object" and .path == $p) | ((.source // "manual") + (if (.dllver // "") != "" then "  (v" + .dllver + ")" else "" end))][0] // "manual"' "$SHARED_DB")"
        line=""
        haslocal=0; [[ $P_LOCAL != - ]] && haslocal=1
        for id in "${ids[@]}"; do
            load_server "$id" || continue
            excl=0; [[ ,$P_EXCL, == *",$S_ID,"* ]] && excl=1
            if [[ $P_INCL != - && ,$P_INCL, != *",$S_ID,"* ]]; then excl=1; fi
            line+="$S_NAME: $(plugin_state "$PLUGIN_REL" "$src" "$haslocal" "$excl");  "
        done
        printf '   Servers      : %s\n\n' "$line"
    done < <(plugins_rows)
}

shared_sync_ui() {   # $1 = 1 for dry-run
    local dry=${1:-0}
    if ((dry)); then header "SYNC ALL SERVERS (DRY-RUN)"; else header "SYNC ALL SERVERS"; fi
    shared_db_ok || return
    DRY_RUN=$dry
    if sync_shared_all; then
        if ((dry)); then info "Dry-run finished. Nothing was changed."; else ok "All servers are in sync."; fi
    else
        warn "Finished with skipped items (see above). Nothing was overwritten."
    fi
    DRY_RUN=0
}

# ------------------------------- Server list UI ------------------------------
print_choices() {
    local id name port path
    while IFS=$'\t' read -r id name port path; do
        printf '%s) %s | Port: %s | ' "$id" "$name" "$port"
        status_colored "$(status_of "$id")"; password_tag "$path" "$id"; echo
    done < <(jq -r '.[] | [.id,.name,.port,(.path // "")] | @tsv' "$DB")
}

# pick_server "Prompt"  -> sets PICK_ID
PICK_ID=""
pick_server() {
    local in
    if [[ $(db_count) -eq 0 ]]; then warn "No servers registered."; return 1; fi
    print_choices; echo
    read -r -p "$1" in || exit 0
    in=$(trim "$in")
    [[ -z $in || $in == q || $in == Q ]] && { info "Cancelled."; return 1; }
    if ! [[ $in =~ ^[0-9]+$ ]]; then err "Invalid ID."; return 1; fi
    in=$((10#$in))
    if ! load_server "$in"; then err "Server ID $in not found."; return 1; fi
    PICK_ID=$in
    return 0
}

# ------------------------------- Start / Stop --------------------------------
start_server() {
    local id=$1 sess gdir cmd logf maparg
    load_server "$id" || { err "Server ID $id not found."; return 1; }
    sess=$(session_name "$id")

    if is_running "$id"; then
        warn "'$S_NAME' is already running (tmux session: $sess)."
        return 0
    fi
    if ! safe_server_path "$S_PATH" "$S_SLUG"; then
        err "Unsafe or inconsistent server path in database: $S_PATH"
        return 1
    fi
    [[ -d $S_PATH ]] || { err "Server directory missing: $S_PATH"; return 1; }
    if port_in_use "$S_PORT"; then
        err "Port $S_PORT is already in use by another process."
        return 1
    fi

    info "Syncing server files with base installation..."
    sync_server_tree "$S_PATH" || return 1
    write_server_cfg "$S_PATH" "$S_NAME" "$S_MAX" "$S_PORT" "$id" || return 1

    # shared plugins: never blocks the start and never deletes anything
    if ((SHARED_OK)); then
        DRY_RUN=0
        discover_shared_plugins
        sync_shared_current || warn "Some shared plugins could not be synchronised safely (see above). Existing files were left untouched."
        wp_config_watch "$id"; WP_NEEDS_RESTART=0
    else
        warn "Shared plugin registry is invalid; skipping shared plugin sync."
    fi

    gdir="$S_PATH${GAMEREL:+/$GAMEREL}"
    [[ -x $gdir/cs2.sh ]] || { err "Launcher not executable: $gdir/cs2.sh"; return 1; }

    # Workshop maps are started with +host_workshop_map <id>, normal maps with +map <name>
    if [[ $S_MAP == workshop:* ]]; then printf -v maparg '+host_workshop_map %q' "${S_MAP#workshop:}"
    else printf -v maparg '+map %q' "$S_MAP"; fi
    printf -v cmd 'cd %q && exec ./cs2.sh -dedicated -console -usercon -port %q +game_type %q +game_mode %q -maxplayers %q %s' \
        "$gdir" "$S_PORT" "$(launch_value "$id" game_type 0)" "$(launch_value "$id" game_mode 1)" "$S_MAX" "$maparg"

    clear_manual_stop "$id"
    info "Starting '$S_NAME' in tmux session $sess ..."
    if ! tmux_cs2 new-session -d -s "$sess" -c "$gdir" "$cmd"; then
        err "Failed to create tmux session $sess."
        return 1
    fi

    logf="$S_PATH/logs/console.log"
    printf -v cmd 'cat >> %q' "$logf"
    tmux_cs2 pipe-pane -o -t "=$sess:" "$cmd" 2>/dev/null || warn "Could not attach console logging."

    sleep 3
    if ! is_running "$id"; then
        err "Server exited right after start. Run its launcher manually to see the error:"
        echo "  runuser -u $CS2_USER -- bash -c 'cd $gdir && ./cs2.sh -dedicated -console -port $S_PORT $maparg'"
        notify_server_event fail_start "$id" || true
        return 1
    fi
    ok "'$S_NAME' started (port $S_PORT, session $sess)."
    echo "   Attach : runuser -u $CS2_USER -- tmux attach -t $sess   (detach: Ctrl+B then D)"
    notify_server_event start "$id" || true
    rm -f -- "$STATE_DIR/crash-notified-$id"
}

# Gracefully stop ONLY this server's tmux session
stop_session() {
    local id=$1 sess i was=0
    sess=$(session_name "$id")
    mark_manual_stop "$id"      # the watchdog must not restart an intentional stop
    is_running "$id" || return 0
    was=1

    tmux_cs2 send-keys -t "=$sess:" "quit" Enter 2>/dev/null
    for ((i = 0; i < STOP_TIMEOUT; i++)); do
        if ! is_running "$id"; then
            ((was)) && notify_server_event stop "$id" || true
            return 0
        fi
        sleep 1
    done
    warn "Server did not quit gracefully; closing tmux session $sess."
    tmux_cs2 kill-session -t "=$sess" 2>/dev/null
    sleep 1
    if is_running "$id"; then err "Could not stop session $sess."; return 1; fi
    ((was)) && notify_server_event stop "$id" || true
    return 0
}

stop_server_ui() {
    header "STOP SERVER"
    pick_server "Server ID to stop (q = cancel): " || return
    if ! is_running "$PICK_ID"; then warn "'$S_NAME' is not running."; return; fi
    confirm_yn "Stop '$S_NAME' (port $S_PORT)? [y/N]: " n || { info "Cancelled."; return; }
    info "Stopping '$S_NAME'..."
    if stop_session "$PICK_ID"; then ok "'$S_NAME' stopped."; else err "Stop failed."; fi
}

start_server_ui() {
    header "START SERVER"
    pick_server "Server ID to start (q = cancel): " || return
    start_server "$PICK_ID"
}

restart_server_ui() {
    header "RESTART SERVER"
    pick_server "Server ID to restart (q = cancel): " || return
    local id=$PICK_ID name=$S_NAME
    if is_running "$id"; then
        confirm_yn "'$name' is running; players will be disconnected. Restart? [y/N]: " n \
            || { info "Cancelled."; return; }
        info "Stopping '$name'..."
        stop_session "$id" || { err "Restart aborted: could not stop server."; return; }
        ok "Stopped."
    fi
    start_server "$id"
}

# ------------------------------- Create Server -------------------------------
create_server_ui() {
    header "CREATE SERVER"
    echo "(enter q at any prompt to cancel)"; echo

    local name slug maxp port map gslt="" id srv name_re='^[A-Za-z0-9][A-Za-z0-9 _.()-]{0,62}$'

    while :; do
        ask "Server name" || { info "Cancelled."; return; }
        name=$ANSWER
        if [[ -z $name ]]; then err "Name cannot be empty."; continue; fi
        if ! [[ $name =~ $name_re ]]; then
            err "Use 1-63 chars: letters, digits, space, _ . ( ) -  (must start with a letter/digit)."
            continue
        fi
        slug=$(printf '%s' "${name,,}" | sed -E 's/[^a-z0-9]+/-/g; s/^-+//; s/-+$//')
        if [[ -z $slug ]]; then err "Name produces an empty directory name."; continue; fi
        if db_name_taken "$name" "$slug"; then err "A server with this name already exists."; continue; fi
        if [[ -e $SERVERS_DIR/$slug || -L $SERVERS_DIR/$slug ]]; then
            err "Directory $SERVERS_DIR/$slug already exists."; continue
        fi
        break
    done

    while :; do
        ask "Client limit" "$(launch_value 0 maxplayers 13)" || { info "Cancelled."; return; }
        maxp=$ANSWER
        if [[ $maxp =~ ^[0-9]+$ ]] && ((10#$maxp >= 1 && 10#$maxp <= MAX_CLIENTS)); then
            maxp=$((10#$maxp)); break
        fi
        err "Client limit must be a number between 1 and $MAX_CLIENTS."
    done

    local defport; defport=$(suggest_port)
    while :; do
        ask "Server port" "$defport" || { info "Cancelled."; return; }
        port=$ANSWER
        if ! [[ $port =~ ^[0-9]+$ ]] || ((10#$port < MIN_PORT || 10#$port > MAX_PORT)); then
            err "Port must be a number between $MIN_PORT and $MAX_PORT."; continue
        fi
        port=$((10#$port))
        if db_port_registered "$port"; then err "Port $port is already registered. Choose another."; continue; fi
        if port_in_use "$port"; then err "Port $port is currently in use on this system. Choose another."; continue; fi
        break
    done

    echo
    info "Map: type a map name (e.g. de_dust2) or a Steam Workshop map ID / link (started with host_workshop_map)."
    while :; do
        ask "Map" "$(launch_value 0 map "$DEFAULT_MAP")" || { info "Cancelled."; return; }
        if normalize_map "$ANSWER"; then map=$MAP_NORM; break; fi
        err "Invalid map. Use a map name (letters, digits, _) or a Workshop ID / link."
    done

    echo
    info "Every CS2 server needs its own Steam Game Server Login Token (GSLT)."
    info "Create one at https://steamcommunity.com/dev/managegameservers (App ID 730)."
    info "It is optional now; you can add or change it later in Server Settings -> Basics."
    while :; do
        ask "GSLT token (press Enter to skip)" "none" || { info "Cancelled."; return; }
        gslt=$ANSWER; [[ ${gslt,,} == none ]] && gslt=""
        if [[ -z $gslt ]] || valid_gslt "$gslt"; then break; fi
        err "That does not look like a GSLT token (16-64 letters/digits)."
    done

    echo; sep
    echo "  Name      : $name"
    echo "  Directory : $SERVERS_DIR/$slug"
    echo "  Port      : $port"
    echo "  Clients   : $maxp"
    echo "  Map       : $(map_label "$map")"
    echo "  GSLT      : $([[ -n $gslt ]] && echo '(set)' || echo '(not set)')"
    echo "  Settings  : the DEFAULT settings are applied"
    sep; echo

    create_server_core "$name" "$slug" "$maxp" "$port" "$map" || return
    id=$CREATED_ID
    if [[ -n $gslt ]]; then
        if server_set_gslt "$id" "$gslt"; then ok "GSLT token saved in server.cfg (sv_setsteamaccount)."
        else info "Token not saved. Set it later in Server Settings -> Basics."; fi
    fi
    echo
    if confirm_yn "Start server now? [Y/n]: " y; then
        start_server "$id"
    fi
}

# ------------------------------- List / Status -------------------------------
print_server_table() {
    if [[ $(db_count) -eq 0 ]]; then warn "No servers registered."; return; fi
    printf '%s%-4s %-28s %-7s %-8s %s%s\n' "$BOLD" ID Name Port Status "Client Limit" "$RESET"
    sep
    local id name port max path
    while IFS=$'\t' read -r id name port max path; do
        printf '%-4s %-28.28s %-7s ' "$id" "$name" "$port"
        status_colored "$(status_of "$id")"; password_tag "$path" "$id"
        printf ' %s\n' "$max"
    done < <(jq -r '.[] | [.id,.name,.port,.maxplayers,(.path // "")] | @tsv' "$DB")
    sep
}

list_servers_ui() {
    header "SERVER LIST"
    print_server_table
}

print_server_status() {
    local st; st=$(status_of "$S_ID")
    echo; sep
    printf '  %-14s %s\n' "Name:"         "$S_NAME"
    printf '  %-14s %s\n' "Port:"         "$S_PORT"
    printf '  %-14s %s\n' "Map:"          "$(map_label "$S_MAP")"
    printf '  %-14s %s\n' "Client limit:" "$S_MAX"
    printf '  %-14s %s\n' "Path:"         "$S_PATH"
    printf '  %-14s ' "Status:"; status_colored "$st"; password_tag "$S_PATH" "$S_ID"; echo
    printf '  %-14s %s\n' "TMUX session:" "$(session_name "$S_ID")"
    if [[ $st == ONLINE ]] && query_players "$S_ID"; then
        printf '  %-14s %s / %s\n' "Players:" "$P_HUMANS" "$S_MAX"
    fi
    sep
}

status_ui() {
    header "SERVER STATUS"
    pick_server "Server ID (q = cancel): " || return
    print_server_status
}

# ------------------------------- Players / History ---------------------------
P_HUMANS=0; P_BOTS=0; P_ROWS=()

# query_players <id> : sends "status" to the server console via tmux and parses it
query_players() {
    local id=$1 sess out line block
    local re="^[[:space:]]*([0-9]+)[[:space:]]+([0-9:]+)[[:space:]]+([0-9]+)[[:space:]]+([0-9]+)[[:space:]]+([a-z]+)[[:space:]]+([0-9]+)[[:space:]]+([^[:space:]]+)[[:space:]]+'(.*)'[[:space:]]*\$"
    P_HUMANS=0; P_BOTS=0; P_ROWS=()
    is_running "$id" || return 1
    sess=$(session_name "$id")

    tmux_cs2 send-keys -t "=$sess:" "status" Enter || return 1
    sleep 2
    out=$(tmux_cs2 capture-pane -p -J -t "=$sess:" -S -300) || return 1

    line=$(grep -E '^players *:' <<<"$out" | tail -n 1)
    if [[ $line =~ ([0-9]+)[[:space:]]+humans?,[[:space:]]+([0-9]+)[[:space:]]+bots? ]]; then
        P_HUMANS=${BASH_REMATCH[1]}; P_BOTS=${BASH_REMATCH[2]}
    else
        return 1
    fi

    block=$(awk '/^ *id +time +ping/ {buf=""; found=1; next} found {buf = buf $0 "\n"} END {printf "%s", buf}' <<<"$out")
    while IFS= read -r line; do
        if [[ $line =~ $re ]]; then
            [[ ${BASH_REMATCH[7]} == "BOT" ]] && continue
            P_ROWS+=("${BASH_REMATCH[8]}"$'\t'"${BASH_REMATCH[2]}"$'\t'"${BASH_REMATCH[3]}"$'\t'"${BASH_REMATCH[5]}")
        fi
    done <<<"$block"
    return 0
}

# show_history <server path> <count>  (reads the server's own game logs)
show_history() {
    local path=$1 n=$2 logdir="$1/$CSGOREL/logs" lines d t typ nm sid c
    local -a files
    mapfile -t files < <(find "$logdir" -maxdepth 1 -type f -name '*.log' -printf '%T@ %p\n' 2>/dev/null \
        | sort -n | tail -n 10 | cut -d' ' -f2-)
    if ((${#files[@]} == 0)); then
        warn "No game logs yet. Logging is enabled automatically; restart the server once."
        return
    fi
    lines=$(cat -- "${files[@]}" | sed -nE \
        -e 's|^L ([0-9]{2}/[0-9]{2}/[0-9]{4}) - ([0-9:]{8}): "(.*)<[0-9]+><(\[U:[0-9]+:[0-9]+\])><[^>]*>" entered the game.*|\1\t\2\tJOIN\t\3\t\4|p' \
        -e 's|^L ([0-9]{2}/[0-9]{2}/[0-9]{4}) - ([0-9:]{8}): "(.*)<[0-9]+><(\[U:[0-9]+:[0-9]+\])><[^>]*>" disconnected.*|\1\t\2\tLEAVE\t\3\t\4|p' \
        | tail -n "$n")
    if [[ -z $lines ]]; then warn "No join/leave events recorded yet."; return; fi
    printf '%s%-10s %-8s %-6s %-24s %s%s\n' "$BOLD" Date Time Event Player SteamID "$RESET"
    sep
    while IFS=$'\t' read -r d t typ nm sid; do
        if [[ $typ == JOIN ]]; then c=$GREEN; else c=$RED; fi
        printf '%-10s %-8s %s%-6s%s %-24.24s %s\n' "$d" "$t" "$c" "$typ" "$RESET" "$nm" "$sid"
    done <<<"$lines"
}

players_ui() {
    header "PLAYERS & HISTORY"
    pick_server "Server ID (q = cancel): " || return
    local id=$PICK_ID path=$S_PATH name=$S_NAME max=$S_MAX n row pname ptime pping pstate i=0
    detect_layout || return

    echo; sep
    printf '%sLive players - %s%s\n' "$BOLD" "$name" "$RESET"
    sep
    if ! is_running "$id"; then
        warn "Server is OFFLINE."
    else
        info "Querying server console..."
        if query_players "$id"; then
            printf 'Players: %s%s%s / %s   (bots: %s)\n\n' "$GREEN" "$P_HUMANS" "$RESET" "$max" "$P_BOTS"
            if ((${#P_ROWS[@]})); then
                printf '%s%-4s %-30s %-10s %-6s %s%s\n' "$BOLD" "#" Name Connected Ping State "$RESET"
                for row in "${P_ROWS[@]}"; do
                    IFS=$'\t' read -r pname ptime pping pstate <<<"$row"
                    i=$((i + 1))
                    printf '%-4s %-30.30s %-10s %-6s %s\n' "$i" "$pname" "$ptime" "$pping" "$pstate"
                done
            else
                echo "  (no human players connected)"
            fi
        else
            warn "Could not read the status output (server may still be loading)."
        fi
    fi

    echo; sep
    printf '%sJoin / leave history%s\n' "$BOLD" "$RESET"
    sep
    ask "Show last N events" 30 || return
    n=$ANSWER
    [[ $n =~ ^[0-9]+$ ]] && ((10#$n > 0)) || n=30
    show_history "$path" "$((10#$n))"
}

# ------------------------------- Delete Server -------------------------------
delete_server_ui() {
    header "DELETE SERVER"
    pick_server "Server ID to delete (q = cancel): " || return
    local id=$PICK_ID

    if ! safe_server_path "$S_PATH" "$S_SLUG"; then
        err "Refusing to delete: unsafe or inconsistent path in database ($S_PATH)."
        return
    fi
    if jq -e --argjson id "$id" --arg p "$S_PATH" 'any(.[]; .id != $id and .path == $p)' "$DB" >/dev/null 2>&1; then
        err "Refusing to delete: another registered server uses the same path."
        return
    fi

    echo; sep
    echo "  Name : $S_NAME"
    echo "  Port : $S_PORT"
    echo "  Path : $S_PATH"
    sep
    warn "This removes the server directory, its cfg/addons copies and its registry entry."
    info "The base installation ($BASE) and shared plugins are NOT touched; only symlinks are removed."
    echo
    local in
    read -r -p "Type DELETE to confirm: " in || exit 0
    if [[ $in != "DELETE" ]]; then info "Cancelled."; return; fi

    if is_running "$id"; then
        info "Stopping running server..."
        stop_session "$id" || { err "Cannot stop server; deletion aborted."; return; }
        ok "Server stopped."
    fi

    if [[ -e $S_PATH || -L $S_PATH ]]; then
        # re-validate right before the destructive command
        safe_server_path "$S_PATH" "$S_SLUG" || { err "Path check failed; deletion aborted."; return; }
        if ! rm -rf --one-file-system -- "$S_PATH"; then
            err "Failed to remove $S_PATH. Registry entry kept."
            return
        fi
    fi
    vault_forget_server "${S_SLUG:-}"
    if [[ -d $BASE/game || -d $BASE ]]; then :; else err "Base installation missing after delete!"; fi

    if db_update --argjson id "$id" 'map(select(.id != $id))'; then
        clear_server_state "$id"
        ok "Server '$S_NAME' deleted."
    else
        err "Directory removed but registry entry could not be deleted. Edit $DB manually."
    fi
}

# =============================================================================
#  SERVER CONSOLE
# =============================================================================
# console_send <id> <command>: types a command into the real CS2 console
console_send() {
    local id=$1 cmd=$2 sess first
    if [[ -z $cmd ]]; then err "Command cannot be empty."; return 1; fi
    if [[ $cmd =~ [[:cntrl:]] ]]; then err "Control characters / newlines are not allowed."; return 1; fi
    if ((${#cmd} > 400)); then err "Command is too long (max 400 characters)."; return 1; fi
    is_running "$id" || { err "Server is not running."; return 1; }
    sess=$(session_name "$id")
    tmux_cs2 send-keys -t "=$sess:" -l -- "$cmd" || return 1
    tmux_cs2 send-keys -t "=$sess:" Enter || return 1
    first=${cmd%%[[:space:]]*}
    case ${first,,} in quit|exit) mark_manual_stop "$id" ;; esac
    return 0
}

# broadcast_cmd <command>: to every RUNNING server
broadcast_cmd() {
    local cmd=$1 id rc=0
    local -a ids
    mapfile -t ids < <(jq -r '.[].id' "$DB")
    for id in "${ids[@]}"; do
        load_server "$id" || continue
        if ! is_running "$id"; then msg_skip "$S_NAME is offline"; continue; fi
        if console_send "$id" "$cmd"; then ok "$S_NAME: command sent"; else err "$S_NAME: could not send command"; rc=1; fi
    done
    return $rc
}

console_attach_ui() {   # $1 = 1 for read-only
    local ro=${1:-0} id name sess in
    local -a flags=()
    if ((ro)); then header "SERVER CONSOLE (READ-ONLY)"; else header "SERVER CONSOLE"; fi
    pick_server "Server ID (q = cancel): " || return
    id=$PICK_ID; name=$S_NAME
    sess=$(session_name "$id")
    if ! is_running "$id"; then
        err "$name is offline."
        echo "Start it first."
        return
    fi
    ((ro)) && flags=(-r)
    echo
    if ((ro)); then info "Attaching to $name console in READ-ONLY mode (you can watch, not type)."
    else info "Attached to $name console. You have full access; type normal CS2 commands."; fi
    info "To return to manager without stopping the server:"
    info "Ctrl+B, then D"
    if [[ -n ${TMUX:-} ]]; then
        warn "The manager is running inside tmux: press Ctrl+B twice, then D to detach the console."
    fi
    echo
    read -r -p "Press Enter to attach..." in || exit 0
    trap ':' INT
    tmux_cs2 attach-session "${flags[@]}" -t "=$sess"
    restore_int_trap
    echo
    if is_running "$id"; then ok "Back in the manager. $name is still running."
    else warn "$name is no longer running."; fi
}

console_send_ui() {
    header "SEND CONSOLE COMMAND"
    pick_server "Server ID (q = cancel): " || return
    local id=$PICK_ID
    if ! is_running "$id"; then err "$S_NAME is offline."; echo "Start it first."; return; fi
    warn "To stop a server on purpose use 'Stop Server' (a 'quit' typed here may be restarted by the watchdog)."
    ask "Command (e.g. status, say Hello, changelevel de_dust2)" || { info "Cancelled."; return; }
    if console_send "$id" "$ANSWER"; then ok "Command sent to $S_NAME."; fi
}

console_broadcast_ui() {
    header "BROADCAST COMMAND"
    info "The command is sent to every RUNNING server (example: say Server restarts soon)."
    ask "Command" || { info "Cancelled."; return; }
    confirm_yn "Send '$ANSWER' to all running servers? [y/N]: " n || { info "Cancelled."; return; }
    broadcast_cmd "$ANSWER"
}

console_menu() {
    local c
    while :; do
        clear_screen
        dsep
        printf '%s             SERVER CONSOLE%s\n' "$BOLD" "$RESET"
        dsep
        echo
        echo "1) Attach (full interactive)"
        echo "2) Attach read-only (view only)"
        echo "3) Send one command (no attach)"
        echo "4) Broadcast command to all running servers"
        echo "5) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) console_attach_ui 0; pause ;;
            2) console_attach_ui 1; pause ;;
            3) console_send_ui;     pause ;;
            4) console_broadcast_ui; pause ;;
            5|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

# =============================================================================
#  LOG VIEWER
# =============================================================================
logs_ui() {
    header "LOG VIEWER"
    pick_server "Server ID (q = cancel): " || return
    need_layout || return
    local choice n file
    echo
    echo "1) Game log (newest file in $CSGOREL/logs)"
    echo "2) Console output log (logs/console.log)"
    echo
    read -r -p "Select: " choice || exit 0
    case "$(trim "$choice")" in
        1) file=$(find "$S_PATH/$CSGOREL/logs" -maxdepth 1 -type f -name '*.log' -printf '%T@ %p\n' 2>/dev/null \
                  | sort -n | tail -n 1 | cut -d' ' -f2-) ;;
        2) file="$S_PATH/logs/console.log" ;;
        *) info "Cancelled."; return ;;
    esac
    if [[ -z $file || ! -f $file ]]; then warn "No log file found yet."; return; fi
    ask "Number of lines (1-1000)" 50 || { info "Cancelled."; return; }
    n=$ANSWER
    if ! [[ $n =~ ^[0-9]+$ ]] || ((10#$n < 1 || 10#$n > 1000)); then err "Enter a number between 1 and 1000."; return; fi
    n=$((10#$n))
    echo; sep
    echo "$file"
    sep
    # control characters are stripped so log content cannot drive the terminal
    tail -n "$n" -- "$file" | tr -d '\000-\010\013-\037\177'
    sep
    if confirm_yn "Follow live? (Ctrl+C returns to the menu) [y/N]: " n; then
        trap ':' INT
        tail -n 0 -f -- "$file" | tr -d '\000-\010\013-\037\177'
        restore_int_trap
        echo
    fi
}

# =============================================================================
#  MAINTENANCE: update, scheduled restart, watchdog, backups
# =============================================================================
broadcast_countdown() {
    local secs=$1
    ((secs > 0)) || return 0
    broadcast_cmd "say [Server] Maintenance update in ${secs} seconds. The server will restart."
    if ((secs > 10)); then
        sleep $((secs - 10))
        broadcast_cmd "say [Server] Restarting for the update in 10 seconds."
        sleep 10
    else
        sleep "$secs"
    fi
}

restart_ids() {
    local id rc=0
    for id in "$@"; do
        load_server "$id" || continue
        start_server "$id" || rc=1
    done
    return $rc
}

# ----- scheduled server restart (written by the web panel scheduler; runs as root through a systemd path unit) -----
ctl_state() {   # <id> <action> <state> [code]: progress file the web panel shows as a spinner
    local f="$PANEL_DIR/data/ctlstate-$1.json" tmp="$PANEL_DIR/data/.ctlstate-$1.tmp"
    jq -nc --arg a "$2" --arg s "$3" --arg c "${4:-}" --argjson t "$(date +%s)" '{action:$a,state:$s,code:$c,ts:$t}' >"$tmp" 2>/dev/null \
        && chmod 644 "$tmp" && mv -f -- "$tmp" "$f"
}

panel_srvctl_run() {   # start / stop / restart requested in the web panel (srvctl-<action>-<id>); runs immediately, no delay
    local f bn act id n=0
    while ((n++ < 20)); do
        local -a files=()
        for f in "$PANEL_DIR"/data/srvctl-*; do [[ -f $f ]] && files+=("$f"); done
        ((${#files[@]})) || break
        for f in "${files[@]}"; do
            bn=${f##*/srvctl-}; act=${bn%%-*}; id=${bn#*-}
            rm -f -- "$f"
            [[ $act =~ ^(start|stop|restart)$ && $id =~ ^[0-9]+$ ]] || continue
            if ! load_server "$id"; then ctl_state "$id" "$act" failed not_found; continue; fi
            ctl_state "$id" "$act" working
            if ! lock_ops 60; then ctl_state "$id" "$act" failed busy; continue; fi
            case $act in
                start)
                    if is_running "$id" || start_server "$id"; then ctl_state "$id" "$act" done; else ctl_state "$id" "$act" failed start_failed; fi ;;
                stop)
                    if stop_session "$id"; then ctl_state "$id" "$act" done; else ctl_state "$id" "$act" failed stop_failed; fi ;;
                restart)
                    if stop_session "$id"; then
                        if start_server "$id"; then ctl_state "$id" "$act" done; else ctl_state "$id" "$act" failed start_failed; fi
                    else ctl_state "$id" "$act" failed stop_failed; fi ;;
            esac
            unlock_ops
        done
    done
    return 0
}

panel_restart_run() {
    local f id rc=0 bn
    panel_srvctl_run
    local -a ids=() run=()
    for f in "$PANEL_DIR"/data/restart-request-*; do
        [[ -f $f ]] || continue
        bn=${f##*/restart-request-}
        [[ $bn =~ ^[0-9]+$ ]] && ids+=("$bn")
        rm -f -- "$f"
    done
    ((${#ids[@]})) || return 0
    lock_ops 0 || { err "Another operation is running; scheduled restart skipped."; return 1; }
    for id in "${ids[@]}"; do load_server "$id" && is_running "$id" && run+=("$id"); done
    if ((${#run[@]})); then
        for id in "${run[@]}"; do load_server "$id" && console_send "$id" "say [Server] Scheduled restart in 60 seconds."; done
        sleep 50
        for id in "${run[@]}"; do load_server "$id" && console_send "$id" "say [Server] Restarting in 10 seconds."; done
        sleep 10
        for id in "${run[@]}"; do
            load_server "$id" || continue
            stop_session "$id" || { rc=1; continue; }
            start_server "$id" || rc=1
        done
    fi
    unlock_ops
    return $rc
}

# ----- CS2 update requested from the web panel (runs as root through a systemd path unit) -----
PU_BY=""
pu_status() {   # <state> <code> [local-build] [remote-build]
    local f="$PANEL_DIR/data/update-status.json" tmp="$PANEL_DIR/data/update-status.json.tmp"
    jq -n --arg s "$1" --arg c "$2" --arg l "${3:-}" --arg r "${4:-}" --arg b "$PU_BY" --argjson t "$(date +%s)" \
        '{state:$s,code:$c,local:$l,remote:$r,by:$b,ts:$t}' >"$tmp" 2>/dev/null \
        && chown "$CS2_USER:$CS2_GROUP" "$tmp" && chmod 644 "$tmp" && mv -f -- "$tmp" "$f"
    return 0
}
pu_local_build() { sed -n 's/.*"buildid"[[:space:]]*"\([0-9]*\)".*/\1/p' "$BASE/steamapps/appmanifest_${STEAM_APPID}.acf" 2>/dev/null | head -1; }
pu_remote_build() {
    run_as_cs2 timeout 150 "$STEAMCMD" +login anonymous +app_info_update 1 +app_info_print "$STEAM_APPID" +quit 7>&- 8>&- 9>&- 2>/dev/null \
        | awk '/"branches"/{b=1} b&&/"public"/{p=1} p&&/"buildid"/{gsub(/"/,"",$2); print $2; exit}'
}
panel_update_run() {
    local req="$PANEL_DIR/data/update-request" id lb rb lb2 rc stop_fail=0
    local -a ids running=() cmd
    [[ -f $req ]] || return 0
    PU_BY=$(jq -r '.by // ""' "$req" 2>/dev/null); PU_BY=${PU_BY//[^[:alnum:] ._-]/}
    rm -f -- "$req"
    [[ -x $STEAMCMD ]] || { pu_status failed no_steamcmd; return 1; }
    lock_ops 0 || { pu_status failed busy; return 1; }
    pu_status checking checking
    lb=$(pu_local_build); rb=$(pu_remote_build)
    if ! [[ $rb =~ ^[0-9]+$ ]]; then pu_status failed check_failed "$lb"; unlock_ops; return 1; fi
    if [[ -n $lb && $lb == "$rb" ]]; then
        info "CS2 is up to date (build $lb); nothing to do."
        pu_status uptodate uptodate "$lb" "$rb"; unlock_ops; return 0
    fi
    info "CS2 update found: build ${lb:-?} -> $rb"
    mapfile -t ids < <(jq -r '.[].id' "$DB")
    for id in "${ids[@]}"; do is_running "$id" && running+=("$id"); done
    pu_status available available "$lb" "$rb"; sleep 10
    if ((${#running[@]})); then
        pu_status countdown countdown "$lb" "$rb"
        broadcast_countdown 60
        for id in "${running[@]}"; do
            load_server "$id" || continue
            stop_session "$id" || stop_fail=1
        done
        if ((stop_fail)); then
            restart_ids "${running[@]}"; pu_status failed stop_failed "$lb" "$rb"; unlock_ops; return 1
        fi
    fi
    pu_status updating updating "$lb" "$rb"
    cmd=("$STEAMCMD" +force_install_dir "$BASE" +login anonymous +app_update "$STEAM_APPID" +quit)
    run_as_cs2 "${cmd[@]}" 7>&- 8>&- 9>&-; rc=$?
    if ((rc == 0)); then
        # After every CS2 game update: full Metamod + CSS + gameinfo repair
        info "Running full Metamod + CounterStrikeSharp repair after CS2 update..."
        repair_metamod_css 1 1 || warn "Metamod/CSS repair had issues; servers will still start. Check Maintenance -> Repair Metamod/CSS."
    fi
    pu_status starting starting "$lb" "$rb"
    ((${#running[@]})) && restart_ids "${running[@]}"
    lb2=$(pu_local_build)
    if ((rc == 0)); then pu_status done done "${lb2:-$lb}" "$rb"; else pu_status failed update_failed "$lb" "$rb"; fi
    unlock_ops
    return $rc
}

update_cs2_ui() {
    header "UPDATE CS2 (SteamCMD)"
    if [[ ! -x $STEAMCMD ]]; then err "SteamCMD not found or not executable: $STEAMCMD"; return; fi
    local -a ids running=()
    local id secs=0 validate=0 rc stop_fail=0
    local -a cmd
    mapfile -t ids < <(jq -r '.[].id' "$DB")
    for id in "${ids[@]}"; do is_running "$id" && running+=("$id"); done

    echo "Running servers: ${#running[@]}"
    for id in "${running[@]}"; do load_server "$id" && echo "  - $S_NAME (port $S_PORT)"; done
    echo
    warn "The shared base installation ($BASE) is updated for ALL servers."
    warn "Running servers are stopped, then started again after the update."
    info "After the game update, gameinfo.gi (Metamod) and official CounterStrikeSharp will be refreshed automatically."
    echo
    if ((${#running[@]})); then
        ask "Countdown before stopping, in seconds (0-600)" 60 || { info "Cancelled."; return; }
        if ! [[ $ANSWER =~ ^[0-9]+$ ]] || ((10#$ANSWER > 600)); then err "Enter a number between 0 and 600."; return; fi
        secs=$((10#$ANSWER))
    fi
    confirm_yn "Start the update? [y/N]: " n || { info "Cancelled."; return; }
    confirm_yn "Validate all game files (much slower)? [y/N]: " n && validate=1

    lock_ops 10 || return
    if ((${#running[@]})); then
        broadcast_countdown "$secs"
        for id in "${running[@]}"; do
            load_server "$id" || continue
            info "Stopping '$S_NAME'..."
            stop_session "$id" || { err "Could not stop '$S_NAME'."; stop_fail=1; }
        done
        if ((stop_fail)); then
            err "Update aborted; restarting the servers that were stopped."
            restart_ids "${running[@]}"
            unlock_ops; return
        fi
    fi

    cmd=("$STEAMCMD" +force_install_dir "$BASE" +login anonymous +app_update "$STEAM_APPID")
    ((validate)) && cmd+=(validate)
    cmd+=(+quit)
    info "Running SteamCMD as $CS2_USER ..."
    run_as_cs2 "${cmd[@]}" 7>&- 8>&- 9>&-
    rc=$?
    if ((rc == 0)); then
        ok "SteamCMD finished."
        info "Running full Metamod + CounterStrikeSharp repair after CS2 update..."
        # repair manages CSS stop/start; servers already stopped above for game update
        repair_metamod_css 1 1 || warn "Metamod/CSS repair had issues; check Maintenance -> Repair Metamod/CSS."
    else
        err "SteamCMD failed (exit code $rc)."
    fi

    if ((${#running[@]})); then
        if ((rc == 0)) || confirm_yn "Update failed. Start the stopped servers anyway? [Y/n]: " y; then
            info "Starting servers that were running before..."
            restart_ids "${running[@]}"
        fi
    fi
    unlock_ops
    ((rc == 0)) && ok "CS2 + Metamod gameinfo + CounterStrikeSharp post-update steps finished."
}

# ----- scheduled restart (systemd transient timers) -----
sched_unit() {   # <unit> <delay-seconds> <manager args...>
    local unit=$1 delay=$2; shift 2
    systemd-run --quiet --unit="$unit" --description="CS2 scheduled action ($unit)" \
        --timer-property=AccuracySec=1s --on-active="${delay}s" "$SELF" "$@"
}

sched_add_ui() {
    header "SCHEDULE RESTART"
    command -v systemd-run >/dev/null 2>&1 || { err "systemd-run is not available."; return; }
    pick_server "Server ID to restart (q = cancel): " || return
    local id=$PICK_ID name=$S_NAME now target delay hh mm base
    now=$(date +%s)
    echo
    echo "When should '$name' restart?"
    echo "  HH:MM  = next occurrence of that time (24h, server time)"
    echo "  +N     = in N minutes (example: +30)"
    ask "When" || { info "Cancelled."; return; }
    if [[ $ANSWER =~ ^\+([0-9]{1,4})$ ]]; then
        target=$((now + 10#${BASH_REMATCH[1]} * 60))
    elif [[ $ANSWER =~ ^([01]?[0-9]|2[0-3]):([0-5][0-9])$ ]]; then
        hh=${BASH_REMATCH[1]}; mm=${BASH_REMATCH[2]}
        target=$(date -d "$hh:$mm" +%s) || { err "Invalid time."; return; }
        if ((target <= now + 60)); then target=$(date -d "tomorrow $hh:$mm" +%s) || { err "Invalid time."; return; }; fi
    else
        err "Use HH:MM or +N (minutes)."; return
    fi
    delay=$((target - now))
    if ((delay < 60)); then err "Choose a time at least 1 minute ahead."; return; fi

    echo
    info "'$name' will restart at $(date -d "@$target" '+%F %H:%M:%S'). Players get warnings 5 and 1 minute before."
    warn "Scheduled restarts do not survive a machine reboot."
    confirm_yn "Schedule it? [Y/n]: " y || { info "Cancelled."; return; }

    base="cs2-restart-$id-$target"
    if ! {
        { ((delay <= 300)) || sched_unit "$base-w5" $((delay - 300)) say "$id" "Server restarting in 5 minutes."; } \
        && { ((delay <= 60)) || sched_unit "$base-w1" $((delay - 60)) say "$id" "Server restarting in 1 minute."; } \
        && sched_unit "$base-go" "$delay" restart "$id"
    }; then
        err "Could not create the timers; removing any that were created."
        systemctl stop "$base-w5.timer" "$base-w1.timer" "$base-go.timer" >/dev/null 2>&1
        return
    fi
    ok "Restart of '$name' scheduled."
}

sched_list_ui() {
    header "SCHEDULED RESTARTS"
    command -v systemctl >/dev/null 2>&1 || { err "systemctl is not available."; return; }
    if [[ -z $(systemctl list-units --type=timer --no-legend --plain 'cs2-restart-*' 2>/dev/null) ]]; then
        info "No scheduled restarts."; return
    fi
    systemctl list-timers --no-pager 'cs2-restart-*'
}

sched_cancel_ui() {
    header "CANCEL SCHEDULED RESTART"
    command -v systemctl >/dev/null 2>&1 || { err "systemctl is not available."; return; }
    local -a units=() bases=()
    local u i=0 sid sepoch
    mapfile -t units < <(systemctl list-units --type=timer --no-legend --plain 'cs2-restart-*-go.timer' 2>/dev/null | awk '{print $1}')
    if ((${#units[@]} == 0)); then info "No scheduled restarts."; return; fi
    for u in "${units[@]}"; do
        if [[ $u =~ ^cs2-restart-([0-9]+)-([0-9]+)-go\.timer$ ]]; then
            sid=${BASH_REMATCH[1]}; sepoch=${BASH_REMATCH[2]}
            i=$((i + 1)); bases[i]="cs2-restart-$sid-$sepoch"
            printf '%s) server ID %s at %s\n' "$i" "$sid" "$(date -d "@$sepoch" '+%F %H:%M')"
        fi
    done
    ((i > 0)) || { info "No scheduled restarts."; return; }
    echo
    ask "Number to cancel (q = cancel)" || { info "Cancelled."; return; }
    if ! [[ $ANSWER =~ ^[0-9]+$ ]] || ((10#$ANSWER < 1 || 10#$ANSWER > i)); then err "Invalid selection."; return; fi
    u=${bases[$((10#$ANSWER))]}
    systemctl stop "$u-w5.timer" "$u-w1.timer" "$u-go.timer" >/dev/null 2>&1
    ok "Scheduled restart cancelled."
}

sched_menu() {
    local c
    while :; do
        clear_screen
        dsep
        printf '%s           SCHEDULED RESTART%s\n' "$BOLD" "$RESET"
        dsep
        echo
        echo "1) Schedule a restart"
        echo "2) List scheduled restarts"
        echo "3) Cancel a scheduled restart"
        echo "4) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) sched_add_ui;    pause ;;
            2) sched_list_ui;   pause ;;
            3) sched_cancel_ui; pause ;;
            4|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

# ----- watchdog / autostart -----
watchdog_run() {
    local id ts now recent cnt f
    local -a ids
    local rc=0
    if ! lock_ops 0; then info "Manager busy; watchdog run skipped."; return 0; fi
    if ! jq -e 'type=="array"' "$AUTOSTART_DB" >/dev/null 2>&1; then
        err "$AUTOSTART_DB is not a valid JSON array; watchdog does nothing."
        unlock_ops; return 1
    fi
    mapfile -t ids < <(jq -r '.[] | select(type=="number") | floor' "$AUTOSTART_DB")
    now=$(date +%s)
    for id in "${ids[@]}"; do
        if ! load_server "$id"; then warn "Autostart ID $id is not registered; ignoring."; continue; fi
        is_running "$id" && continue
        [[ -e $(manual_stop_file "$id") ]] && continue   # stopped on purpose
        f="$STATE_DIR/restarts-$id"
        recent=""
        if [[ -f $f ]]; then
            recent=$(awk -v now="$now" -v w="$WATCHDOG_WINDOW" '$1 ~ /^[0-9]+$/ && now-$1 < w' "$f" 2>/dev/null)
        fi
        cnt=$(printf '%s' "$recent" | grep -c . || true)
        if ((cnt >= WATCHDOG_MAX_RESTARTS)); then
            warn "'$S_NAME' is offline but hit the restart limit ($WATCHDOG_MAX_RESTARTS per $((WATCHDOG_WINDOW / 60)) min); skipping."
            if [[ ! -f $STATE_DIR/crash-notified-$id ]]; then
                notify_server_event crash "$id" || true
                : >"$STATE_DIR/crash-notified-$id"
            fi
            continue
        fi
        { [[ -n $recent ]] && printf '%s
' "$recent"; printf '%s
' "$now"; } >"$f"
        info "Watchdog: '$S_NAME' is offline; starting it."
        notify_server_event crash "$id" || true
        rm -f -- "$STATE_DIR/crash-notified-$id"
        start_server "$id" || rc=1
    done
    unlock_ops
    return $rc
}

watchdog_install() {
    command -v systemctl >/dev/null 2>&1 || { err "systemctl is not available."; return; }
    local svc="/etc/systemd/system/$WATCHDOG_UNIT.service" tim="/etc/systemd/system/$WATCHDOG_UNIT.timer"
    cat >"$svc" <<EOF
[Unit]
Description=CS2 server watchdog
After=network-online.target

[Service]
Type=oneshot
ExecStart=$SELF watchdog
EOF
    cat >"$tim" <<EOF
[Unit]
Description=Run the CS2 watchdog every minute

[Timer]
OnActiveSec=30
OnUnitActiveSec=60
AccuracySec=5s

[Install]
WantedBy=timers.target
EOF
    if systemctl daemon-reload && systemctl enable --now "$WATCHDOG_UNIT.timer" >/dev/null 2>&1; then
        ok "Watchdog installed and enabled (checks every minute)."
        info "It only restarts servers marked for autostart and never those you stopped from the manager."
    else
        err "Could not enable the watchdog timer."
    fi
}

watchdog_remove() {
    command -v systemctl >/dev/null 2>&1 || { err "systemctl is not available."; return; }
    systemctl disable --now "$WATCHDOG_UNIT.timer" >/dev/null 2>&1
    rm -f -- "/etc/systemd/system/$WATCHDOG_UNIT.service" "/etc/systemd/system/$WATCHDOG_UNIT.timer"
    systemctl daemon-reload
    ok "Watchdog removed."
}

watchdog_status() {
    local id name
    if command -v systemctl >/dev/null 2>&1; then
        printf 'Timer enabled : %s\n' "$(systemctl is-enabled "$WATCHDOG_UNIT.timer" 2>/dev/null || echo no)"
        printf 'Timer active  : %s\n' "$(systemctl is-active "$WATCHDOG_UNIT.timer" 2>/dev/null || echo no)"
    fi
    echo "Autostart servers:"
    if ((AUTOSTART_OK)) && [[ $(jq 'length' "$AUTOSTART_DB") -gt 0 ]]; then
        while IFS= read -r id; do
            name=$(jq -r --argjson id "$id" '.[] | select(.id == $id) | .name' "$DB")
            printf '  - ID %s  %s%s\n' "$id" "${name:-<not registered>}" \
                "$([[ -e $(manual_stop_file "$id") ]] && echo '  (stopped manually: watchdog will not restart it)')"
        done < <(jq -r '.[] | select(type=="number") | floor' "$AUTOSTART_DB")
    else
        echo "  (none)"
    fi
}

autostart_toggle_ui() {
    ((AUTOSTART_OK)) || { err "$AUTOSTART_DB is invalid; fix it first."; return; }
    pick_server "Server ID to toggle autostart (q = cancel): " || return
    local id=$PICK_ID
    if jq -e --argjson id "$id" 'index($id) != null' "$AUTOSTART_DB" >/dev/null 2>&1; then
        autostart_update --argjson id "$id" 'map(select(. != $id))' && ok "Autostart DISABLED for '$S_NAME'."
    else
        autostart_update --argjson id "$id" '. + [$id] | unique' && ok "Autostart ENABLED for '$S_NAME'."
    fi
}

watchdog_menu() {
    local c
    while :; do
        clear_screen
        dsep
        printf '%s          WATCHDOG / AUTOSTART%s\n' "$BOLD" "$RESET"
        dsep
        echo
        echo "1) Install watchdog (systemd timer)"
        echo "2) Remove watchdog"
        echo "3) Status"
        echo "4) Toggle autostart for a server"
        echo "5) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) watchdog_install;     pause ;;
            2) confirm_yn "Remove the watchdog? [y/N]: " n && watchdog_remove; pause ;;
            3) watchdog_status;      pause ;;
            4) autostart_toggle_ui;  pause ;;
            5|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

# ----- JSON backups (view only) -----
backups_ui() {
    header "JSON BACKUPS"
    local base f
    printf 'Directory: %s  (newest %s kept per file)\n\n' "$BACKUP_DIR" "$BACKUP_KEEP"
    for base in servers.json plugins.json autostart.json server-settings.json; do
        printf '%s%s%s\n' "$BOLD" "$base" "$RESET"
        if ! find "$BACKUP_DIR" -maxdepth 1 -type f -name "$base.*" -print -quit 2>/dev/null | grep -q .; then
            echo "  (none yet)"; continue
        fi
        while IFS= read -r f; do
            printf '  %s\n' "$f"
        done < <(find "$BACKUP_DIR" -maxdepth 1 -type f -name "$base.*" -printf '%T@ %p\n' | sort -rn | cut -d' ' -f2-)
    done
    echo
    info "Backups are never restored automatically. To restore one (with the manager closed):"
    echo "  cp -a $BACKUP_DIR/<backup-file> $SERVERS_DIR/<servers.json|shared/plugins.json>"
    echo "  jq -e 'type==\"array\"' <restored-file>"
}

# =============================================================================
#  OFFICIAL COUNTERSTRIKESHARP AUTO-UPDATER
#  Source: https://github.com/roflmuffin/CounterStrikeSharp/releases
#  Only overlays the CounterStrikeSharp directory; Metamod is never touched.
# =============================================================================
css_latest_release() {
    local json=$1
    curl -fsSL --connect-timeout 15 --max-time 45 \
        -H 'Accept: application/vnd.github+json' \
        -H 'X-GitHub-Api-Version: 2022-11-28' \
        'https://api.github.com/repos/roflmuffin/CounterStrikeSharp/releases/latest' -o "$json" || return 1
    jq -e '(.tag_name | type == "string") and (.assets | type == "array")' "$json" >/dev/null 2>&1
}

css_targets_collect() {
    CSS_TARGET_PATHS=(); CSS_TARGET_KEYS=(); CSS_TARGET_IDS=()
    local target id
    need_layout || return 1
    target="$BASE/$CSGOREL/addons/counterstrikesharp"
    if [[ -d $target && ! -L $target ]]; then
        CSS_TARGET_PATHS+=("$target"); CSS_TARGET_KEYS+=(base); CSS_TARGET_IDS+=(0)
    fi
    while IFS= read -r id; do
        [[ $id =~ ^[0-9]+$ ]] || continue
        load_server "$id" || continue
        safe_server_path "$S_PATH" "$S_SLUG" || continue
        target="$S_PATH/$CSGOREL/addons/counterstrikesharp"
        [[ -d $target && ! -L $target ]] || continue
        CSS_TARGET_PATHS+=("$target"); CSS_TARGET_KEYS+=("server-$id"); CSS_TARGET_IDS+=("$id")
    done < <(jq -r '.[].id' "$DB" 2>/dev/null)
    ((${#CSS_TARGET_PATHS[@]} > 0))
}

css_detect_installed_version() {   # prints a common 1.0.xxx version only if every target agrees
    local target found first="" mixed=0
    command -v strings >/dev/null 2>&1 || return 1
    for target in "${CSS_TARGET_PATHS[@]}"; do
        found=$(strings -a "$target/api/CounterStrikeSharp.API.dll" 2>/dev/null | grep -Eo '1\.0\.[0-9]+' | sort -Vu | tail -1)
        [[ -n $found ]] || return 1
        if [[ -z $first ]]; then first=$found; elif [[ $found != "$first" ]]; then mixed=1; fi
    done
    ((mixed == 0)) && [[ -n $first ]] || return 1
    printf '%s\n' "$first"
}

css_backup_prune() {
    [[ -d $CSS_BACKUP_DIR ]] || return 0
    local -a runs=()
    mapfile -t runs < <(find "$CSS_BACKUP_DIR" -mindepth 1 -maxdepth 1 -type d -name '20*' -printf '%f\n' 2>/dev/null | sort -r)
    local i
    for ((i=CSS_BACKUP_KEEP; i<${#runs[@]}; i++)); do
        rm -rf --one-file-system -- "$CSS_BACKUP_DIR/${runs[$i]}"
    done
}

css_backup_target() {   # <run-dir> <index>
    local run=$1 i=$2 key=${CSS_TARGET_KEYS[$2]} target=${CSS_TARGET_PATHS[$2]}
    local dest="$run/$key/counterstrikesharp"
    install -d -m 750 -- "$(dirname -- "$dest")" || return 1
    cp -a -- "$target" "$dest" || return 1
    printf '%s\n' "$target" >"$run/$key/target-path.txt"
    printf '%s\n' "${CSS_TARGET_IDS[$i]}" >"$run/$key/server-id.txt"
}

css_restore_run() {   # <run-dir> ; restore every backed-up target
    local run=$1 item target backup id rc=0
    [[ -d $run ]] || { err "Backup run not found: $run"; return 1; }
    while IFS= read -r -d '' item; do
        target=$(cat "$item/target-path.txt" 2>/dev/null) || { rc=1; continue; }
        backup="$item/counterstrikesharp"
        [[ -d $backup && -d $target && ! -L $target ]] || { err "Unsafe or incomplete rollback target: $target"; rc=1; continue; }
        case "$target" in "$BASE"/*|"$SERVERS_DIR"/*) ;; *) err "Rollback path is outside managed directories: $target"; rc=1; continue ;; esac
        local parent name restore_tmp
        parent=${target%/*}; name=${target##*/}; restore_tmp="$parent/.${name}.rollback.$$"
        rm -rf --one-file-system -- "$restore_tmp"
        cp -a -- "$backup" "$restore_tmp" || { rc=1; continue; }
        rm -rf --one-file-system -- "$target" || { rm -rf --one-file-system -- "$restore_tmp"; rc=1; continue; }
        mv -- "$restore_tmp" "$target" || { rc=1; continue; }
        chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$target" 2>/dev/null || true
        id=$(cat "$item/server-id.txt" 2>/dev/null || echo 0)
        info "Restored CounterStrikeSharp files for ${id/0/base} from backup."
    done < <(find "$run" -mindepth 1 -maxdepth 1 -type d -print0)
    if [[ -f $run/previous-version.txt ]]; then
        local previous_version
        previous_version=$(cat "$run/previous-version.txt" 2>/dev/null || true)
        if [[ -n $previous_version ]]; then
            printf '%s\n' "$previous_version" >"$CSS_STATE_FILE.tmp" && chmod 644 "$CSS_STATE_FILE.tmp" && mv -f -- "$CSS_STATE_FILE.tmp" "$CSS_STATE_FILE"
        else
            rm -f -- "$CSS_STATE_FILE"
        fi
    fi
    return "$rc"
}

css_rollback_latest() {
    local latest
    need_layout || return 1
    [[ -d $CSS_BACKUP_DIR ]] || { err "No CounterStrikeSharp backups exist yet."; return 1; }
    latest=$(find "$CSS_BACKUP_DIR" -mindepth 1 -maxdepth 1 -type d -name '20*' -printf '%p\n' 2>/dev/null | sort -r | head -1)
    [[ -n $latest ]] || { err "No CounterStrikeSharp backups exist yet."; return 1; }
    info "Rollback source: $latest"
    confirm_yn "Restore the previous CounterStrikeSharp files from this backup? [y/N]: " n || return 1
    lock_ops 60 || { err "Another manager operation is running."; return 1; }
    local id rc=0
    local -a running=()
    while IFS= read -r id; do
        [[ $id =~ ^[0-9]+$ ]] || continue
        load_server "$id" || continue
        if is_running "$id" && [[ -d $S_PATH/$CSGOREL/addons/counterstrikesharp ]]; then running+=("$id"); fi
    done < <(jq -r '.[].id' "$DB")
    if ((${#running[@]})); then
        broadcast_cmd "say [CS2NEXUS] CounterStrikeSharp rollback maintenance; server restarting shortly."
        for id in "${running[@]}"; do stop_session "$id" || rc=1; done
    fi
    if ((rc == 0)); then css_restore_run "$latest" || rc=1; fi
    for id in "${running[@]}"; do load_server "$id" && start_server "$id" || rc=1; done
    unlock_ops
    if ((rc == 0)); then ok "CounterStrikeSharp rollback completed. Backup kept at $latest"; else err "Rollback completed with errors; inspect server logs and $latest"; fi
    return "$rc"
}

css_update_run() {   # [quiet 0|1]
    local quiet=${1:-0} tmpdir json tag asset_url asset_name archive stage css_src current run i id rc=0 stop_failed=0
    local -a running=() updated_ids=()
    local -a CSS_TARGET_PATHS=() CSS_TARGET_KEYS=() CSS_TARGET_IDS=()
    if ! lock_ops 0; then ((quiet)) || warn "Manager busy; CounterStrikeSharp update skipped."; return 1; fi
    if ! css_targets_collect; then
        ((quiet)) || info "CounterStrikeSharp is not installed in the base or any registered server; nothing to update."
        unlock_ops; return 0
    fi
    tmpdir=$(mktemp -d /tmp/cs2nexus-css-update.XXXXXX) || { unlock_ops; return 1; }
    json="$tmpdir/release.json"
    if ! css_latest_release "$json"; then
        ((quiet)) || err "Could not query the official CounterStrikeSharp GitHub release API."
        rm -rf --one-file-system -- "$tmpdir"; unlock_ops; return 1
    fi
    tag=$(jq -r '.tag_name' "$json")
    asset_name=$(jq -r '[.assets[] | select((.name | test("linux";"i")) and (.name | test("with-runtime";"i")) and (.name | endswith(".zip")))] | first | .name // empty' "$json")
    asset_url=$(jq -r --arg n "$asset_name" '.assets[] | select(.name == $n) | .browser_download_url' "$json")
    if [[ -z $tag || -z $asset_name || $asset_url != https://github.com/roflmuffin/CounterStrikeSharp/releases/download/* ]]; then
        ((quiet)) || err "The official release did not contain a recognized Linux with-runtime ZIP asset."
        rm -rf --one-file-system -- "$tmpdir"; unlock_ops; return 1
    fi
    current=$(cat "$CSS_STATE_FILE" 2>/dev/null || true)
    if [[ -z $current ]]; then
        local detected_version
        detected_version=$(css_detect_installed_version 2>/dev/null || true)
        [[ -n $detected_version ]] && current="v$detected_version"
    fi
    if [[ $current == "$tag" ]]; then
        printf '%s\n' "$tag" >"$CSS_STATE_FILE.tmp" && chmod 644 "$CSS_STATE_FILE.tmp" && mv -f -- "$CSS_STATE_FILE.tmp" "$CSS_STATE_FILE"
        ((quiet)) || ok "CounterStrikeSharp is up to date ($tag)."
        rm -rf --one-file-system -- "$tmpdir"; unlock_ops; return 0
    fi
    ((quiet)) || info "Official CounterStrikeSharp update found: ${current:-not yet tracked} -> $tag"
    archive="$tmpdir/$asset_name"
    if ! curl -fL --retry 3 --connect-timeout 15 --max-time 600 "$asset_url" -o "$archive"; then
        ((quiet)) || err "Download failed; installed files were not changed."
        rm -rf --one-file-system -- "$tmpdir"; unlock_ops; return 1
    fi
    stage="$tmpdir/extracted"; mkdir -p -- "$stage"
    if ! unzip -q "$archive" -d "$stage"; then
        ((quiet)) || err "Downloaded ZIP could not be extracted; installed files were not changed."
        rm -rf --one-file-system -- "$tmpdir"; unlock_ops; return 1
    fi
    css_src=$(find "$stage" -type d -path '*/addons/counterstrikesharp' -print -quit 2>/dev/null)
    if [[ -z $css_src || ! -f $css_src/api/CounterStrikeSharp.API.dll || ! -d $css_src/bin ]]; then
        ((quiet)) || err "The official package structure was not recognized; installed files were not changed."
        rm -rf --one-file-system -- "$tmpdir"; unlock_ops; return 1
    fi
    # The official installer overlays files rather than deleting old ones. Remove
    # protected directories from the STAGING copy so user configs, databases and
    # plugin directories cannot be overwritten by the release archive.
    rm -rf --one-file-system -- "$css_src/plugins" "$css_src/configs" "$css_src/data"

    # Stop only servers that are currently running and have their own CSS core directory.
    for i in "${!CSS_TARGET_IDS[@]}"; do
        id=${CSS_TARGET_IDS[$i]}
        ((id > 0)) || continue
        if is_running "$id"; then running+=("$id"); fi
    done
    if ((${#running[@]})); then
        ((quiet)) || info "Stopping ${#running[@]} running server(s) for the CounterStrikeSharp update..."
        broadcast_cmd "say [CS2NEXUS] CounterStrikeSharp update maintenance in 30 seconds."
        sleep 20
        broadcast_cmd "say [CS2NEXUS] Restarting in 10 seconds for an official framework update."
        sleep 10
        for id in "${running[@]}"; do
            if ! stop_session "$id"; then stop_failed=1; break; fi
        done
    fi
    if ((stop_failed)); then
        for id in "${running[@]}"; do load_server "$id" && ! is_running "$id" && start_server "$id" || true; done
        ((quiet)) || err "Could not stop all servers; update cancelled."
        rm -rf --one-file-system -- "$tmpdir"; unlock_ops; return 1
    fi

    run="$CSS_BACKUP_DIR/$(date +%Y%m%d-%H%M%S)"
    install -d -m 750 -- "$run" || rc=1
    if ((rc == 0)); then
        printf '%s\n' "$current" >"$run/previous-version.txt" || rc=1
    fi
    if ((rc == 0)); then
        for i in "${!CSS_TARGET_PATHS[@]}"; do
            if ! css_backup_target "$run" "$i"; then rc=1; break; fi
        done
    fi
    # Overlay only CounterStrikeSharp core files. No deletion/replacement of addons,
    # Metamod, plugin directories, configs or plugin databases takes place.
    if ((rc == 0)); then
        for i in "${!CSS_TARGET_PATHS[@]}"; do
            local target=${CSS_TARGET_PATHS[$i]}
            if ! cp -a -- "$css_src/." "$target/"; then rc=1; break; fi
            chown -R -P -h "$CS2_USER:$CS2_GROUP" -- "$target" 2>/dev/null || true
            [[ -f $target/api/CounterStrikeSharp.API.dll && -d $target/bin ]] || { rc=1; break; }
        done
    fi
    if ((rc != 0)); then
        ((quiet)) || err "Update failed; restoring all CounterStrikeSharp backups."
        css_restore_run "$run" || true
    else
        printf '%s\n' "$tag" >"$CSS_STATE_FILE.tmp" && chmod 644 "$CSS_STATE_FILE.tmp" && mv -f -- "$CSS_STATE_FILE.tmp" "$CSS_STATE_FILE" || rc=1
    fi

    # Bring back only servers that were online before maintenance.
    for id in "${running[@]}"; do
        if load_server "$id" && ! start_server "$id"; then rc=1; fi
    done
    # If a restart fails after installation, revert all updated CSS cores and retry starts.
    if ((rc != 0)) && [[ -d $run ]]; then
        ((quiet)) || err "Post-update validation failed; rolling back to the pre-update backup."
        for id in "${running[@]}"; do load_server "$id" && is_running "$id" && stop_session "$id" || true; done
        css_restore_run "$run" || true
        for id in "${running[@]}"; do load_server "$id" && ! is_running "$id" && start_server "$id" || true; done
    fi
    if ((rc == 0)); then
        css_backup_prune
        # CS2 updates often wipe the Metamod SearchPath; re-apply every time CSS is refreshed
        patch_gameinfo || true
        ((quiet)) || ok "CounterStrikeSharp updated to $tag. Backup: $run"
    else
        ((quiet)) || err "CounterStrikeSharp update did not complete cleanly. Inspect server logs; backup: $run"
    fi
    rm -rf --one-file-system -- "$tmpdir"
    unlock_ops
    return "$rc"
}

css_autoupdate_enable() {   # [quiet]
    local quiet=${1:-0}
    command -v systemctl >/dev/null 2>&1 || { ((quiet)) || err "systemctl is not available."; return 1; }
    cat >"/etc/systemd/system/$CSS_TIMER_UNIT.service" <<EOF
[Unit]
Description=CS2NEXUS official CounterStrikeSharp updater
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=$SELF css-update
EOF
    cat >"/etc/systemd/system/$CSS_TIMER_UNIT.timer" <<EOF
[Unit]
Description=Check official CounterStrikeSharp releases every 6 hours

[Timer]
OnBootSec=10min
OnUnitActiveSec=6h
RandomizedDelaySec=5min
Persistent=true

[Install]
WantedBy=timers.target
EOF
    if systemctl daemon-reload && systemctl enable --now "$CSS_TIMER_UNIT.timer" >/dev/null 2>&1; then
        conf_set CSS_AUTOUPDATE 1 || true
        ((quiet)) || ok "Official CounterStrikeSharp auto-update enabled (checks every 6 hours)."
        return 0
    fi
    ((quiet)) || err "Could not enable CounterStrikeSharp auto-update timer."
    return 1
}

css_autoupdate_disable() {
    command -v systemctl >/dev/null 2>&1 && systemctl disable --now "$CSS_TIMER_UNIT.timer" >/dev/null 2>&1 || true
    rm -f -- "/etc/systemd/system/$CSS_TIMER_UNIT.service" "/etc/systemd/system/$CSS_TIMER_UNIT.timer"
    command -v systemctl >/dev/null 2>&1 && systemctl daemon-reload
    conf_set CSS_AUTOUPDATE 0 || true
    ok "CounterStrikeSharp auto-update disabled."
}

css_updater_menu() {
    local c enabled=0 current latest_json latest
    systemctl is-active --quiet "$CSS_TIMER_UNIT.timer" 2>/dev/null && enabled=1
    current=$(cat "$CSS_STATE_FILE" 2>/dev/null || echo 'unknown / not tracked')
    header "COUNTERSTRIKESHARP UPDATER"
    printf '  Source          : https://github.com/roflmuffin/CounterStrikeSharp/releases\n'
    printf '  Last installed  : %s\n' "$current"
    printf '  Periodic update : %s\n\n' "$([[ $enabled == 1 ]] && echo 'ENABLED (every 6 hours)' || echo 'disabled')"
    echo "  1) Check and install latest official release now"
    echo "  2) $( ((enabled)) && echo 'Disable' || echo 'Enable') periodic auto-update"
    echo "  3) Roll back to the latest saved backup"
    echo "  4) Full repair (Metamod + CSS + gameinfo, force reinstall)"
    echo "  5) Back"
    echo
    read -r -p "Select: " c || return
    case "$(trim "$c")" in
        1) css_update_run 0; pause ;;
        2) if ((enabled)); then css_autoupdate_disable; else css_autoupdate_enable; fi; pause ;;
        3) css_rollback_latest; pause ;;
        4) repair_metamod_css 0 1; pause ;;
        5|q|Q) return ;;
        *) err "Invalid option."; sleep 1 ;;
    esac
}

maintenance_menu() {
    local c
    while :; do
        clear_screen
        dsep
        printf '%s              MAINTENANCE%s\n' "$BOLD" "$RESET"
        dsep
        echo
        echo "1) Update CS2 (SteamCMD, safe)"
        echo "2) Scheduled restart"
        echo "3) Watchdog / autostart"
        echo "4) JSON backups (small registry copies)"
        echo "5) Data backups (WeaponPaints, bans, admins, settings, panel)"
        echo "6) Resource alerts (CPU / RAM / disk limits)"
        echo "7) Update launcher"
        echo "8) Launcher settings"
        echo "9) CounterStrikeSharp updater (official / auto-update / rollback)"
        echo "10) Repair Metamod + CSS fully (auto fix after CS2 update / crash)"
        echo "11) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) update_cs2_ui; pause ;;
            2) sched_menu ;;
            3) watchdog_menu ;;
            4) backups_ui; pause ;;
            5) backups_full_menu ;;
            6) alerts_menu ;;
            7) update_launcher_ui; pause ;;
            8) launcher_settings_ui ;;
            9) css_updater_menu ;;
            10) repair_metamod_css 0 1; pause ;;
            11|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

# =============================================================================
#  EXTRA FEATURE SETTINGS  (own file: values may contain ? = & and so on)
# =============================================================================
readonly FX_FILE="$SHARED_DIR/nexus-features.conf"
fx_get() {   # <KEY> [default]
    local v
    v=$(grep -m1 "^$1=" "$FX_FILE" 2>/dev/null | cut -d= -f2-)
    printf '%s' "${v:-${2:-}}"
}
fx_set() {   # <KEY> <value>
    local k=$1 v=$2 tmp
    [[ $k =~ ^[A-Z0-9_]+$ ]] || return 1
    [[ $v != *$'\n'* && $v != *$'\r'* ]] || { err "No line breaks allowed."; return 1; }
    install -d -m 755 -- "$(dirname -- "$FX_FILE")" 2>/dev/null
    tmp=$(mktemp "$FX_FILE.XXXXXX") || return 1
    { [[ -f $FX_FILE ]] && grep -v "^$k=" "$FX_FILE"; printf '%s=%s\n' "$k" "$v"; } >"$tmp"
    chmod 600 "$tmp"
    mv -f -- "$tmp" "$FX_FILE" || { rm -f -- "$tmp"; return 1; }
}
fx_num() {   # <KEY> <default> <min> <max> -> value (falls back to default when invalid)
    local v; v=$(fx_get "$1" "$2")
    [[ $v =~ ^[0-9]+$ ]] && ((10#$v >= $3 && 10#$v <= $4)) || v=$2
    printf '%s' "$((10#$v))"
}
ask_num() {   # <prompt> <current> <min> <max>  -> ANSWER
    local a
    while :; do
        read -r -p "$1 [$2]: " a || exit 0
        a=$(trim "$a"); [[ -z $a ]] && a=$2
        if [[ $a =~ ^[0-9]+$ ]] && ((10#$a >= $3 && 10#$a <= $4)); then ANSWER=$((10#$a)); return 0; fi
        err "Enter a number from $3 to $4."
    done
}

# =============================================================================
#  DATA BACKUPS  (rotating .tar.gz: WeaponPaints, bans, admins, settings, panel data)
# =============================================================================
readonly BK_ROOT="/opt/cs2-backups"
readonly BK_UNIT="cs2nexus-backup"
readonly PANEL_DIR="/opt/cs2-panel"

bk_keep() { fx_num BACKUP_KEEP 14 1 365; }

# every path (file or folder) that holds data worth keeping; only existing ones are printed
bk_collect() {
    local p id row spath rel
    local -a list=("$DB" "$FX_FILE" "$CONF_FILE" "$SHARED_DIR/configs" "$VAULT_DIR" "$PANEL_DIR/data")
    for p in "$SHARED_DIR"/*.json; do list+=("$p"); done
    while IFS=$'\t' read -r id spath; do
        [[ -n $spath ]] || continue
        local b="$spath/$CSGOREL"
        list+=("$b/addons/counterstrikesharp/configs/admins.json" "$b/addons/counterstrikesharp/configs/ServerCommandsAdmins.json"
               "$b/addons/counterstrikesharp/plugins/ServerCommands/data" "$b/addons/counterstrikesharp/plugins/FakeBan/data"
               "$b/addons/counterstrikesharp/configs/plugins/NexusLink" "$b/addons/counterstrikesharp/configs/plugins/NexusAdminTools" "$b/cfg/server.cfg" "$b/cfg/cs2nexus_settings.cfg")
    done < <(jq -r '.[] | [.id, .path] | @tsv' "$DB" 2>/dev/null)
    for p in "${list[@]}"; do [[ -e $p ]] && printf '%s\n' "$p"; done
}

bk_sqlite_copy() {   # <src> <dst>: consistent copy of a database that may be in use
    local s=$1 d=$2
    if command -v sqlite3 >/dev/null 2>&1 && sqlite3 -readonly "$s" ".timeout 5000" ".backup '$d'" >/dev/null 2>&1; then return 0; fi
    if command -v node >/dev/null 2>&1 && node --disable-warning=ExperimentalWarning -e '
const {DatabaseSync}=require("node:sqlite");const db=new DatabaseSync(process.argv[1],{readOnly:true});
db.exec("PRAGMA busy_timeout=5000");db.exec("VACUUM INTO \x27"+process.argv[2].replace(/\x27/g,"\x27\x27")+"\x27");db.close()' "$s" "$d" 2>/dev/null; then return 0; fi
    cp -a -- "$s" "$d"
}

# backup_run [label]  -> creates $BK_ROOT/cs2nexus-<label>-<time>.tar.gz and rotates the old ones
backup_run() {
    local label=${1:-auto} stage out tmp p dst n=0 keep
    install -d -m 700 -- "$BK_ROOT" || { err "Cannot create $BK_ROOT"; return 1; }
    vault_snapshot_all
    stage=$(mktemp -d "$BK_ROOT/.stage.XXXXXX") || return 1
    while IFS= read -r p; do
        dst="$stage$p"
        mkdir -p -- "$(dirname -- "$dst")"
        case $p in
            *.sqlite|*.sqlite3|*.db) bk_sqlite_copy "$p" "$dst" ;;
            *) cp -a -- "$p" "$dst" ;;
        esac && n=$((n + 1))
        # databases inside folders (nexus.db) are copied consistently as well
        if [[ -d $p ]]; then
            while IFS= read -r -d '' f; do bk_sqlite_copy "$f" "$stage$f"; done < <(find "$p" -type f \( -name '*.db' -o -name '*.sqlite' \) -print0 2>/dev/null)
            find "$stage$p" -type f \( -name '*-wal' -o -name '*-shm' -o -name '*-journal' \) -delete 2>/dev/null
        fi
    done < <(bk_collect)
    wp_db_dump "$stage"
    out="$BK_ROOT/cs2nexus-$label-$(date +%Y%m%d-%H%M%S).tar.gz"
    tmp="$out.part"
    if tar -C "$stage" -czpf "$tmp" . 2>/dev/null && mv -f -- "$tmp" "$out"; then
        chmod 600 "$out"
        ok "Backup created: $out ($(du -h -- "$out" | cut -f1), $n item(s))"
    else
        rm -f -- "$tmp"; rm -rf --one-file-system -- "$stage"; err "Backup failed."; return 1
    fi
    rm -rf --one-file-system -- "$stage"
    # rotation: automatic/manual backups use the setting; pre-restore safety copies keep the last 5
    keep=$(bk_keep)
    ls -1t -- "$BK_ROOT"/cs2nexus-auto-*.tar.gz "$BK_ROOT"/cs2nexus-manual-*.tar.gz 2>/dev/null | tail -n +"$((keep + 1))" | while IFS= read -r p; do rm -f -- "$p"; done
    ls -1t -- "$BK_ROOT"/cs2nexus-prerestore-*.tar.gz 2>/dev/null | tail -n +6 | while IFS= read -r p; do rm -f -- "$p"; done
    ls -1t -- "$BK_ROOT"/cs2nexus-doctor-*.tar.gz 2>/dev/null | tail -n +4 | while IFS= read -r p; do rm -f -- "$p"; done
    return 0
}

bk_list() {   # prints "file<TAB>size<TAB>date", newest first
    local f
    ls -1t -- "$BK_ROOT"/cs2nexus-*.tar.gz 2>/dev/null | while IFS= read -r f; do
        printf '%s\t%s\t%s\n' "$f" "$(du -h -- "$f" | cut -f1)" "$(date -d "@$(stat -c %Y -- "$f")" '+%Y-%m-%d %H:%M')"
    done
}

# scope filter for a restore: prints a grep -E pattern matching the paths (inside the archive, "./abs/path")
bk_scope_pattern() {
    case $1 in
        all)      echo '.' ;;
        wp)       echo '(WeaponPaints|weaponpaints)' ;;
        bans)     echo '/(ServerCommands|FakeBan)/data/' ;;
        admins)   echo '/configs/(admins\.json|ServerCommandsAdmins\.json)$' ;;
        settings) echo "^\\./($(printf '%s' "${DB#/}" | sed 's/[.]/\\./g')|${SHARED_DIR#/}/[^/]*\\.json|${SHARED_DIR#/}/nexus-features\\.conf|etc/cs2nexus\\.conf)|/cfg/(server|cs2nexus_settings)\\.cfg\$" ;;
        panel)    echo "^\\./${PANEL_DIR#/}/data|/configs/plugins/NexusLink/" ;;
    esac
}

backup_restore_ui() {
    local -a files=() lines=() sel
    local n c f scope pat tmp cnt=0 rows run
    mapfile -t lines < <(bk_list)
    if ((${#lines[@]} == 0)); then warn "No backups yet (folder: $BK_ROOT)."; return; fi
    header "RESTORE A BACKUP"
    n=0
    for c in "${lines[@]}"; do
        n=$((n + 1)); IFS=$'\t' read -r f sz dt <<<"$c"; files+=("$f")
        printf '  %2d) %s   %s   %s\n' "$n" "$dt" "$sz" "${f##*/}"
        ((n >= 30)) && break
    done
    echo "   b) Back"; echo
    read -r -p "Backup to restore: " c || exit 0
    c=$(trim "$c"); [[ $c == b || $c == B || -z $c ]] && return
    if ! [[ $c =~ ^[0-9]+$ ]] || ((10#$c < 1 || 10#$c > ${#files[@]})); then err "Invalid option."; return; fi
    f=${files[$((10#$c - 1))]}
    echo
    echo "  What do you want to restore?"
    echo "   1) Everything"
    echo "   2) WeaponPaints (config + database dump)"
    echo "   3) Bans & punishments (ServerCommands / FakeBan data)"
    echo "   4) Admin files"
    echo "   5) Server list, settings, registries and server.cfg"
    echo "   6) Web panel data"
    echo "   b) Back"; echo
    read -r -p "Select: " c || exit 0
    case "$(trim "$c")" in
        1) scope=all ;; 2) scope=wp ;; 3) scope=bans ;; 4) scope=admins ;; 5) scope=settings ;; 6) scope=panel ;;
        *) return ;;
    esac
    run=$(jq -r '.[].id' "$DB" 2>/dev/null | while read -r i; do is_running "$i" && printf '%s ' "$i"; done)
    if [[ -n $run ]]; then
        err "These servers are running: $run"
        echo "  Stop them first (Stop Server), then restore. Restoring under a running server does not work reliably."
        return
    fi
    pat=$(bk_scope_pattern "$scope")
    tmp=$(mktemp -d "$BK_ROOT/.restore.XXXXXX") || return
    if ! tar -C "$tmp" -xzpf "$f" 2>/dev/null; then err "The archive could not be read."; rm -rf --one-file-system -- "$tmp"; return; fi
    mapfile -t sel < <(cd "$tmp" && find . -type f -print | grep -E -- "$pat")
    if ((${#sel[@]} == 0)); then warn "This backup holds nothing for that choice."; rm -rf --one-file-system -- "$tmp"; return; fi
    echo "  ${#sel[@]} file(s) will be restored (existing files with the same path are replaced)."
    confirm_yn "Continue? A safety backup of the current state is made first. [y/N]: " n || { rm -rf --one-file-system -- "$tmp"; return; }
    backup_run prerestore || { err "Safety backup failed; nothing restored."; rm -rf --one-file-system -- "$tmp"; return; }
    for c in "${sel[@]}"; do
        c=${c#.}
        [[ $c == /* && $c != *..* ]] || continue
        mkdir -p -- "$(dirname -- "$c")"
        if cp -a -- "$tmp$c" "$c"; then cnt=$((cnt + 1)); fi
    done
    rm -rf --one-file-system -- "$tmp"
    ok "Restored $cnt file(s). Start your servers again."
    [[ $scope == all || $scope == settings ]] && info "Run 'Plugins -> Sync' once so every server picks up its files."
    if [[ $scope == all || $scope == wp ]] && [[ -s $SHARED_DIR/weaponpaints.sql ]]; then
        info "The WeaponPaints database dump is at $SHARED_DIR/weaponpaints.sql. Import it with: $(basename -- "$(wp_sql_bin 2>/dev/null || echo mariadb)") $(wp_db_get name 2>/dev/null) < $SHARED_DIR/weaponpaints.sql"
    fi
}

backup_timer_install() {
    command -v systemctl >/dev/null 2>&1 || { err "systemctl is not available."; return 1; }
    local hour; hour=$(fx_num BACKUP_HOUR 4 0 23)
    cat >"/etc/systemd/system/$BK_UNIT.service" <<EOF
[Unit]
Description=CS2Nexus data backup

[Service]
Type=oneshot
ExecStart=$SELF backup
EOF
    cat >"/etc/systemd/system/$BK_UNIT.timer" <<EOF
[Unit]
Description=Daily CS2Nexus data backup

[Timer]
OnCalendar=*-*-* $(printf '%02d' "$hour"):30:00
Persistent=true

[Install]
WantedBy=timers.target
EOF
    if systemctl daemon-reload && systemctl enable --now "$BK_UNIT.timer" >/dev/null 2>&1; then
        fx_set BACKUP_AUTO 1; ok "Automatic backup enabled (every day at $(printf '%02d' "$hour"):30)."
    else err "Could not enable the backup timer."; return 1; fi
}
backup_timer_remove() {
    command -v systemctl >/dev/null 2>&1 && systemctl disable --now "$BK_UNIT.timer" >/dev/null 2>&1
    rm -f -- "/etc/systemd/system/$BK_UNIT.service" "/etc/systemd/system/$BK_UNIT.timer"
    command -v systemctl >/dev/null 2>&1 && systemctl daemon-reload
    fx_set BACKUP_AUTO 0; ok "Automatic backup disabled."
}

backups_full_menu() {
    local c n a
    while :; do
        clear_screen; dsep
        printf '%s              DATA BACKUPS%s\n' "$BOLD" "$RESET"; dsep; echo
        a=$(systemctl is-active "$BK_UNIT.timer" 2>/dev/null || echo no)
        n=$(bk_list | wc -l)
        printf '  Folder        : %s\n  Backups       : %s (keeps the newest %s)\n  Automatic     : %s (daily %02d:30)\n\n' \
            "$BK_ROOT" "$n" "$(bk_keep)" "$([[ $a == active ]] && echo ON || echo OFF)" "$(fx_num BACKUP_HOUR 4 0 23)"
        echo "  Saved: WeaponPaints config + database dump, bans & punishments, admin files, server list,"
        echo "         settings, plugin registries, server.cfg and the web panel data."
        echo
        echo "  1) Back up now"
        echo "  2) Turn automatic daily backup ON / OFF"
        echo "  3) Change time and how many to keep"
        echo "  4) List backups"
        echo "  5) Restore a backup"
        echo "  6) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) backup_run manual; pause ;;
            2) if [[ $a == active ]]; then backup_timer_remove; else backup_timer_install; fi; pause ;;
            3) ask_num "Hour of the day (0-23)" "$(fx_num BACKUP_HOUR 4 0 23)" 0 23; fx_set BACKUP_HOUR "$ANSWER"
               ask_num "How many backups to keep" "$(bk_keep)" 1 365; fx_set BACKUP_KEEP "$ANSWER"
               [[ $a == active ]] && backup_timer_install; pause ;;
            4) bk_list | awk -F'\t' '{printf "  %s  %6s  %s\n", $3, $2, $1}'; pause ;;
            5) backup_restore_ui; pause ;;
            6|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

# =============================================================================
#  RESOURCE ALERTS  (timer every minute; log + optional Discord-style webhook / Telegram)
# =============================================================================
readonly AL_UNIT="cs2nexus-alerts"
readonly AL_LOG="/var/log/cs2nexus-alerts.log"
readonly AL_STATE="$STATE_DIR/alerts.state"

alert_send() {   # <text>   (never fails the caller)
    # Routes: log + journal + optional webhook + Telegram (via Cloudflare Worker) + Bale.
    # Telegram never talks to api.telegram.org from this host — only https://telbot.cs2nexus.ir/
    local msg=$1 url tok proxy_key tg_chat
    printf '%s %s\n' "$(date '+%F %T')" "$msg" >>"$AL_LOG" 2>/dev/null
    if [[ -f $AL_LOG ]] && (($(stat -c %s "$AL_LOG" 2>/dev/null || echo 0) > 1048576)); then tail -n 2000 "$AL_LOG" >"$AL_LOG.tmp" && mv -f "$AL_LOG.tmp" "$AL_LOG"; fi
    command -v logger >/dev/null 2>&1 && logger -t cs2nexus-alert -- "$msg"
    msg="[$(hostname)] $msg"
    url=$(fx_get ALERT_WEBHOOK)
    if [[ -n $url ]]; then
        curl -fsS -m 10 -H 'Content-Type: application/json' -d "$(jq -nc --arg c "$msg" '{content:$c, text:$c}')" "$url" >/dev/null 2>&1 || true
    fi
    tok=$(fx_get ALERT_TG_TOKEN)
    proxy_key=$(fx_get ALERT_TG_PROXY_KEY)
    # Require token + Worker key + at least one chat id. Failures never abort the caller.
    if [[ -n $tok && -n $proxy_key ]]; then
        while IFS= read -r tg_chat; do
            [[ -n $tg_chat ]] || continue
            curl -fsS -m 15 \
                -H "X-Proxy-Key: $proxy_key" \
                --data-urlencode "chat_id=$tg_chat" \
                --data-urlencode "text=$msg" \
                "https://telbot.cs2nexus.ir/bot${tok}/sendMessage" >/dev/null 2>&1 || true
        done < <(printf '%s\n%s\n' "$(fx_get ALERT_TG_CHAT)" "$(fx_get ALERT_TG_CHAT2)" | awk 'NF && !seen[$0]++')
    fi
    bale_send "$msg"
}

# ---------------- Bale bot (tapi.bale.ai — Telegram-compatible) ----------------
bale_token() {
    local t; t=$(fx_get BALE_TOKEN)
    if [[ -z $t ]]; then t='1143887056:9XYOpu_Vg2-pQq9Qs98heRvjSrUc-SbW5ow'; fi
    printf '%s' "$t"
}
bale_chat_ids() {
    # prints up to 2 unique chat ids (BALE_CHAT_ID + BALE_CHAT_ID2)
    local a b
    a=$(fx_get BALE_CHAT_ID); b=$(fx_get BALE_CHAT_ID2)
    [[ -n $a ]] && printf '%s\n' "$a"
    [[ -n $b && $b != "$a" ]] && printf '%s\n' "$b"
}
bale_send() {   # <text>  — sends to both configured chat ids
    local msg=$1 tok chat payload
    command -v curl >/dev/null 2>&1 || return 0
    tok=$(bale_token); [[ -n $tok ]] || return 0
    while IFS= read -r chat; do
        [[ -n $chat ]] || continue
        payload=$(jq -nc --arg c "$chat" --arg t "$msg" '{chat_id:(try ($c|tonumber) catch $c), text:$t}') || continue
        curl -fsS -m 12 -H 'Content-Type: application/json' \
            -d "$payload" "https://tapi.bale.ai/bot${tok}/sendMessage" >/dev/null 2>&1 || true
    done < <(bale_chat_ids)
}
bale_discover_chat() {
    local tok raw id slot
    tok=$(bale_token); [[ -n $tok ]] || { err "Bale token is empty."; return 1; }
    raw=$(curl -fsS -m 15 "https://tapi.bale.ai/bot${tok}/getUpdates?limit=30" 2>/dev/null) || { err "Could not reach Bale API."; return 1; }
    id=$(printf '%s' "$raw" | jq -r '[.result[]? | .message.chat // .callback_query.message.chat // empty | select((.type=="private") or (.type==null) or (.type=="")) | .id] | last // empty' 2>/dev/null)
    if [[ -z $id || $id == null ]]; then
        err "No private chat found. Open the bot in Bale, send /start, then try again."
        return 1
    fi
    # fill first empty slot, or replace chat1 if both full and same user re-runs
    if [[ -z $(fx_get BALE_CHAT_ID) ]]; then
        fx_set BALE_CHAT_ID "$id"; slot=1
    elif [[ $(fx_get BALE_CHAT_ID) == "$id" ]]; then
        slot=1; ok "Chat id 1 already set: $id"
    elif [[ -z $(fx_get BALE_CHAT_ID2) ]]; then
        fx_set BALE_CHAT_ID2 "$id"; slot=2
    elif [[ $(fx_get BALE_CHAT_ID2) == "$id" ]]; then
        slot=2; ok "Chat id 2 already set: $id"
    else
        # both slots used by others — ask which to overwrite is hard in non-interactive; default overwrite #2
        fx_set BALE_CHAT_ID2 "$id"; slot=2
        warn "Both slots were full; chat id 2 was replaced."
    fi
    ok "Bale chat id #$slot saved: $id"
    bale_send "CS2NEXUS connected (chat #$slot). You will get server start / stop / crash alerts here."
}
server_crash_snippet() {
    local logf=${1:-} out
    [[ -n $logf && -f $logf ]] || { printf '%s' "(no console log)"; return; }
    out=$(tail -n 40 -- "$logf" 2>/dev/null | tr -cd '\11\12\15\40-\176\n' | tail -n 15)
    out=$(printf '%s' "$out" | tail -c 1200)
    [[ -n $out ]] && printf '%s' "$out" || printf '%s' "(empty log)"
}
# server_crash_report <id>: saves everything useful for finding the cause of a crash in
# <server>/logs/crash-reports/crash-<time>.txt (console tail, CounterStrikeSharp log, plugins, game build)
# and prints the path. Only the newest 20 reports are kept.
server_crash_report() {
    local id=$1 dir f css cl pl line
    load_server "$id" 2>/dev/null || return 1
    dir="$S_PATH/logs/crash-reports"
    [[ -L $dir || -L $S_PATH/logs ]] && return 1
    mkdir -p -- "$dir" 2>/dev/null || return 1
    f="$dir/crash-$(date +%Y%m%d-%H%M%S).txt"
    css="$S_PATH/$CSGOREL/addons/counterstrikesharp"
    {
        echo "CS2Nexus crash report - server '$S_NAME' (id $id, port $S_PORT) - $(date '+%F %T %Z')"
        echo
        echo "== Game build =="
        grep -E '^(PatchVersion|ServerVersion|ClientVersion|VersionDate)=' "$S_PATH/$CSGOREL/steam.inf" 2>/dev/null || echo "(steam.inf not found)"
        echo
        echo "== Loaded CounterStrikeSharp plugins =="
        for pl in "$css"/plugins/*/; do [[ -d $pl ]] && echo "  $(basename "$pl")"; done 2>/dev/null
        echo
        echo "== Metamod / CounterStrikeSharp files (date = last update) =="
        ls -l --time-style=+%F "$css/bin/linuxsteamrt64/counterstrikesharp.so" "$S_PATH/$CSGOREL/addons/metamod/bin/linuxsteamrt64/server.so" 2>/dev/null | awk '{print "  " $6 "  " $7}'
        echo
        echo "== Last 80 console lines =="
        tail -n 80 -- "$S_PATH/logs/console.log" 2>/dev/null | tr -cd '\11\12\15\40-\176\n'
        echo
        echo "== CounterStrikeSharp log (newest file, last 60 lines) =="
        cl=$(ls -t "$css"/logs/*.txt 2>/dev/null | head -n1)
        if [[ -n $cl ]]; then tail -n 60 -- "$cl" 2>/dev/null | tr -cd '\11\12\15\40-\176\n'; else echo "(no CounterStrikeSharp log)"; fi
        echo
        if command -v coredumpctl >/dev/null 2>&1; then
            echo "== Core dumps (coredumpctl) =="
            coredumpctl list --no-pager 2>/dev/null | tail -n 4
            echo "  Backtrace of the newest one:  coredumpctl gdb   (then: bt)   or   coredumpctl info"
        fi
    } >"$f" 2>/dev/null
    chown "$CS2_USER:$CS2_GROUP" -- "$f" 2>/dev/null
    # keep only the newest 20
    ls -1t "$dir"/crash-*.txt 2>/dev/null | tail -n +21 | while IFS= read -r line; do rm -f -- "$line"; done
    printf '%s' "$f"
}

notify_server_event() {   # <event> <id>   start|stop|crash|fail_start
    local ev=$1 id=$2 name port snip msg rpt
    load_server "$id" 2>/dev/null || return 0
    name=${S_NAME:-"#$id"}; port=${S_PORT:-?}
    case $ev in
        start)
            msg="🟢 Server STARTED
• Name: $name
• ID: $id
• Port: $port
• Host: $(hostname)"
            ;;
        stop)
            msg="⏹ Server STOPPED (manual)
• Name: $name
• ID: $id
• Port: $port
• Host: $(hostname)"
            ;;
        crash)
            snip=$(server_crash_snippet "$S_PATH/logs/console.log")
            rpt=$(server_crash_report "$id" 2>/dev/null || true)
            msg="🔴 Server CRASHED / offline
• Name: $name
• ID: $id
• Port: $port
• Host: $(hostname)
• Watchdog will restart if autostart is enabled${rpt:+
• Full crash report: $rpt}

Last console lines:
$snip"
            ;;
        fail_start)
            snip=$(server_crash_snippet "$S_PATH/logs/console.log")
            msg="⚠️ Server FAILED TO STAY UP
• Name: $name
• ID: $id
• Port: $port
• Host: $(hostname)

Last console lines:
$snip"
            ;;
        *) return 0 ;;
    esac
    alert_send "$msg"
}


# one check (called every minute by the timer). A value must stay over its limit for ALERT_SUSTAIN
# checks in a row before an alert is sent; the same alert repeats at most every ALERT_COOLDOWN minutes.
alert_check() {
    [[ $(fx_get ALERT_ENABLED 0) == 1 ]] || return 0
    local lim_cpu lim_ram lim_disk sustain cool now
    lim_cpu=$(fx_num ALERT_CPU 90 1 100); lim_ram=$(fx_num ALERT_RAM 90 1 100); lim_disk=$(fx_num ALERT_DISK 90 1 100)
    sustain=$(fx_num ALERT_SUSTAIN 3 1 60); cool=$(fx_num ALERT_COOLDOWN 30 1 1440); now=$(date +%s)
    local -A st_streak=() st_last=() st_on=() prev=() cur=() val=() lim=() label=()
    local line k a b c
    if [[ -f $AL_STATE ]]; then
        while read -r k line; do
            case $k in
                P:*) prev[${k#P:}]="$line" ;;
                S:*) read -r a b c <<<"$line"; st_streak[${k#S:}]=$a; st_last[${k#S:}]=$b; st_on[${k#S:}]=$c ;;
            esac
        done <"$AL_STATE"
    fi
    local tick cores memtot memavail dfp tot idle t0
    tick=$(getconf CLK_TCK 2>/dev/null || echo 100); cores=$(nproc 2>/dev/null || echo 1)
    memtot=$(awk '/^MemTotal:/{print $2}' /proc/meminfo); memavail=$(awk '/^MemAvailable:/{print $2}' /proc/meminfo)
    read -r tot idle < <(awk '/^cpu /{ t = 0; for (i = 2; i <= NF; i++) t += $i; print t, $5 + $6 }' /proc/stat)
    # system CPU since the previous check
    cur[sys]="$tot $idle $now"
    if [[ -n ${prev[sys]:-} ]]; then
        read -r pt pi pn <<<"${prev[sys]}"
        if ((tot > pt)); then val[cpu]=$(( 100 * ((tot - pt) - (idle - pi)) / (tot - pt) )); fi
    fi
    val[ram]=$(( (memtot - memavail) * 100 / (memtot > 0 ? memtot : 1) ))
    dfp=$(df -P "$SERVERS_DIR" 2>/dev/null | awk 'NR==2{gsub("%","",$5); print $5}'); [[ $dfp =~ ^[0-9]+$ ]] && val[disk]=$dfp
    lim[cpu]=$lim_cpu; lim[ram]=$lim_ram; lim[disk]=$lim_disk
    label[cpu]="CPU of the machine"; label[ram]="RAM of the machine"; label[disk]="Disk ($SERVERS_DIR)"
    # every running server: its share of the machine
    local snap id name pid ticks pages ramp cpup
    snap=$(mktemp) && mon_snapshot >"$snap"
    while IFS=$'\t' read -r id name; do
        pid=$(tmux_cs2 list-panes -t "=$(session_name "$id"):" -F '#{pane_pid}' 2>/dev/null | head -n 1)
        [[ -n $pid ]] || continue
        read -r ticks pages < <(mon_sum "$snap" "$pid")
        ramp=$(( pages * $(getconf PAGESIZE 2>/dev/null || echo 4096) / 1024 * 100 / (memtot > 0 ? memtot : 1) ))
        val[s${id}ram]=$ramp; lim[s${id}ram]=$lim_ram; label[s${id}ram]="Server '$name' RAM (share of the machine)"
        cur[s$id]="$ticks $now"
        if [[ -n ${prev[s$id]:-} ]]; then
            read -r pt pn <<<"${prev[s$id]}"
            if ((now > pn)); then
                cpup=$(awk -v d="$((ticks - pt))" -v tk="$tick" -v s="$((now - pn))" -v c="$cores" 'BEGIN{ v = d / tk / s * 100 / c; if (v < 0) v = 0; printf "%d", v }')
                val[s${id}cpu]=$cpup; lim[s${id}cpu]=$lim_cpu; label[s${id}cpu]="Server '$name' CPU (share of the machine)"
            fi
        fi
    done < <(jq -r '.[] | [.id, .name] | @tsv' "$DB" 2>/dev/null)
    rm -f -- "$snap"
    for k in "${!val[@]}"; do
        if ((val[$k] >= lim[$k])); then
            st_streak[$k]=$(( ${st_streak[$k]:-0} + 1 ))
            if ((st_streak[$k] >= sustain)) && ((now - ${st_last[$k]:-0} >= cool * 60)); then
                alert_send "ALERT: ${label[$k]} is at ${val[$k]}% (limit ${lim[$k]}%, for ${st_streak[$k]} min)."
                st_last[$k]=$now; st_on[$k]=1
            fi
        else
            if [[ ${st_on[$k]:-0} == 1 ]]; then alert_send "OK again: ${label[$k]} is back to ${val[$k]}%."; fi
            st_streak[$k]=0; st_on[$k]=0
        fi
    done
    for k in "${!st_streak[@]}"; do   # a value that is no longer measured (server stopped) is forgotten silently
        [[ -n ${val[$k]+x} ]] || { st_streak[$k]=0; st_on[$k]=0; }
    done
    {
        for k in "${!cur[@]}"; do printf 'P:%s %s\n' "$k" "${cur[$k]}"; done
        for k in "${!st_streak[@]}"; do printf 'S:%s %s %s %s\n' "$k" "${st_streak[$k]}" "${st_last[$k]:-0}" "${st_on[$k]:-0}"; done
    } >"$AL_STATE.tmp" && mv -f -- "$AL_STATE.tmp" "$AL_STATE"
    return 0
}

alert_timer_install() {
    command -v systemctl >/dev/null 2>&1 || { err "systemctl is not available."; return 1; }
    cat >"/etc/systemd/system/$AL_UNIT.service" <<EOF
[Unit]
Description=CS2Nexus resource alert check

[Service]
Type=oneshot
ExecStart=$SELF alert-check
EOF
    cat >"/etc/systemd/system/$AL_UNIT.timer" <<EOF
[Unit]
Description=CS2Nexus resource alert check every minute

[Timer]
OnActiveSec=30
OnUnitActiveSec=60
AccuracySec=5s

[Install]
WantedBy=timers.target
EOF
    if systemctl daemon-reload && systemctl enable --now "$AL_UNIT.timer" >/dev/null 2>&1; then
        fx_set ALERT_ENABLED 1; ok "Resource alerts are ON (checked every minute)."
    else err "Could not enable the alert timer."; return 1; fi
}
alert_timer_remove() {
    command -v systemctl >/dev/null 2>&1 && systemctl disable --now "$AL_UNIT.timer" >/dev/null 2>&1
    rm -f -- "/etc/systemd/system/$AL_UNIT.service" "/etc/systemd/system/$AL_UNIT.timer" "$AL_STATE"
    command -v systemctl >/dev/null 2>&1 && systemctl daemon-reload
    fx_set ALERT_ENABLED 0; ok "Resource alerts are OFF."
}

alerts_menu() {
    local c v
    while :; do
        clear_screen; dsep
        printf '%s              RESOURCE ALERTS%s\n' "$BOLD" "$RESET"; dsep; echo
        printf '  State          : %s\n' "$([[ $(fx_get ALERT_ENABLED 0) == 1 ]] && echo "${GREEN}ON${RESET}" || echo "${RED}OFF${RESET}")"
        printf '  Limits         : CPU %s%%   RAM %s%%   Disk %s%%\n' "$(fx_num ALERT_CPU 90 1 100)" "$(fx_num ALERT_RAM 90 1 100)" "$(fx_num ALERT_DISK 90 1 100)"
        printf '  Alert when     : over the limit for %s minute(s) in a row; the same alert repeats at most every %s min\n' "$(fx_num ALERT_SUSTAIN 3 1 60)" "$(fx_num ALERT_COOLDOWN 30 1 1440)"
        printf '  Also checks    : every running server (its share of the machine, same CPU/RAM limits)\n'
        printf '  Log file       : %s\n' "$AL_LOG"
        v=$(fx_get ALERT_WEBHOOK); printf '  Webhook        : %s\n' "${v:+set}${v:-not set}"
        v=$(fx_get ALERT_TG_TOKEN); printf '  Telegram       : %s\n' "$([[ -n $v && -n $(fx_get ALERT_TG_CHAT) && -n $(fx_get ALERT_TG_PROXY_KEY) ]] && echo "set (Worker; $( [[ -n $(fx_get ALERT_TG_CHAT2) ]] && echo '2 recipients' || echo '1 recipient' ))" || echo 'not set / incomplete')"
        printf '  Bale           : token %s, chat1 %s, chat2 %s\n\n' "$([[ -n $(bale_token) ]] && echo set || echo 'not set')" "$([[ -n $(fx_get BALE_CHAT_ID) ]] && echo set || echo empty)" "$([[ -n $(fx_get BALE_CHAT_ID2) ]] && echo set || echo empty)"
        echo "  1) Turn alerts ON / OFF"
        echo "  2) Change the limits (CPU, RAM, disk)"
        echo "  3) Change how long / how often"
        echo "  4) Set the webhook (Discord or any URL that accepts JSON)"
        echo "  5) Set Telegram (Worker key + bot token + 2 chat ids)"
        echo "  6) Send a test alert"
        echo "  7) Show the alert log"
        echo "  8) Bale: auto-detect chat id (open bot, send /start, then run this)"
        echo "  9) Bale: set token / chat id manually"
        echo "  b) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) if [[ $(fx_get ALERT_ENABLED 0) == 1 ]]; then alert_timer_remove; else alert_timer_install; fi; pause ;;
            2) ask_num "CPU limit %" "$(fx_num ALERT_CPU 90 1 100)" 1 100; fx_set ALERT_CPU "$ANSWER"
               ask_num "RAM limit %" "$(fx_num ALERT_RAM 90 1 100)" 1 100; fx_set ALERT_RAM "$ANSWER"
               ask_num "Disk limit %" "$(fx_num ALERT_DISK 90 1 100)" 1 100; fx_set ALERT_DISK "$ANSWER"; ok "Saved."; pause ;;
            3) ask_num "Minutes over the limit before an alert" "$(fx_num ALERT_SUSTAIN 3 1 60)" 1 60; fx_set ALERT_SUSTAIN "$ANSWER"
               ask_num "Repeat the same alert at most every (minutes)" "$(fx_num ALERT_COOLDOWN 30 1 1440)" 1 1440; fx_set ALERT_COOLDOWN "$ANSWER"; ok "Saved."; pause ;;
            4) read -r -p "Webhook URL (empty = remove): " v || exit 0; v=$(trim "$v")
               if [[ -z $v || $v =~ ^https?://[^[:space:]]+$ ]]; then fx_set ALERT_WEBHOOK "$v"; ok "Saved."; else err "That is not an http(s) URL."; fi; pause ;;
            5) read -rsp "Telegram bot token (empty = remove): " v || exit 0; echo; v=$(trim "$v")
               if [[ -z $v ]]; then
                   fx_set ALERT_TG_TOKEN ""; fx_set ALERT_TG_CHAT ""; fx_set ALERT_TG_CHAT2 ""; fx_set ALERT_TG_PROXY_KEY ""; ok "Telegram settings removed."
               elif [[ $v =~ ^[0-9]+:[A-Za-z0-9_-]+$ ]]; then
                   read -r -p "Telegram chat id #1: " chat_input || exit 0; chat_input=$(trim "$chat_input")
                   if [[ $chat_input =~ ^-?[0-9]+$ ]]; then
                       read -r -p "Telegram chat id #2 (empty = only first recipient): " chat_input2 || exit 0; chat_input2=$(trim "$chat_input2")
                       if [[ -z $chat_input2 || $chat_input2 =~ ^-?[0-9]+$ ]]; then
                           read -rsp "Cloudflare Worker PROXY_KEY: " proxy_input || exit 0; echo
                           proxy_input=$(trim "$proxy_input")
                           if [[ -n $proxy_input ]]; then
                               fx_set ALERT_TG_TOKEN "$v"
                               fx_set ALERT_TG_CHAT "$chat_input"
                               fx_set ALERT_TG_CHAT2 "$chat_input2"
                               fx_set ALERT_TG_PROXY_KEY "$proxy_input"
                               ok "Telegram Worker settings saved for up to two recipients."
                           else err "Worker key cannot be empty; Telegram settings were not saved."; fi
                       else err "The second chat id must be a number or empty."; fi
                   else err "The first chat id must be a number."; fi
               else err "That does not look like a bot token."; fi; pause ;;
            6) alert_send "TEST: this is a test alert from CS2Nexus."; ok "Sent (log, journal$([[ -n $(fx_get ALERT_WEBHOOK) ]] && echo ', webhook')$([[ -n $(fx_get ALERT_TG_TOKEN) && -n $(fx_get ALERT_TG_CHAT) && -n $(fx_get ALERT_TG_PROXY_KEY) ]] && echo ', Telegram')$([[ -n $(fx_get BALE_CHAT_ID)$(fx_get BALE_CHAT_ID2) ]] && echo ', Bale'))."; pause ;;
            7) if [[ -s $AL_LOG ]]; then tail -n 30 "$AL_LOG"; else info "The log is empty."; fi; pause ;;
            8) bale_discover_chat; pause ;;
            9) read -r -p "Bale bot token (empty = keep default): " v || exit 0; v=$(trim "$v")
               if [[ -n $v ]]; then fx_set BALE_TOKEN "$v"; ok "Token saved."; fi
               read -r -p "Bale chat id #1 (empty = keep, - = clear): " v || exit 0; v=$(trim "$v")
               if [[ $v == - ]]; then fx_set BALE_CHAT_ID ""; ok "Chat id #1 cleared.";
               elif [[ -n $v ]]; then fx_set BALE_CHAT_ID "$v"; ok "Chat id #1 saved."; fi
               read -r -p "Bale chat id #2 (empty = keep, - = clear): " v || exit 0; v=$(trim "$v")
               if [[ $v == - ]]; then fx_set BALE_CHAT_ID2 ""; ok "Chat id #2 cleared.";
               elif [[ -n $v ]]; then fx_set BALE_CHAT_ID2 "$v"; ok "Chat id #2 saved."; fi
               pause ;;
            b|B|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

# =============================================================================
#  WEB PANEL  (players' website: login with !getcode, live servers, history, matches)
#  The panel files and the NexusLink plugin are built into this launcher.
# =============================================================================
readonly PANEL_UNIT="cs2nexus-panel"
readonly PANEL_VERSION="3.0.11"
readonly PANEL_SETTINGS="$PANEL_DIR/data/settings.json"

panel_installed() { [[ -f $PANEL_DIR/app/server/index.js && -f $PANEL_SETTINGS ]]; }
panel_get() { jq -r --arg k "$1" '.[$k] // empty' "$PANEL_SETTINGS" 2>/dev/null; }
panel_set() {   # <key> <json value>
    local tmp
    tmp=$(mktemp "$PANEL_SETTINGS.XXXXXX") || return 1
    if jq --arg k "$1" --argjson v "$2" '.[$k] = $v' "$PANEL_SETTINGS" >"$tmp" 2>/dev/null; then
        chown "root:$CS2_GROUP" "$tmp"; chmod 640 "$tmp"; mv -f -- "$tmp" "$PANEL_SETTINGS"
    else rm -f -- "$tmp"; return 1; fi
}
panel_running() { systemctl is-active --quiet "$PANEL_UNIT.service" 2>/dev/null; }
panel_host() {
    local h; h=$(panel_get domain)
    [[ -n $h ]] || h=$(hostname -I 2>/dev/null | awk '{print $1}')
    printf '%s' "${h:-your-server-ip}"
}
panel_url() {
    local scheme=http port; port=$(panel_get port)
    if [[ $(panel_get nginx) == true ]]; then
        [[ $(panel_get nginx_ssl) == true ]] && scheme=https
        printf '%s://%s' "$scheme" "$(panel_host)"; return
    fi
    [[ -n $(panel_get tls_cert) ]] && scheme=https
    if [[ ($scheme == http && $port == 80) || ($scheme == https && $port == 443) ]]; then printf '%s://%s' "$scheme" "$(panel_host)"
    else printf '%s://%s:%s' "$scheme" "$(panel_host)" "$port"; fi
}

# the list of servers the website shows (written for the panel user, nothing secret in it)
# the list of servers the website shows (written for the panel user, nothing secret in it)
panel_export_servers() {
    [[ -d $PANEL_DIR/data ]] || return 0
    local tmp="$PANEL_DIR/data/servers-public.json.tmp"
    jq --arg rel "${CSGOREL:-game/csgo}" '[.[] | {id:.id, name:.name, port:.port, maxplayers:.maxplayers, map:.map, cfg:((.path // "") + "/" + $rel + "/addons/counterstrikesharp/configs")}]' "$DB" >"$tmp" 2>/dev/null \
        && chown "$CS2_USER:$CS2_GROUP" "$tmp" && chmod 644 "$tmp" && mv -f -- "$tmp" "$PANEL_DIR/data/servers-public.json"
    rent_export_plugins
    return 0
}

# per-server NexusLink config (server id + panel address + key). Uses the loaded server (S_*).
panel_write_plugin_config_current() {   # [disabled]
    panel_installed || return 0
    local base="$S_PATH/$CSGOREL" dir f key ip en=true
    [[ ${1:-} == disabled ]] && en=false
    [[ -d $base && ! -L $base ]] || return 0
    dir="$base/addons/counterstrikesharp/configs/plugins/NexusLink"
    ensure_chain "$base" "$dir" || return 0
    f="$dir/NexusLink.json"; key=$(panel_get api_key); ip=$(panel_get internal_port)
    local new
    new=$(jq -n --argjson en "$en" --arg url "http://127.0.0.1:${ip:-27500}" --arg key "$key" --argjson id "$S_ID" \
        '{ConfigVersion:1, Enabled:$en, PanelUrl:$url, ApiKey:$key, ServerId:$id, SnapshotSeconds:5, CodeCooldownSeconds:15, MinMatchRounds:3, ChatPrefix:"[Nexus]"}')
    if [[ -f $f && $(jq -S . "$f" 2>/dev/null) == "$(jq -S . <<<"$new")" ]]; then return 0; fi
    printf '%s\n' "$new" >"$f" && chown "$CS2_USER:$CS2_GROUP" "$f" && chmod 640 "$f"
    PANEL_CFG_CHANGED=1
    return 0
}
PANEL_CFG_CHANGED=0
panel_write_all_plugin_configs() {   # [disabled]
    local id; PANEL_CFG_CHANGED=0
    while IFS= read -r id; do load_server "$id" && panel_write_plugin_config_current "${1:-}"; done < <(jq -r '.[].id' "$DB")
}

panel_payload_extract() {   # <dest>
    awk '/^#__NEXUS_PAYLOAD_END__$/{f=0} f{sub(/^#/,""); print} /^#__NEXUS_PAYLOAD_BEGIN__$/{f=1}' "$SELF" | base64 -d 2>/dev/null | tar -xz -C "$1" 2>/dev/null
}

# ----- rented servers: jobs written by the web panel (rent-req-<id>.json), run as root through a systemd path unit -----
rent_state() {   # <req> <state> [server id] [error]: the answer the panel waits for
    local f="$PANEL_DIR/data/rent-res-$1.json" tmp="$PANEL_DIR/data/.rent-res-$1.tmp"
    jq -nc --arg s "$2" --argjson id "${3:-0}" --arg e "${4:-}" --argjson t "$(date +%s)" '{state:$s,server_id:$id,error:$e,ts:$t}' >"$tmp" 2>/dev/null \
        && chown "$CS2_USER:$CS2_GROUP" "$tmp" 2>/dev/null; chmod 644 "$tmp" 2>/dev/null; mv -f -- "$tmp" "$f"
}

rent_export_plugins() {   # which plugins exist and where they are switched off (the panel hides the mandatory ones)
    [[ -d $PANEL_DIR/data ]] || return 0
    local tmp="$PANEL_DIR/data/.plugins-public.tmp"
    if [[ -f $SHARED_DB ]] && jq '[.[] | select(type=="object") | {name:((.name // "") | tostring), exclude:((.exclude // []) | map(select(type=="number"))), include:((.include // []) | map(select(type=="number")))}]' "$SHARED_DB" >"$tmp" 2>/dev/null; then
        chown "$CS2_USER:$CS2_GROUP" "$tmp" 2>/dev/null; chmod 644 "$tmp"; mv -f -- "$tmp" "$PANEL_DIR/data/plugins-public.json"
    fi
    return 0
}

rent_export_settings() {   # <rental id> <server id>: what the renter sees in the settings page (never the token or the password themselves)
    local rid=$1 id=$2 tmp="$PANEL_DIR/data/.rentsettings-$1.tmp" e
    e=$(st_get "$id"); [[ -n $e ]] || e='{}'
    load_server "$id" || return 0
    jq -nc --argjson e "$e" --arg map "$S_MAP" '{map:$map, gslt:(($e.launch.gslt // "") != ""), password:(($e.cvars.sv_password // "") != ""),
        custom:[($e.custom // [])[] | select(endswith(" //r")) | sub(" //r$"; "")]}' >"$tmp" 2>/dev/null \
        && chown "$CS2_USER:$CS2_GROUP" "$tmp" 2>/dev/null; chmod 644 "$tmp" 2>/dev/null; mv -f -- "$tmp" "$PANEL_DIR/data/rentsettings-$rid.json"
}

rent_is_rented() {   # <rental id> <server id>: the panel lists the servers it rented out; every other server is refused
    jq -e --argjson r "$1" --argjson s "$2" 'any(.[]; .rid == $r and .server_id == $s)' "$PANEL_DIR/data/rentals-export.json" >/dev/null 2>&1
}

rent_plugin_mandatory() { case ${1,,} in servercommands|nexuslink|nexuscommands|fakeban|nexusadmintools) return 0 ;; esac; return 1; }

rent_job_create() {   # <req> <job file>
    local req=$1 f=$2 rid name slug players port owner oname id flags
    IFS=$'\t' read -r rid name slug players port owner oname < <(jq -r '[(.rid|tostring), .name, .slug, (.players|tostring), (.port|tostring), .owner, (.owner_name // "owner")] | @tsv' "$f" 2>/dev/null)
    [[ $rid =~ ^[0-9]+$ && $name =~ ^[A-Za-z0-9][A-Za-z0-9\ ]{3,18}[A-Za-z0-9]$ && $slug =~ ^[a-z0-9][a-z0-9-]{0,40}$ && $players =~ ^[0-9]+$ && $port =~ ^[0-9]+$ && $owner =~ ^[0-9]{17}$ ]] \
        || { rent_state "$req" failed 0 "invalid job"; return; }
    players=$((10#$players)); port=$((10#$port))
    ((players >= 1 && players <= MAX_CLIENTS && port >= MIN_PORT && port <= MAX_PORT - 5)) || { rent_state "$req" failed 0 "invalid players or port"; return; }
    oname=$(rent_label "$oname")
    lock_ops 120 || { rent_state "$req" failed 0 "manager busy"; return; }
    if db_port_registered "$port" || db_port_registered "$((port + 5))" || port_in_use "$port" || port_in_use "$((port + 5))"; then rent_state "$req" failed 0 "port is not free"; unlock_ops; return; fi
    if db_name_taken "$name" "$slug" || [[ -e $SERVERS_DIR/$slug || -L $SERVERS_DIR/$slug ]]; then rent_state "$req" failed 0 "name is not free"; unlock_ops; return; fi
    rent_state "$req" working
    if ! create_server_core "$name" "$slug" "$players" "$port" "$DEFAULT_MAP" || [[ -z $CREATED_ID ]]; then
        rent_state "$req" failed 0 "server could not be created"; unlock_ops; return
    fi
    id=$CREATED_ID
    # a rented server starts with the mandatory plugins and WeaponPaints (+ its libraries) + MapVote only
    if ((SHARED_OK)); then
        shared_update --argjson id "$id" '[.[] | if type=="object" and ((.name // "") | ascii_downcase) as $n | (["servercommands","nexuslink","nexuscommands","fakeban","nexusadmintools","weaponpaints","playersettings","menumanagercore","mapvote"] | index($n)) == null
            then .exclude = (((.exclude // []) + [$id]) | unique) else . end]' >/dev/null
        load_server "$id" && { DRY_RUN=0; sync_shared_current || true; }
    fi
    # the renter is the OWNER of this one server (in the game too): every permission except adminsp, with their real name unchanged
    flags=$(printf '%s\n' "${ADMIN_PERMS[@]}" | jq -R 'split("|")[0] | select(. != "adminsp") | "@nepentii/" + .' | jq -sc .)
    admin_write_server "$id" "$owner" "$oname" 40 "OWNER" true "$flags" || warn "Could not write the renter as admin of server $id."
    ((AUTOSTART_OK)) && autostart_update --argjson id "$id" '. + [$id] | unique' >/dev/null
    panel_export_servers; rent_export_plugins; rent_export_settings "$rid" "$id"
    if ! load_server "$id" || ! { is_running "$id" || start_server "$id"; }; then
        rent_state "$req" done "$id" "created, but the first start failed"
    else
        rent_state "$req" done "$id"
    fi
    unlock_ops
}

rent_job_settings() {   # <req> <job file>
    local req=$1 f=$2 rid sid v name players map gslt pw
    rid=$(jq -r '.rid | tostring' "$f" 2>/dev/null); sid=$(jq -r '.server_id | tostring' "$f" 2>/dev/null)
    [[ $rid =~ ^[0-9]+$ && $sid =~ ^[0-9]+$ ]] && rent_is_rented "$rid" "$sid" || { rent_state "$req" failed 0 "not a rented server"; return; }
    lock_ops 60 || { rent_state "$req" failed 0 "manager busy"; return; }
    load_server "$sid" || { rent_state "$req" failed 0 "server not found"; unlock_ops; return; }
    rent_state "$req" working
    if jq -e 'has("name")' "$f" >/dev/null; then
        name=$(jq -r .name "$f")
        if [[ $name =~ ^[A-Za-z0-9][A-Za-z0-9\ ]{3,18}[A-Za-z0-9]$ ]]; then
            if [[ ${name,,} != "${S_NAME,,}" ]] && db_name_taken "$name" "no-such-slug-$rid"; then rent_state "$req" failed 0 "name is not free"; unlock_ops; return; fi
            db_update --argjson id "$sid" --arg n "$name" 'map(if .id == $id then .name = $n else . end)' >/dev/null
        else rent_state "$req" failed 0 "invalid name"; unlock_ops; return; fi
    fi
    if jq -e 'has("players")' "$f" >/dev/null; then
        players=$(jq -r '.players | tostring' "$f")
        [[ $players =~ ^[0-9]+$ ]] && ((10#$players >= 1 && 10#$players <= MAX_CLIENTS)) || { rent_state "$req" failed 0 "invalid players"; unlock_ops; return; }
        db_update --argjson id "$sid" --argjson p "$((10#$players))" 'map(if .id == $id then .maxplayers = $p else . end)' >/dev/null
    fi
    if jq -e 'has("map")' "$f" >/dev/null; then
        normalize_map "$(jq -r .map "$f")" || { rent_state "$req" failed 0 "invalid map"; unlock_ops; return; }
        db_update --argjson id "$sid" --arg m "$MAP_NORM" 'map(if .id == $id then .map = $m else . end)' >/dev/null
    fi
    if jq -e 'has("gslt")' "$f" >/dev/null; then
        gslt=$(jq -r .gslt "$f")
        if [[ -n $gslt ]]; then
            valid_gslt "$gslt" || { rent_state "$req" failed 0 "invalid token"; unlock_ops; return; }
            gslt_in_use "$sid" "$gslt" && { rent_state "$req" failed 0 "this token is already used by another server"; unlock_ops; return; }
            st_update "$sid" '.launch.gslt = $v' --arg v "$gslt" >/dev/null
        else st_update "$sid" 'del(.launch.gslt)' >/dev/null; fi
    fi
    if jq -e 'has("password")' "$f" >/dev/null; then
        pw=$(jq -r .password "$f")
        if [[ -n $pw ]]; then
            [[ $pw =~ ^[A-Za-z0-9_.-]{1,32}$ ]] || { rent_state "$req" failed 0 "invalid password"; unlock_ops; return; }
            st_update "$sid" '.cvars.sv_password = $v' --arg v "$pw" >/dev/null
        else st_update "$sid" 'del(.cvars.sv_password)' >/dev/null; fi
    fi
    if jq -e '(.custom // null) | type == "array"' "$f" >/dev/null 2>&1; then
        # lines of the renter carry a " //r" marker, so lines the owner put into the default settings are never touched
        local bad
        bad=$(jq -r '[.custom[] | select((type == "string" and test("^[a-z0-9_]+( [A-Za-z0-9_.:,/ -]{0,80})?$") and (split(" ")[0] | test("^(mp|sv|bot|cs|ammo|weapon|spec|inferno|molotov|healthshot|game|cl|mm|nav|phys|ff|tr)_")) and (split(" ")[0] | test("^(sv_setsteamaccount|sv_logfile|sv_visiblemaxplayers|sv_password|sv_rcon.*|rcon.*|tv_.*)$") | not)) | not)] | length' "$f" 2>/dev/null)
        [[ $bad == 0 ]] || { rent_state "$req" failed 0 "a custom line is not allowed"; unlock_ops; return; }
        st_update "$sid" '.custom = (((.custom // []) | map(select(endswith(" //r") | not))) + ($c | map(. + " //r")))' --argjson c "$(jq -c '.custom' "$f")" >/dev/null
    fi
    load_server "$sid" && write_server_cfg "$S_PATH" "$S_NAME" "$S_MAX" "$S_PORT" "$sid" >/dev/null 2>&1
    # push the join password (and a renamed server) to a RUNNING server right away, so the
    # password really blocks joins now - not only after the next restart
    if is_running "$sid"; then
        if jq -e 'has("password")' "$f" >/dev/null 2>&1; then
            if [[ -n $pw ]]; then
                console_send "$sid" "sv_password \"$pw\"" >/dev/null 2>&1 \
                    && ok "Password applied to the running server (joins need it now)." \
                    || warn "Could not reach the console; the password applies at the next restart."
            else
                console_send "$sid" 'sv_password ""' >/dev/null 2>&1 \
                    && ok "Password removed on the running server." \
                    || warn "Could not reach the console; the change applies at the next restart."
            fi
        fi
        if jq -e 'has("name")' "$f" >/dev/null 2>&1; then
            console_send "$sid" "hostname \"$S_NAME\"" >/dev/null 2>&1 || true
        fi
    fi
    panel_export_servers; rent_export_settings "$rid" "$sid"
    rent_state "$req" done "$sid"
    unlock_ops
}

# RCON typed on the "Manage" page of a rented server: sent to that server's console, answered with what the console printed
rent_state_out() {   # <req> <server id> <console text>
    local f="$PANEL_DIR/data/rent-res-$1.json" tmp="$PANEL_DIR/data/.rent-res-$1.tmp"
    printf '%s' "$3" | jq -Rsc --argjson id "${2:-0}" --argjson t "$(date +%s)" '{state:"done",server_id:$id,error:"",ts:$t,out:(split("\n") | map(select(length > 0)) | .[-30:])}' >"$tmp" 2>/dev/null \
        && chown "$CS2_USER:$CS2_GROUP" "$tmp" 2>/dev/null; chmod 644 "$tmp" 2>/dev/null; mv -f -- "$tmp" "$f"
}

rent_job_rcon() {   # <req> <job file>
    local req=$1 f=$2 rid sid cmd first logf s0 s1 out
    rid=$(jq -r '.rid | tostring' "$f" 2>/dev/null); sid=$(jq -r '.server_id | tostring' "$f" 2>/dev/null); cmd=$(jq -r '.cmd // ""' "$f" 2>/dev/null)
    [[ $rid =~ ^[0-9]+$ && $sid =~ ^[0-9]+$ ]] && rent_is_rented "$rid" "$sid" || { rent_state "$req" failed 0 "not a rented server"; return; }
    if [[ -z $cmd || ${#cmd} -gt 200 || $cmd =~ [[:cntrl:]] || $cmd == *';'* ]]; then rent_state "$req" failed 0 "invalid command"; return; fi
    first=${cmd%%[[:space:]]*}; first=${first,,}
    # the commands that would let a renter go beyond their own server (the panel checks this too)
    if [[ $first =~ ^(quit|exit|_restart|killserver|css_rcon|css_plugins|css_plugin|meta|exec|writeid|writeip|sv_setsteamaccount|sv_logfile|sv_visiblemaxplayers|sv_password|sv_rcon[a-z_]*|rcon[a-z_]*|tv_[a-z_]+|maxplayers|hostport|net_[a-z_]+|plugin_[a-z_]+)$ ]]; then
        rent_state "$req" failed 0 "this command is not allowed"; return
    fi
    load_server "$sid" || { rent_state "$req" failed 0 "server not found"; return; }
    is_running "$sid" || { rent_state "$req" failed 0 "the server is offline"; return; }
    logf="$S_PATH/logs/console.log"
    s0=$(stat -c %s -- "$logf" 2>/dev/null || echo 0)
    console_send "$sid" "$cmd" >/dev/null 2>&1 || { rent_state "$req" failed 0 "could not reach the server console"; return; }
    sleep 1.2
    s1=$(stat -c %s -- "$logf" 2>/dev/null || echo 0)
    out=""
    if ((s1 > s0)); then
        out=$(tail -c "+$((s0 + 1))" -- "$logf" 2>/dev/null | head -c 30000 | sed -E 's/\x1b\[[0-9;?]*[A-Za-z]//g; s/\r//g' | tr -d '\000' | tail -n 30 | cut -c1-240)
    fi
    rent_state_out "$req" "$sid" "$out"
}

rent_job_plugin() {   # <req> <job file>
    local req=$1 f=$2 rid sid name on
    rid=$(jq -r '.rid | tostring' "$f" 2>/dev/null); sid=$(jq -r '.server_id | tostring' "$f" 2>/dev/null); name=$(jq -r '.plugin // ""' "$f" 2>/dev/null); on=$(jq -r '.on | tostring' "$f" 2>/dev/null)
    [[ $rid =~ ^[0-9]+$ && $sid =~ ^[0-9]+$ ]] && rent_is_rented "$rid" "$sid" || { rent_state "$req" failed 0 "not a rented server"; return; }
    [[ $name =~ ^[A-Za-z0-9._+@-]+$ && $on =~ ^(true|false)$ ]] && ! rent_plugin_mandatory "$name" || { rent_state "$req" failed 0 "this plugin cannot be changed"; return; }
    shared_db_ok && jq -e --arg n "$name" 'any(.[]; type=="object" and .name == $n)' "$SHARED_DB" >/dev/null 2>&1 || { rent_state "$req" failed 0 "unknown plugin"; return; }
    lock_ops 60 || { rent_state "$req" failed 0 "manager busy"; return; }
    rent_state "$req" working
    # "exclude" wins over everything; switching on also adds the server to "include" when the plugin is limited to some servers
    shared_update --arg n "$name" --argjson id "$sid" --argjson on "$on" '[.[] | if type=="object" and .name == $n then
        (if $on then (.exclude = ((.exclude // []) - [$id])) | (if ((.include // []) | length) > 0 then .include = (((.include // []) + [$id]) | unique) else . end)
         else (.exclude = (((.exclude // []) + [$id]) | unique)) end) else . end]' >/dev/null
    if load_server "$sid"; then DRY_RUN=0; sync_shared_current || true; fi
    rent_export_plugins
    rent_state "$req" done "$sid"
    unlock_ops
}

rent_job_admin() {   # <req> <job file>: the renter's own admins, and handing the server over to someone else
    local req=$1 f=$2 rid sid op act ident name old new fl p ok
    rid=$(jq -r '.rid | tostring' "$f" 2>/dev/null); sid=$(jq -r '.server_id | tostring' "$f" 2>/dev/null); op=$(jq -r '.op // ""' "$f" 2>/dev/null); act=$(jq -r '.action // ""' "$f" 2>/dev/null)
    [[ $rid =~ ^[0-9]+$ && $sid =~ ^[0-9]+$ ]] && rent_is_rented "$rid" "$sid" || { rent_state "$req" failed 0 "not a rented server"; return; }
    lock_ops 60 || { rent_state "$req" failed 0 "manager busy"; return; }
    rent_state "$req" working
    if [[ $op == transfer ]]; then
        old=$(jq -r '.old // ""' "$f"); new=$(jq -r '.new // ""' "$f"); name=$(rent_label "$(jq -r '.new_name // "owner"' "$f")")
        if [[ ! $old =~ ^[0-9]{17}$ || ! $new =~ ^[0-9]{17}$ || $old == "$new" ]]; then rent_state "$req" failed 0 "invalid players"; unlock_ops; return; fi
        # the old owner loses the server in the game too; the new one becomes its administrator with the same permissions the renter always has
        fl=$(printf '%s\n' "${ADMIN_PERMS[@]}" | jq -R 'split("|")[0] | select(. != "adminsp") | "@nepentii/" + .' | jq -sc .)
        admin_remove_server "$sid" "$old"; admin_remove_server "$sid" "$new"
        if admin_write_server "$sid" "$new" "$name" 40 "OWNER" true "$fl"; then rent_state "$req" done "$sid"; else rent_state "$req" failed 0 "could not write the new owner"; fi
        unlock_ops; return
    fi
    ident=$(jq -r '.identity // ""' "$f"); name=$(jq -r '.name // "admin"' "$f")
    if [[ ! $ident =~ ^[0-9]{17}$ ]]; then rent_state "$req" failed 0 "invalid player"; unlock_ops; return; fi
    if [[ $act == remove ]]; then
        admin_remove_server "$sid" "$ident"; rent_state "$req" done "$sid"; unlock_ops; return
    fi
    # only the permissions the panel allows for a server admin (never adding other admins); RCON only comes with the renter's "All" level
    local tag im
    tag=$(jq -r '.tag // "ADMIN"' "$f" 2>/dev/null | tr -cd 'A-Za-z0-9 ' | cut -c1-10); tag=${tag^^}; tag=${tag#"${tag%%[! ]*}"}; tag=${tag%"${tag##*[! ]}"}
    [[ -n $tag && $tag != OWNER ]] || tag=ADMIN
    im=$(jq -r '.immunity // 20' "$f" 2>/dev/null); [[ $im =~ ^(10|20|30)$ ]] || im=20
    fl='[]'
    while IFS= read -r p; do
        [[ $p =~ ^[a-z]+$ && $p != addadmin && $p != adminsp ]] || continue
        printf '%s\n' "${ADMIN_PERMS[@]}" | cut -d'|' -f1 | grep -qx -- "$p" || continue
        fl=$(jq -c --arg f "@nepentii/$p" '. + [$f]' <<<"$fl")
    done < <(jq -r '(.flags // [])[]' "$f" 2>/dev/null)
    if [[ $act != set || $fl == '[]' ]]; then rent_state "$req" failed 0 "no permissions"; unlock_ops; return; fi
    if admin_write_server "$sid" "$ident" "$name" "$im" "$tag" true "$fl"; then rent_state "$req" done "$sid"; else rent_state "$req" failed 0 "could not write the admin"; fi
    unlock_ops
}

rent_label() {   # a name for the admin files: keeps any language (the player's own name is never changed), drops only unsafe characters
    local v
    v=$(printf '%s' "$1" | jq -Rr 'gsub("[\\p{Cc}\"\\\\<>`$;\u0027{}%]"; "") | gsub("\\s+"; " ") | gsub("^ +| +$"; "") | .[0:32]' 2>/dev/null)
    printf '%s' "${v:-owner}"
}

rent_owner_flags() {   # the permissions of a renter on his own server: everything except adminsp (addadmin included)
    printf '%s\n' "${ADMIN_PERMS[@]}" | jq -R 'split("|")[0] | select(. != "adminsp") | "@nepentii/" + .' | jq -sc .
}

rent_job_owner() {   # <req> <job file>: (re)writes the owner entry of a rented server: OWNER tag, real name, addadmin and the rest
    local req=$1 f=$2 rid sid owner oname flags
    rid=$(jq -r '.rid | tostring' "$f" 2>/dev/null); sid=$(jq -r '.server_id | tostring' "$f" 2>/dev/null); owner=$(jq -r '.owner // ""' "$f" 2>/dev/null)
    oname=$(rent_label "$(jq -r '.owner_name // "owner"' "$f" 2>/dev/null)")
    [[ $rid =~ ^[0-9]+$ && $sid =~ ^[0-9]+$ && $owner =~ ^[0-9]{17}$ ]] && rent_is_rented "$rid" "$sid" || { rent_state "$req" failed 0 "not a rented server"; return; }
    lock_ops 60 || { rent_state "$req" failed 0 "manager busy"; return; }
    flags=$(rent_owner_flags)
    if admin_write_server "$sid" "$owner" "$oname" 40 "OWNER" true "$flags"; then rent_state "$req" done "$sid"; else rent_state "$req" failed 0 "could not write the owner"; fi
    unlock_ops
}

rent_job_delete() {   # <req> <job file>: removes one rented server completely (files, registry entry, autostart, plugin switches)
    local req=$1 f=$2 rid sid
    rid=$(jq -r '.rid | tostring' "$f" 2>/dev/null); sid=$(jq -r '.server_id | tostring' "$f" 2>/dev/null)
    [[ $rid =~ ^[0-9]+$ && $sid =~ ^[0-9]+$ ]] && rent_is_rented "$rid" "$sid" || { rent_state "$req" failed 0 "not a rented server"; return; }
    lock_ops 180 || { rent_state "$req" failed 0 "manager busy"; return; }
    if ! load_server "$sid"; then rent_state "$req" done "$sid"; unlock_ops; return; fi   # already gone
    rent_state "$req" working
    if ! safe_server_path "$S_PATH" "$S_SLUG"; then rent_state "$req" failed 0 "unsafe server path"; unlock_ops; return; fi
    if jq -e --argjson id "$sid" --arg p "$S_PATH" 'any(.[]; .id != $id and .path == $p)' "$DB" >/dev/null 2>&1; then rent_state "$req" failed 0 "another server uses the same path"; unlock_ops; return; fi
    if is_running "$sid"; then
        stop_session "$sid" || { rent_state "$req" failed 0 "the server could not be stopped"; unlock_ops; return; }
    fi
    if [[ -e $S_PATH || -L $S_PATH ]]; then
        safe_server_path "$S_PATH" "$S_SLUG" || { rent_state "$req" failed 0 "path check failed"; unlock_ops; return; }
        rm -rf --one-file-system -- "$S_PATH" || { rent_state "$req" failed 0 "the files could not be removed"; unlock_ops; return; }
    fi
    if ! db_update --argjson id "$sid" 'map(select(.id != $id))' >/dev/null; then rent_state "$req" failed 0 "the registry entry could not be removed"; unlock_ops; return; fi
    vault_forget_server "${S_SLUG:-}"
    clear_server_state "$sid"
    ((AUTOSTART_OK)) && autostart_update --argjson id "$sid" 'map(select(. != $id))' >/dev/null
    # forget the server in the plugin switches (an "include" list is only shortened when it keeps at least one server)
    ((SHARED_OK)) && shared_update --argjson id "$sid" '[.[] | if type=="object" then .exclude = ((.exclude // []) - [$id])
        | (if (((.include // []) - [$id]) | length) > 0 then .include = ((.include // []) - [$id]) else . end) else . end]' >/dev/null
    rm -f -- "$PANEL_DIR/data/rentsettings-$rid.json"
    panel_export_servers; rent_export_plugins
    rent_state "$req" done "$sid"
    unlock_ops
}

panel_rent_run() {
    local f req op n=0 sz
    while ((n++ < 40)); do
        local -a files=()
        for f in "$PANEL_DIR"/data/rent-req-*.json; do [[ -f $f && ! -L $f ]] && files+=("$f"); done
        ((${#files[@]})) || break
        for f in "${files[@]}"; do
            req=${f##*/rent-req-}; req=${req%.json}
            sz=$(stat -c %s -- "$f" 2>/dev/null || echo 0)
            # the job is copied first (and removed at once), so the panel can see that the helper picked it up
            local job; job=$(mktemp) || continue
            if [[ $req =~ ^[0-9a-f]{12}$ ]] && ((sz > 0 && sz < 65536)) && cp -- "$f" "$job" && jq -e 'type == "object"' "$job" >/dev/null 2>&1; then
                rm -f -- "$f"
                op=$(jq -r '.op // ""' "$job")
                case $op in
                    create) rent_job_create "$req" "$job" ;;
                    settings) rent_job_settings "$req" "$job" ;;
                    plugin) rent_job_plugin "$req" "$job" ;;
                    rcon) rent_job_rcon "$req" "$job" ;;
                    admin|transfer) rent_job_admin "$req" "$job" ;;
                    owner) rent_job_owner "$req" "$job" ;;
                    delete) rent_job_delete "$req" "$job" ;;
                    *) [[ $req =~ ^[0-9a-f]{12}$ ]] && rent_state "$req" failed 0 "unknown job" ;;
                esac
            else rm -f -- "$f"; fi
            rm -f -- "$job"
        done
    done
    return 0
}

panel_unit_write() {
    command -v systemctl >/dev/null 2>&1 || { err "systemd is not available on this machine."; return 1; }
    local rw=""
    cat >"/etc/systemd/system/$PANEL_UNIT.service" <<EOF
[Unit]
Description=CS2Nexus web panel
After=network.target

[Service]
User=$CS2_USER
Group=$CS2_GROUP
Environment=NEXUS_PANEL_DATA=$PANEL_DIR/data
ExecStartPre=-+$SELF panel-export
WorkingDirectory=$PANEL_DIR/app
Environment=NEXT_TELEMETRY_DISABLED=1
Environment=NODE_ENV=production
ExecStart=/usr/bin/env node --disable-warning=ExperimentalWarning server/index.js
Restart=on-failure
RestartSec=3
AmbientCapabilities=CAP_NET_BIND_SERVICE
NoNewPrivileges=true
ProtectSystem=full
ProtectHome=true
PrivateTmp=true
ReadWritePaths=$PANEL_DIR/data${rw:+ $rw}

[Install]
WantedBy=multi-user.target
EOF
    cat >"/etc/systemd/system/cs2nexus-update.service" <<EOF
[Unit]
Description=CS2Nexus: CS2 update requested from the web panel

[Service]
Type=oneshot
KillMode=process
ExecStart=$SELF panel-update
TimeoutStartSec=3h
EOF
    cat >"/etc/systemd/system/cs2nexus-update.path" <<EOF
[Unit]
Description=CS2Nexus: watch for a CS2 update request from the web panel

[Path]
PathExists=$PANEL_DIR/data/update-request
Unit=cs2nexus-update.service

[Install]
WantedBy=multi-user.target
EOF
    cat >"/etc/systemd/system/cs2nexus-restart.service" <<EOF
[Unit]
Description=CS2Nexus: scheduled server restart from the web panel

[Service]
Type=oneshot
KillMode=process
ExecStart=$SELF panel-restart
TimeoutStartSec=1h
EOF
    cat >"/etc/systemd/system/cs2nexus-restart.path" <<EOF
[Unit]
Description=CS2Nexus: watch for scheduled restart requests

[Path]
PathExistsGlob=$PANEL_DIR/data/restart-request-*
PathExistsGlob=$PANEL_DIR/data/srvctl-*
Unit=cs2nexus-restart.service

[Install]
WantedBy=multi-user.target
EOF
    cat >"/etc/systemd/system/cs2nexus-rent.service" <<EOF
[Unit]
Description=CS2Nexus: server rental jobs from the web panel

[Service]
Type=oneshot
KillMode=process
ExecStart=$SELF panel-rent
TimeoutStartSec=2h
EOF
    cat >"/etc/systemd/system/cs2nexus-rent.path" <<EOF
[Unit]
Description=CS2Nexus: watch for server rental jobs

[Path]
PathExistsGlob=$PANEL_DIR/data/rent-req-*.json
Unit=cs2nexus-rent.service

[Install]
WantedBy=multi-user.target
EOF
    systemctl daemon-reload
    systemctl enable --now cs2nexus-update.path cs2nexus-restart.path cs2nexus-rent.path >/dev/null 2>&1
}

panel_firewall_hint() {   # <port>
    command -v ufw >/dev/null 2>&1 || return 0
    ufw status 2>/dev/null | grep -q "^Status: active" || return 0
    ufw status 2>/dev/null | grep -qE "^$1(/tcp)?[[:space:]]+ALLOW" && return 0
    if confirm_yn "The firewall (ufw) is active. Open port $1/tcp for the panel? [Y/n]: " y; then ufw allow "$1/tcp" >/dev/null && ok "Port $1/tcp opened."; fi
}

panel_need_node() {   # Node.js >= 22.13 (built-in sqlite); installed from NodeSource when missing or too old
    local v
    node_ok() { command -v node >/dev/null 2>&1 && command -v npm >/dev/null 2>&1 && node -e 'const [a,b]=process.versions.node.split(".").map(Number);process.exit(a>22||(a===22&&b>=13)?0:1)' 2>/dev/null; }
    node_ok && return 0
    confirm_yn "Node.js 22.13 or newer is needed for the panel. Install Node 22 now (NodeSource, apt)? [Y/n]: " y || return 1
    info "Installing Node.js 22 ..."
    apt-get install -y ca-certificates curl gnupg >/dev/null 2>&1
    if curl -fsSL https://deb.nodesource.com/setup_22.x -o /tmp/nodesource-setup.sh 2>/dev/null && bash /tmp/nodesource-setup.sh >/dev/null 2>&1; then
        apt-get install -y nodejs >/dev/null 2>&1
    fi
    rm -f /tmp/nodesource-setup.sh
    node_ok || { v=$(node -v 2>/dev/null); err "Could not install Node.js 22 (found: ${v:-none}). Install it manually (https://nodejs.org) and try again."; return 1; }
    ok "Node.js $(node -v) ready."
}

panel_build() {   # install dependencies and build the site inside $PANEL_DIR/app (needs the npm registry once)
    local app="$PANEL_DIR/app" reg=""
    [[ -n ${NEXUS_NPM_REGISTRY:-} ]] && reg="--registry=$NEXUS_NPM_REGISTRY"
    info "Installing dependencies and building the website (first time takes a few minutes) ..."
    ( cd "$app" && NEXT_TELEMETRY_DISABLED=1 npm ci --omit=dev --no-audit --no-fund $reg >/tmp/cs2nexus-npm.log 2>&1 ) \
        || { err "npm could not install the dependencies. Is the npm registry reachable? (log: /tmp/cs2nexus-npm.log; set NEXUS_NPM_REGISTRY=<mirror> to use a mirror)"; return 1; }
    ( cd "$app" && NEXT_TELEMETRY_DISABLED=1 npm run build >>/tmp/cs2nexus-npm.log 2>&1 ) \
        || { err "The website build failed (log: /tmp/cs2nexus-npm.log)."; return 1; }
    install -d -m 755 -- "$app/.next/cache"
    chown -R root:root "$app"; chmod -R go-w "$app"
    chown -R "$CS2_USER:$CS2_GROUP" "$app/.next/cache"
    return 0
}

panel_install() {
    local tmp key first=0
    [[ -d $SHARED_ADDONS ]] || { err "The shared plugin folder does not exist yet (finish the launcher setup first)."; return 1; }
    panel_need_node || return 1
    tmp=$(mktemp -d /tmp/cs2nexus-panel.XXXXXX) || return 1
    if ! panel_payload_extract "$tmp" || [[ ! -f $tmp/app/server/index.js || ! -f $tmp/plugin/NexusLink/NexusLink.dll ]]; then
        err "This launcher file has no panel inside (damaged copy?). Use 'Maintenance -> Update launcher'."
        rm -rf --one-file-system -- "$tmp"; return 1
    fi
    panel_installed || first=1
    install -d -m 755 -- "$PANEL_DIR" "$PANEL_DIR/maps" "$PANEL_DIR/tls"
    install -d -m 750 -o "$CS2_USER" -g "$CS2_GROUP" -- "$PANEL_DIR/data"
    chown -R "$CS2_USER:$CS2_GROUP" "$PANEL_DIR/maps" "$PANEL_DIR/tls"
    rm -rf --one-file-system -- "$PANEL_DIR/app"
    mv -- "$tmp/app" "$PANEL_DIR/app" || { err "Could not place the panel files."; return 1; }
    panel_build || { err "The panel could not be built. Nothing was started."; return 1; }
    printf '%s\n' "$PANEL_VERSION" >"$PANEL_DIR/VERSION"
    if [[ ! -f $PANEL_SETTINGS ]]; then
        key=$(head -c 48 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c 40)
        jq -n --arg key "$key" --arg dir "$PANEL_DIR" \
            '{port:8080, bind:"0.0.0.0", internal_port:27500, api_key:$key, domain:"", tls_cert:"", tls_key:"", trust_proxy:false,
              servers_file:($dir+"/data/servers-public.json"), maps_dir:($dir+"/maps"), title:"CS2Nexus", session_hours:720, code_ttl:300}' >"$PANEL_SETTINGS"
        chown "root:$CS2_GROUP" "$PANEL_SETTINGS"; chmod 640 "$PANEL_SETTINGS"
    fi
    # NexusLink plugin: one shared copy for every server
    local pdst="$SHARED_ADDONS/counterstrikesharp/plugins/NexusLink"
    install -d -m 755 -o "$CS2_USER" -g "$CS2_GROUP" -- "$SHARED_ADDONS/counterstrikesharp/plugins"
    rm -rf --one-file-system -- "$pdst"; cp -a -- "$tmp/plugin/NexusLink" "$pdst" && chown -R "$CS2_USER:$CS2_GROUP" "$pdst"
    rm -rf --one-file-system -- "$tmp"
    admintools_install quiet nosync || warn "CS2Nexus AdminTools could not be installed (Admins -> AdminTools -> Install)."
    shared_update --arg n NexusLink --arg p "counterstrikesharp/plugins/NexusLink" \
        'if any(.[]; type=="object" and .path == $p) then . else . += [{name:$n, path:$p}] end' >/dev/null
    panel_export_servers
    panel_unit_write || return 1
    lock_ops 30 && { DRY_RUN=0; sync_shared_all || true; unlock_ops; }
    panel_write_all_plugin_configs
    systemctl enable "$PANEL_UNIT.service" >/dev/null 2>&1
    systemctl restart "$PANEL_UNIT.service"; sleep 1
    if panel_running; then ok "Web panel installed and running: $(panel_url)"; else err "The panel did not start. See: journalctl -u $PANEL_UNIT -n 30"; fi
    panel_firewall_hint "$(panel_get port)"
    ok "NexusLink plugin installed for every server (one shared copy)."
    if ((first || PANEL_CFG_CHANGED)); then
        warn "Restart your servers once (Restart Server) so they load NexusLink and connect to the panel."
    fi
}

panel_ctl() {   # start|stop|restart
    panel_installed || { err "The panel is not installed yet."; return 1; }
    systemctl "$1" "$PANEL_UNIT.service" && sleep 1
    if [[ $1 != stop ]]; then panel_running && ok "Panel is running: $(panel_url)" || err "The panel is not running. See the log (option 9)."
    else ok "Panel stopped."; fi
}

panel_set_port() {
    ask_num "Public port of the website (80 and 443 work too)" "$(panel_get port)" 1 65535 || return
    local p=$ANSWER
    [[ $p == "$(panel_get internal_port)" ]] && { err "That port is used by the internal plugin link."; return; }
    panel_set port "$p" && ok "Port set to $p." && panel_firewall_hint "$p"
    panel_running && systemctl restart "$PANEL_UNIT.service" && ok "Panel restarted: $(panel_url)"
}

panel_set_ip() {   # numeric address for the Join buttons (steam://connect); the shown text keeps the domain
    local cur ip; cur=$(panel_get connect_ip)
    echo "  The Join buttons need a numeric IP (Steam cannot always resolve a domain). The website keeps showing the domain."
    echo "  Current: ${cur:-(automatic: the IP of the domain)}"
    read -r -p "  Server IP (e.g. 176.120.18.9, empty = automatic): " ip || return
    ip=$(trim "$ip")
    if [[ -n $ip && ! $ip =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then err "That is not an IPv4 address."; return; fi
    panel_set connect_ip "\"$ip\"" && ok "Join IP saved: ${ip:-automatic}"
    panel_running && systemctl restart "$PANEL_UNIT.service"
}

# ---- nginx in front of the panel: http://domain (port 80) / https://domain (443) with no :8080 ----
panel_nginx_setup() {
    local d p conf=/etc/nginx/conf.d/cs2nexus-panel.conf
    d=$(panel_get domain)
    [[ -n $d ]] || { err "Set the domain first (option 1)."; return 1; }
    if ! command -v nginx >/dev/null 2>&1; then
        confirm_yn "nginx is not installed. Install it now (apt)? [Y/n]: " y || return 1
        DEBIAN_FRONTEND=noninteractive apt-get install -y nginx >/dev/null 2>&1 || { err "Could not install nginx."; return 1; }
    fi
    if ss -ltnH 2>/dev/null | awk '{print $4}' | grep -qE '[:.]80$' && ! ss -ltnpH 2>/dev/null | grep -E '[:.]80[[:space:]]' | grep -q nginx; then
        err "Port 80 is used by another program (not nginx). Stop it first, then retry."; return 1
    fi
    p=$(panel_get port)
    if [[ $p == 80 || $p == 443 || -z $p ]]; then p=8080; panel_set port 8080; fi
    cat >"$conf" <<'NGX'
# CS2Nexus web panel (managed by the launcher)
server {
    listen 80;
@V6@    server_name @DOMAIN@;
    client_max_body_size 2m;
    location / {
        proxy_pass http://127.0.0.1:@PORT@;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 60s;
    }
}
NGX
    if [[ -e /proc/net/if_inet6 ]]; then sed -i 's/^@V6@/    listen [::]:80;\n/' "$conf"; else sed -i 's/^@V6@//' "$conf"; fi
    sed -i "s/@DOMAIN@/$d/; s/@PORT@/$p/" "$conf"
    if ! nginx -t >/dev/null 2>&1; then
        err "nginx rejected the configuration:"; nginx -t 2>&1 | sed 's/^/    /'; rm -f -- "$conf"; return 1
    fi
    # the panel now only listens locally and trusts nginx's headers; TLS (if any) is handled by nginx
    panel_set bind '"127.0.0.1"'; panel_set trust_proxy true; panel_set tls_cert '""'; panel_set tls_key '""'
    panel_set nginx true; panel_set nginx_ssl false
    systemctl enable --now nginx >/dev/null 2>&1; systemctl reload nginx >/dev/null 2>&1 || systemctl restart nginx
    panel_running && systemctl restart "$PANEL_UNIT.service"
    panel_firewall_hint 80
    ok "nginx is serving the panel. Open: $(panel_url)"
    info "The old address with :$p no longer works from outside (the panel listens on 127.0.0.1 only)."
    info "Next: option 7 gives you free HTTPS."
    return 0
}

panel_nginx_ssl() {
    local d email
    [[ $(panel_get nginx) == true ]] || { err "Set up nginx first (option 6)."; return 1; }
    d=$(panel_get domain)
    read -r -p "Email for Let's Encrypt notices: " email || exit 0; email=$(trim "$email")
    [[ $email =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]] || { err "That email looks wrong."; return 1; }
    if ! command -v certbot >/dev/null 2>&1 || ! dpkg -s python3-certbot-nginx >/dev/null 2>&1; then
        DEBIAN_FRONTEND=noninteractive apt-get install -y certbot python3-certbot-nginx >/dev/null 2>&1 || { err "Could not install certbot."; return 1; }
    fi
    panel_firewall_hint 80; panel_firewall_hint 443
    if certbot --nginx -d "$d" --non-interactive --agree-tos -m "$email" --redirect; then
        panel_set nginx_ssl true
        ok "HTTPS is on and renews itself (certbot timer). Open: $(panel_url)"
    else
        err "Let's Encrypt refused. $d must point to this server and ports 80/443 must be reachable from the internet."; return 1
    fi
}

panel_nginx_off() {
    rm -f -- /etc/nginx/conf.d/cs2nexus-panel.conf
    command -v nginx >/dev/null 2>&1 && nginx -t >/dev/null 2>&1 && systemctl reload nginx >/dev/null 2>&1
    panel_set nginx false; panel_set nginx_ssl false; panel_set bind '"0.0.0.0"'; panel_set trust_proxy false
    panel_running && systemctl restart "$PANEL_UNIT.service"
    ok "nginx no longer serves the panel. Direct address: $(panel_url)"
    info "If certbot changed the nginx file earlier, that certificate is still in /etc/letsencrypt."
}

panel_domain_menu() {
    local c d email tmpd crt key host
    while :; do
        clear_screen; dsep
        printf '%s              DOMAIN AND SSL%s\n' "$BOLD" "$RESET"; dsep; echo
        d=$(panel_get domain)
        printf '  Domain    : %s\n  SSL       : %s\n  Address   : %s\n  Proxy     : %s\n\n' "${d:-none (using the server IP)}" \
            "$([[ -n $(panel_get tls_cert) ]] && echo "ON ($(panel_get tls_cert))" || echo OFF)" "$(panel_url)" \
            "$([[ $(panel_get trust_proxy) == true ]] && echo 'trusting X-Forwarded headers' || echo 'direct')"
        echo "  1) Set the domain name"
        echo "  2) Get a free SSL certificate (Let's Encrypt)"
        echo "  3) Use my own certificate files"
        echo "  4) Turn SSL off"
        echo "  5) I use a reverse proxy / Cloudflare in front (trust forwarded IP) ON / OFF"
        echo "  6) Use nginx: open the site on http://domain (no :port)  [recommended]"
        echo "  7) nginx: get free HTTPS (Let's Encrypt)"
        echo "  8) Turn nginx off (back to the direct port)"
        echo "  9) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) read -r -p "Domain (example: play.example.com, empty = remove): " d || exit 0; d=$(trim "${d,,}")
               if [[ -z $d || $d =~ ^[a-z0-9]([a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$ ]]; then panel_set domain "\"$d\"" && ok "Saved."
                   [[ -n $d ]] && info "Point the DNS A record of $d to this server's IP, then choose option 2 for SSL."
               else err "That is not a valid domain name."; fi; pause ;;
            2) d=$(panel_get domain)
               [[ $(panel_get nginx) == true ]] && { err "nginx is on: use option 7 for HTTPS instead."; pause; continue; }
               [[ -n $d ]] || { err "Set the domain first (option 1)."; pause; continue; }
               echo "  Needs: the domain already points to this server, and port 80 is free during the check."
               if ss -ltn 2>/dev/null | awk '{print $4}' | grep -qE '[:.]80$'; then err "Port 80 is in use by another program. Stop it first, then retry."; pause; continue; fi
               read -r -p "Email for Let's Encrypt notices: " email || exit 0; email=$(trim "$email")
               [[ $email =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]] || { err "That email looks wrong."; pause; continue; }
               if ! command -v certbot >/dev/null 2>&1; then
                   confirm_yn "certbot is needed. Install it now (apt)? [Y/n]: " y || continue
                   apt-get install -y certbot >/dev/null 2>&1 || { err "Could not install certbot."; pause; continue; }
               fi
               panel_firewall_hint 80
               install -d -m 755 /etc/letsencrypt/renewal-hooks/deploy
               cat >/etc/letsencrypt/renewal-hooks/deploy/cs2nexus-panel.sh <<EOF
#!/bin/sh
# copies the renewed certificate for the CS2Nexus panel and restarts it
[ "\${RENEWED_LINEAGE:-}" = "/etc/letsencrypt/live/$d" ] || exit 0
cp -L /etc/letsencrypt/live/$d/fullchain.pem $PANEL_DIR/tls/fullchain.pem
cp -L /etc/letsencrypt/live/$d/privkey.pem $PANEL_DIR/tls/privkey.pem
chown $CS2_USER:$CS2_GROUP $PANEL_DIR/tls/fullchain.pem $PANEL_DIR/tls/privkey.pem
chmod 640 $PANEL_DIR/tls/privkey.pem
systemctl restart $PANEL_UNIT.service
EOF
               chmod 755 /etc/letsencrypt/renewal-hooks/deploy/cs2nexus-panel.sh
               if certbot certonly --standalone -d "$d" --non-interactive --agree-tos -m "$email" --keep-until-expiring; then
                   RENEWED_LINEAGE="/etc/letsencrypt/live/$d" /etc/letsencrypt/renewal-hooks/deploy/cs2nexus-panel.sh 2>/dev/null
                   cp -L "/etc/letsencrypt/live/$d/fullchain.pem" "$PANEL_DIR/tls/fullchain.pem" && cp -L "/etc/letsencrypt/live/$d/privkey.pem" "$PANEL_DIR/tls/privkey.pem" \
                       && chown "$CS2_USER:$CS2_GROUP" "$PANEL_DIR/tls/"*.pem && chmod 640 "$PANEL_DIR/tls/privkey.pem"
                   panel_set tls_cert "\"$PANEL_DIR/tls/fullchain.pem\""; panel_set tls_key "\"$PANEL_DIR/tls/privkey.pem\""
                   ok "Certificate installed. It renews itself (certbot timer) and the panel restarts after each renewal."
                   if [[ $(panel_get port) != 443 ]] && confirm_yn "Use the normal HTTPS port 443 for the website? [Y/n]: " y; then panel_set port 443; panel_firewall_hint 443; fi
                   panel_running && systemctl restart "$PANEL_UNIT.service"
                   ok "Open: $(panel_url)"
               else err "Let's Encrypt refused. Check that $d points to this server and port 80 is reachable from outside."; fi
               pause ;;
            3) read -r -p "Path of the certificate file (fullchain / .crt): " crt || exit 0; read -r -p "Path of the private key file: " key || exit 0
               crt=$(trim "$crt"); key=$(trim "$key")
               if [[ -f $crt && -f $key ]] && openssl x509 -in "$crt" -noout 2>/dev/null; then
                   cp -L -- "$crt" "$PANEL_DIR/tls/fullchain.pem" && cp -L -- "$key" "$PANEL_DIR/tls/privkey.pem" \
                       && chown "$CS2_USER:$CS2_GROUP" "$PANEL_DIR/tls/"*.pem && chmod 640 "$PANEL_DIR/tls/privkey.pem"
                   panel_set tls_cert "\"$PANEL_DIR/tls/fullchain.pem\""; panel_set tls_key "\"$PANEL_DIR/tls/privkey.pem\""
                   ok "Certificate copied. Renew it yourself by repeating this option."
                   panel_running && systemctl restart "$PANEL_UNIT.service"
               else err "Could not read a valid certificate and key at those paths."; fi; pause ;;
            4) panel_set tls_cert '""'; panel_set tls_key '""'; ok "SSL is off (plain http)."; panel_running && systemctl restart "$PANEL_UNIT.service"; pause ;;
            5) if [[ $(panel_get trust_proxy) == true ]]; then panel_set trust_proxy false; ok "Direct connections only."
               else panel_set trust_proxy true; ok "X-Forwarded-For / -Proto are trusted. Only turn this on if ALL traffic comes through your proxy."; fi
               panel_running && systemctl restart "$PANEL_UNIT.service"; pause ;;
            6) panel_nginx_setup; pause ;;
            7) panel_nginx_ssl; pause ;;
            8) panel_nginx_off; pause ;;
            9|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

panel_maps_import() {   # zip file or folder with map pictures
    local src n=0 dst="$PANEL_DIR/maps"
    ask "Path of a .zip file or a folder with map pictures (empty = cancel)"; src=$(trim "$ANSWER")
    [[ -n $src ]] || return 0
    install -d -m 755 -o "$CS2_USER" -g "$CS2_GROUP" -- "$dst"
    if [[ -d $src ]]; then
        local f b
        while IFS= read -r -d '' f; do
            b=${f##*/}; [[ $b =~ ^[A-Za-z0-9_-]+\.(jpg|jpeg|png|webp|JPG|JPEG|PNG|WEBP)$ ]] || continue
            [[ -L $f ]] && continue
            install -m 644 -o "$CS2_USER" -g "$CS2_GROUP" -- "$f" "$dst/$b" && n=$((n+1))
        done < <(find "$src" -maxdepth 2 -type f -print0 2>/dev/null)
    elif [[ -f $src ]]; then
        n=$(python3 - "$src" "$dst" <<'PY'
import sys, zipfile, os, re
z, d = sys.argv[1], sys.argv[2]; n = 0; tot = 0
rx = re.compile(r"^[A-Za-z0-9_\-]+\.(jpg|jpeg|png|webp)$", re.I)
try:
    with zipfile.ZipFile(z) as zf:
        for i in zf.infolist():
            b = os.path.basename(i.filename)
            if i.is_dir() or not rx.match(b) or i.file_size > 5_000_000: continue
            tot += i.file_size
            if tot > 400_000_000: break
            with zf.open(i) as s, open(os.path.join(d, b), "wb") as o: o.write(s.read())
            n += 1
except Exception as e:
    sys.stderr.write(str(e) + "\n")
print(n)
PY
)
        n=${n:-0}
        chown -R "$CS2_USER:$CS2_GROUP" "$dst" 2>/dev/null; find "$dst" -type f -exec chmod 644 {} + 2>/dev/null
    else
        err "Not found: $src"; return 1
    fi
    ok "$n map picture(s) imported into $dst. They show up on the site at once."
}

panel_maps_help() {
    panel_maps_import_menu
}

panel_maps_import_menu() {
    local n; n=$(find "$PANEL_DIR/maps" -maxdepth 1 -type f \( -iname '*.jpg' -o -iname '*.jpeg' -o -iname '*.png' -o -iname '*.webp' \) 2>/dev/null | wc -l)
    echo
    echo "  Map pictures folder : $PANEL_DIR/maps   ($n picture(s) now)"
    echo "  The site shows the picture of the map each server is playing right now, and it follows map changes."
    echo "  Name each file like the map: de_dust2.jpg, de_mirage.png, ze_maze.jpg ... (jpg, png or webp)."
    echo "  Workshop maps use the last part of the name. Maps without a picture show a coloured card."
    echo
    echo "   1) Import pictures from a .zip file or a folder"
    echo "   2) Back"
    ask "Choose"
    [[ $ANSWER == 1 ]] && panel_maps_import
    return 0
}

# ----- voice relay (TURN): lets admins on different networks hear each other in the panel's admin voice room -----
VOICE_TURN_CONF="/etc/turnserver.conf"
voice_relay_get() { jq -r --arg k "$1" '(.voice_turn // {})[$k] // empty' "$PANEL_SETTINGS" 2>/dev/null; }
voice_relay_on() { [[ -n $(voice_relay_get secret) ]]; }

voice_relay_ports_open() {   # opens the relay ports when the ufw firewall is active
    command -v ufw >/dev/null 2>&1 || return 0
    ufw status 2>/dev/null | grep -q "^Status: active" || return 0
    ufw allow 3478/udp >/dev/null && ufw allow 3478/tcp >/dev/null && ufw allow 49160:49400/udp >/dev/null && ok "Firewall (ufw): 3478 tcp/udp and 49160-49400 udp opened."
}

voice_relay_install() {
    panel_installed || { err "Install the web panel first."; return 1; }
    local host secret port=3478
    host=$(voice_relay_get host); [[ -n $host ]] || host=$(panel_host)
    ask "Public address of this machine (domain or IP that admins can reach)" "$host" || return 1
    host=$(printf '%s' "$ANSWER" | tr -cd 'A-Za-z0-9.:-')
    [[ -n $host ]] || { err "Enter a domain or an IP address."; return 1; }
    secret=$(voice_relay_get secret)
    [[ -n $secret ]] || secret=$(head -c 48 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c 40)
    if ! command -v turnserver >/dev/null 2>&1; then
        info "Installing coturn..."
        DEBIAN_FRONTEND=noninteractive apt-get install -y coturn >/dev/null 2>&1 || { err "Could not install coturn (apt-get install coturn)."; return 1; }
    fi
    {
        echo "# written by CS2Nexus (voice relay for the panel's admin voice room)"
        echo "listening-port=$port"
        echo "fingerprint"
        echo "use-auth-secret"
        echo "static-auth-secret=$secret"
        echo "realm=$host"
        echo "min-port=49160"
        echo "max-port=49400"
        echo "total-quota=100"
        echo "no-multicast-peers"
        echo "no-cli"
        echo "no-tcp-relay"
        echo "no-tlsv1"
        echo "no-tlsv1_1"
        echo "denied-peer-ip=0.0.0.0-0.255.255.255"
        echo "denied-peer-ip=10.0.0.0-10.255.255.255"
        echo "denied-peer-ip=127.0.0.0-127.255.255.255"
        echo "denied-peer-ip=169.254.0.0-169.254.255.255"
        echo "denied-peer-ip=172.16.0.0-172.31.255.255"
        echo "denied-peer-ip=192.168.0.0-192.168.255.255"
    } >"$VOICE_TURN_CONF"
    chmod 640 "$VOICE_TURN_CONF"; chown root:turnserver "$VOICE_TURN_CONF" 2>/dev/null || true
    [[ -f /etc/default/coturn ]] && sed -i 's/^#\?TURNSERVER_ENABLED=.*/TURNSERVER_ENABLED=1/' /etc/default/coturn
    systemctl enable coturn >/dev/null 2>&1; systemctl restart coturn >/dev/null 2>&1
    sleep 1
    systemctl is-active --quiet coturn || { err "coturn did not start. See: journalctl -u coturn -n 30"; return 1; }
    voice_relay_ports_open
    panel_set voice_turn "$(jq -n --arg h "$host" --argjson p "$port" --arg s "$secret" '{host:$h, port:$p, secret:$s}')" || { err "Could not save the relay settings."; return 1; }
    panel_ctl restart >/dev/null 2>&1
    ok "Voice relay is on: $host:$port"
    echo "  If admins still cannot hear each other, also open these ports at your hosting provider's firewall:"
    echo "    3478 TCP+UDP and 49160-49400 UDP (to this machine)."
}

voice_relay_remove() {
    systemctl disable --now coturn >/dev/null 2>&1
    panel_installed && panel_set voice_turn null >/dev/null 2>&1 && panel_ctl restart >/dev/null 2>&1
    ok "Voice relay turned off (the coturn package stays installed)."
}

voice_relay_menu() {
    local c
    while :; do
        clear_screen; dsep
        printf '%s          VOICE RELAY (admin voice room)%s\n' "$BOLD" "$RESET"; dsep; echo
        echo "  Admins talk to each other directly. When they are on different networks (home internet, mobile data,"
        echo "  or when public STUN servers are blocked) the connection stays on 'connecting'. A relay on this machine fixes that."
        echo
        if voice_relay_on; then printf '  Status : %sON%s   (%s:%s)\n\n' "$GREEN" "$RESET" "$(voice_relay_get host)" "$(voice_relay_get port)"; else printf '  Status : %sOFF%s\n\n' "$YELLOW" "$RESET"; fi
        echo "  1) Turn on / reconfigure (installs coturn)"
        echo "  2) Turn off"
        echo "  3) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) voice_relay_install; pause ;;
            2) voice_relay_remove; pause ;;
            3|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

panel_menu() {
    local c st
    while :; do
        clear_screen; dsep
        printf '%s              WEB PANEL%s\n' "$BOLD" "$RESET"; dsep; echo
        if panel_installed; then
            panel_running && st="${GREEN}RUNNING${RESET}" || st="${RED}STOPPED${RESET}"
            printf '  Status  : %s   (panel %s, built into this launcher: %s)\n' "$st" "$(cat "$PANEL_DIR/VERSION" 2>/dev/null || echo ?)" "$PANEL_VERSION"
            printf '  Address : %s\n' "$(panel_url)"
            printf '  Plugin  : NexusLink (one shared copy; each server reports to http://127.0.0.1:%s)\n\n' "$(panel_get internal_port)"
        else
            echo "  Not installed yet. Players log in with !getcode in the game, then see their servers,"
            echo "  play time and matches on a website that runs on this machine."
            echo
        fi
        echo "  1) Install / update the panel (also installs the NexusLink plugin on all servers)"
        echo "  2) Start"
        echo "  3) Stop"
        echo "  4) Restart"
        echo "  5) Change the port"
        echo "  6) Domain and SSL"
        echo "  7) Map pictures"
        echo "  8) Re-write the plugin settings of all servers (after changing ports)"
        echo "  9) Show the panel log"
        echo " 10) Remove the panel (data and pictures are kept)"
        echo " 11) Join IP (numeric address used by the Join buttons)"
        echo " 12) Voice relay (lets admins on different networks use the admin voice room)"
        echo " 13) Back"
        echo
        read -r -p "Select: " c || exit 0
        case "$(trim "$c")" in
            1) panel_install; pause ;;
            2) panel_ctl start; pause ;;
            3) panel_ctl stop; pause ;;
            4) panel_ctl restart; pause ;;
            5) panel_installed && panel_set_port || err "Install the panel first."; pause ;;
            6) panel_installed && panel_domain_menu || { err "Install the panel first."; pause; } ;;
            7) panel_maps_help; pause ;;
            8) panel_installed && { panel_write_all_plugin_configs; ok "Done."; ((PANEL_CFG_CHANGED)) && warn "Restart the servers (or run 'css_plugins reload NexusLink' in their console)."; } || err "Install the panel first."; pause ;;
            9) journalctl -u "$PANEL_UNIT" -n 40 --no-pager 2>/dev/null || err "No log available."; pause ;;
            10) if confirm_yn "Stop and remove the panel program? Players' history in $PANEL_DIR/data stays. [y/N]: " n; then
                    systemctl disable --now "$PANEL_UNIT.service" >/dev/null 2>&1
                    systemctl disable --now cs2nexus-update.path cs2nexus-restart.path cs2nexus-rent.path >/dev/null 2>&1
                    rm -f -- "/etc/systemd/system/$PANEL_UNIT.service" /etc/systemd/system/cs2nexus-update.service /etc/systemd/system/cs2nexus-update.path /etc/systemd/system/cs2nexus-restart.service /etc/systemd/system/cs2nexus-restart.path /etc/systemd/system/cs2nexus-rent.service /etc/systemd/system/cs2nexus-rent.path; systemctl daemon-reload
                    rm -rf --one-file-system -- "$PANEL_DIR/app"
                    panel_write_all_plugin_configs disabled 2>/dev/null
                    ok "Panel removed. NexusLink is switched off in every server's settings (remove it in Plugins if you like)."
                fi; pause ;;
            11) panel_installed && panel_set_ip || err "Install the panel first."; pause ;;
            12) panel_installed && voice_relay_menu || { err "Install the panel first."; pause; } ;;
            13|q|Q) return ;;
            *) err "Invalid option."; sleep 1 ;;
        esac
    done
}

